# --- IMPORTS ---
import os as _os_early
# Fix Windows + Postgres en castellano: libpq devuelve mensajes con tildes en cp1252
# y psycopg2 falla con UnicodeDecodeError al conectar (byte 0xf3, etc.).
# Forzamos UTF-8 y locale C en el servidor antes de cualquier intento de conexion.
_os_early.environ.setdefault('PGCLIENTENCODING', 'UTF8')
# Neon (pooler o host directo) rechaza lc_messages en PGOPTIONS.
_url_early = (
    (_os_early.environ.get('DATABASE_URL') or _os_early.environ.get('SQLALCHEMY_DATABASE_URI') or '')
    .lower()
)
_neon_pg = 'neon.tech' in _url_early
_pgopt_actual = _os_early.environ.get('PGOPTIONS', '')
if not _neon_pg and 'lc_messages' not in _pgopt_actual:
    _os_early.environ['PGOPTIONS'] = (_pgopt_actual + ' -c lc_messages=C').strip()
elif _neon_pg and 'lc_messages' in _pgopt_actual:
    _os_early.environ['PGOPTIONS'] = ' '.join(
        p for p in _pgopt_actual.split() if 'lc_messages' not in p
    ).strip()


def _bootstrap_venv_si_arranque_local():
    """
    En PC de desarrollo: `python app.py` suele usar el Python de Windows (sin Flask).
    Si existe .venv y este archivo se ejecuta como script, relanzar con .venv/Scripts/python.exe.
    No afecta gunicorn/pytest (importan app con __name__ != '__main__').
  """
    if _os_early.environ.get('LHEXIA_SKIP_VENV_BOOTSTRAP') == '1':
        return
    if __name__ != '__main__':
        return
    import sys as _sys_boot

    _root = _os_early.path.dirname(_os_early.path.abspath(__file__))
    _venv_py = _os_early.path.join(_root, '.venv', 'Scripts', 'python.exe')
    if not _os_early.path.isfile(_venv_py):
        return
    if _os_early.path.normcase(_sys_boot.executable) == _os_early.path.normcase(_venv_py):
        return
    import subprocess as _sp_boot

    raise SystemExit(_sp_boot.call([_venv_py, __file__, *_sys_boot.argv[1:]]))


_bootstrap_venv_si_arranque_local()

