def _leer_jsonl(path, limit=1000):
    out = []
    if not os.path.exists(path):
        return out
    try:
        with open(path, 'r', encoding='utf-8') as f:
            for line in f:
                line = (line or '').strip()
                if not line:
                    continue
                try:
                    rec = json.loads(line)
                    if isinstance(rec, dict):
                        out.append(rec)
                except Exception:
                    continue
    except Exception:
        return []
    if limit and len(out) > limit:
        out = out[-limit:]
    return out


def _parse_lhexia_datetime(value):
    if isinstance(value, datetime):
        return value
    raw = (str(value or '').strip())
    if not raw:
        return None
    for fmt in (
        '%Y-%m-%d %H:%M:%S',
        '%Y-%m-%dT%H:%M:%S',
        '%Y-%m-%d %H:%M',
        '%Y-%m-%d',
    ):
        try:
            return datetime.strptime(raw[:len(fmt)], fmt)
        except Exception:
            continue
    try:
        return datetime.fromisoformat(raw)
    except Exception:
        return None


def _map_lead_eventos(limit=3000):
    eventos = _leer_jsonl(_ruta_landing_lead_eventos(), limit=limit)
    by_lead = {}
    for ev in eventos:
        lid = str(ev.get('lead_id') or '').strip()
        if not lid:
            continue
        by_lead[lid] = ev
    return by_lead


