@app.context_processor
def inject_session_uptime():
    """Expone el inicio de sesion (epoch ms) para el contador de minutos en la topbar."""
    iso = session.get('login_at') if session else None
    if not iso:
        return {'session_login_ms': None}
    try:
        dt = datetime.fromisoformat(iso)
        return {'session_login_ms': int(dt.timestamp() * 1000)}
    except Exception:
        return {'session_login_ms': None}


@app.context_processor
def inject_public_seo_urls():
    """Base canónica e imagen OG absoluta (respeta PUBLIC_SITE_URL) para plantillas públicas."""
    try:
        base = _public_site_base_url()
        return {
            'public_site_url': base,
            'public_og_image_url': f'{base}/static/img/lhexia-brand-approved.png?v={LHEXIA_ASSET_VERSION}',
        }
    except Exception:
        return {
            'public_site_url': 'https://www.lhexia.cl',
            'public_og_image_url': f'https://www.lhexia.cl/static/img/lhexia-brand-approved.png?v={LHEXIA_ASSET_VERSION}',
        }


@app.before_request
def _autocompletar_login_at():
    """Si un usuario ya autenticado no tiene login_at en sesion (p. ej. tras reinicio del server),
    lo seteamos a 'ahora' para que el contador de minutos no quede vacio."""
    try:
        if current_user.is_authenticated and not session.get('login_at'):
            session['login_at'] = datetime.utcnow().isoformat()
    except Exception:
        pass


