from flask_login import LoginManager

login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = 'login'  # nombre de la ruta de login
login_manager.login_message = "Debes iniciar sesión para acceder a esta página."
login_manager.login_message_category = "warning"


@login_manager.unauthorized_handler
def _login_manager_no_autorizado():
    """Evita perder ?next= y devuelve JSON en APIs."""
    if (request.path or '').startswith('/api/'):
        return jsonify({'ok': False, 'error': 'login_required'}), 401
    nxt = (request.full_path or request.path or '').strip()
    if nxt in ('', '/login', '/login?'):
        return redirect(url_for('login'))
    return redirect(url_for('login', next=nxt.rstrip('?')))


@login_manager.user_loader
def load_user(user_id):
    try:
        uid = int(user_id)
    except (TypeError, ValueError):
        return None
    ultimo_error = None
    for intento in range(3):
        try:
            usuario = db.session.get(Usuario, uid)
            if usuario is not None:
                return usuario
            if intento == 0:
                db.session.rollback()
                continue
            return None
        except (OperationalError, SATimeoutError, SQLAlchemyError) as exc:
            ultimo_error = exc
            db.session.rollback()
            if intento == 0:
                time.sleep(float(os.getenv('LOGIN_USER_RETRY_SEC', '0.15')))
                continue
        except Exception as exc:
            ultimo_error = exc
            db.session.rollback()
            break
    if ultimo_error is not None:
        app.logger.warning('No se pudo rehidratar la sesion para uid=%s: %s', uid, ultimo_error)
    return None

