def _enrol_resumen_almacen_codigo(a):
    tid = id_almacen_tienda()
    bid = id_almacen_bodega()
    if tid and a.id == tid:
        return 'tienda'
    if bid and a.id == bid:
        return 'bodega'
    return ''


def _enrol_almacenes_ui():
    if not _tablas_inventario_almacen_existen():
        return []
    rows = Almacen.query.filter_by(activo=True).order_by(Almacen.nombre.asc()).all()
    out = []
    for a in rows:
        out.append({'id': a.id, 'nombre': (a.nombre or a.codigo or '').strip() or f'#{a.id}', 'rol': _enrol_resumen_almacen_codigo(a)})
    return out


def _enrol_permite_traslado_ui():
    return _tablas_inventario_almacen_existen() and Almacen.query.filter_by(activo=True).count() >= 2


def _enrol_normalizar_codigo(c):
    return (c or '').strip()


def _enrol_buscar_producto_por_codigo(codigo):
    c = _enrol_normalizar_codigo(codigo)
    if not c:
        return None
    p = Producto.query.filter(Producto.codigo_barra == c).first()
    if p:
        return p
    p = Producto.query.filter(Producto.codigo_interno == c).first()
    if p:
        return p
    return _producto_por_codigo_chilemat_escaneo(c.upper())


def _enrol_codigo_barra_ocupado(codigo, excluir_producto_id=None):
    c = _enrol_normalizar_codigo(codigo)
    if not c:
        return False
    q = Producto.query.filter(Producto.codigo_barra == c)
    if excluir_producto_id:
        q = q.filter(Producto.id != int(excluir_producto_id))
    return q.first() is not None


def _enrol_linea_conteo_sumar(sesion_id, producto_id, delta):
    if not _tablas_enrolamiento_existen():
        return
    sid = int(sesion_id)
    pid = int(producto_id)
    try:
        d = int(delta)
    except (TypeError, ValueError):
        return
    if d == 0:
        return
    line = EnrolamientoTomaLinea.query.filter_by(sesion_id=sid, producto_id=pid).first()
    if not line:
        line = EnrolamientoTomaLinea(sesion_id=sid, producto_id=pid, conteo=0)
        db.session.add(line)
    line.conteo = int(line.conteo or 0) + d


def _enrol_serializar_producto(producto, sesion_id=None, sesion_almacen_id=None):
    tid = id_almacen_tienda()
    bid = id_almacen_bodega()
    mult = _tablas_inventario_almacen_existen()
    if mult:
        st_t = int(stock_producto_en_almacen(producto.id, tid) or 0) if tid else int(producto.stock or 0)
        st_b = int(stock_producto_en_almacen(producto.id, bid) or 0) if bid else 0
    else:
        st_t = int(producto.stock or 0)
        st_b = 0

    conteo = 0
    if sesion_id and _tablas_enrolamiento_existen():
        line = EnrolamientoTomaLinea.query.filter_by(sesion_id=int(sesion_id), producto_id=producto.id).first()
        if line:
            conteo = int(line.conteo or 0)

    stock_rows = []
    nom_sesion = ''
    if mult:
        for a in Almacen.query.filter_by(activo=True).order_by(Almacen.nombre.asc()).all():
            cant = int(stock_producto_en_almacen(producto.id, a.id) or 0)
            rol = _enrol_resumen_almacen_codigo(a)
            es_tienda = rol == 'tienda'
            es_sesion = bool(sesion_almacen_id and int(sesion_almacen_id) == int(a.id))
            if es_sesion:
                nom_sesion = (a.nombre or a.codigo or '').strip()
            stock_rows.append({
                'nombre': (a.nombre or a.codigo or '').strip() or f'#{a.id}',
                'cantidad': cant,
                'rol': rol,
                'es_tienda_pos': es_tienda,
                'es_sesion': es_sesion,
            })

    return {
        'id': producto.id,
        'nombre': producto.nombre,
        'categoria': producto.categoria or '',
        'subcategoria': producto.subcategoria or '',
        'codigo_chilemat': (producto.codigo_chilemat or '').strip(),
        'codigo_interno': (producto.codigo_interno or '').strip(),
        'imagen_url': (producto.imagen_url or '').strip(),
        'precio_venta': float(producto.precio_venta or 0),
        'precio_compra': float(producto.precio_compra or 0),
        'precio_mayoreo': float(producto.precio_mayoreo or 0),
        'stock_tienda': st_t,
        'stock_bodega': st_b,
        'stock_total_maestro': int(producto.stock or 0),
        'stock_por_almacen': stock_rows,
        'conteo_sesion': conteo,
        'stock_almacen_sesion_nombre': nom_sesion,
    }


def _enrol_sesion_get_or_404(sid):
    if not _tablas_enrolamiento_existen():
        return None
    return EnrolamientoTomaSesion.query.get(int(sid))


def _enrol_destino_almacen(sesion_row, id_almacen_destino):
    if id_almacen_destino:
        try:
            aid = int(id_almacen_destino)
        except (TypeError, ValueError):
            aid = None
        if aid:
            a = Almacen.query.filter_by(id=aid, activo=True).first()
            if a:
                return aid
    if sesion_row and sesion_row.id_almacen:
        return int(sesion_row.id_almacen)
    aid_def = id_almacen_tienda()
    return aid_def


def stock_disponible_venta_tienda(producto):
    """Stock usable en POS: solo almacén TIENDA (fuente única definitiva)."""
    if not producto:
        return 0
    aid = id_almacen_tienda()
    if aid and _tablas_inventario_almacen_existen():
        v = stock_producto_en_almacen(producto.id, aid)
        return int(v or 0)
    return int(producto.stock or 0)


def stock_disponible_bodega(producto):
    """Stock en almacén BODEGA (0 si no hay tablas multi-almacén)."""
    if not producto:
        return 0
    aid = id_almacen_bodega()
    if aid and _tablas_inventario_almacen_existen():
        v = stock_producto_en_almacen(producto.id, aid)
        return int(v or 0)
    return int(producto.stock or 0)


def _venta_validar_stock_bodega_para_cobro(venta):
    """
    Cobro con retiro en bodega: no se descuenta tienda al pagar; debe haber stock en bodega
    para (consumo línea − ya despachado por voz antes del cobro).
    """
    faltantes = []
    if not venta:
        return faltantes
    for d in list(venta.detalles or []):
        try:
            producto = d.producto or Producto.query.get(d.id_producto)
            if not producto:
                faltantes.append('Producto no encontrado en una línea del vale.')
                continue
            factor = _factor_venta_a_stock(producto)
            consumo = int(round((d.cantidad or 0) * factor))
            if consumo <= 0:
                faltantes.append(f'{producto.nombre}: conversión de cantidad inválida.')
                continue
            ya_bod = _venta_consumo_ya_despachado_bodega(venta, d.id)
            necesita_bod = max(0, consumo - ya_bod)
            if necesita_bod <= 0:
                continue
            disp_b = stock_disponible_bodega(producto)
            if disp_b < necesita_bod:
                faltantes.append(
                    f'{producto.nombre} (disponible bodega: {disp_b}, requerido al cobrar: {necesita_bod})'
                )
        except Exception as ex:
            db.session.rollback()
            app.logger.exception('Validación stock bodega cobro línea %s: %s', getattr(d, 'id', None), ex)
            faltantes.append('No se pudo validar stock en bodega para una línea.')
    return faltantes


def stock_tienda_por_producto_ids(ids):
    """Mapa id_producto -> stock en TIENDA (fuente única definitiva)."""
    ids = [int(x) for x in ids if x is not None]
    if not ids:
        return {}
    aid = id_almacen_tienda()
    if aid and _tablas_inventario_almacen_existen():
        rows = (
            db.session.query(StockPorAlmacen.id_producto, StockPorAlmacen.cantidad)
            .filter(
                StockPorAlmacen.id_almacen == aid,
                StockPorAlmacen.id_producto.in_(ids),
            )
            .all()
        )
        por_id = {int(pid): int(cant or 0) for pid, cant in rows}
        faltan = [i for i in ids if i not in por_id]
        if faltan:
            # Si no hay fila en TIENDA, se considera 0.
            for pid in faltan:
                por_id[int(pid)] = 0
        return por_id
    prods = Producto.query.filter(Producto.id.in_(ids)).all()
    return {p.id: int(p.stock or 0) for p in prods}


def stock_bodega_por_producto_ids(ids):
    """Mapa id_producto -> stock en BODEGA."""
    ids = [int(x) for x in ids if x is not None]
    if not ids:
        return {}
    bid = id_almacen_bodega()
    if bid and _tablas_inventario_almacen_existen():
        rows = (
            db.session.query(StockPorAlmacen.id_producto, StockPorAlmacen.cantidad)
            .filter(
                StockPorAlmacen.id_almacen == bid,
                StockPorAlmacen.id_producto.in_(ids),
            )
            .all()
        )
        por_id = {int(pid): int(cant or 0) for pid, cant in rows}
        for pid in ids:
            por_id.setdefault(int(pid), 0)
        return por_id
    return {int(i): 0 for i in ids}


def stock_tienda_bodega_por_producto_ids(ids):
    """Tienda + bodega en una consulta a stock_por_almacen (POS / búsqueda enriquecida)."""
    ids = [int(x) for x in ids if x is not None]
    if not ids:
        return {}, {}
    tid = id_almacen_tienda()
    bid = id_almacen_bodega()
    almacenes = [a for a in (tid, bid) if a]
    stock_t = {int(i): 0 for i in ids}
    stock_b = {int(i): 0 for i in ids}
    if almacenes and _tablas_inventario_almacen_existen():
        rows = (
            db.session.query(
                StockPorAlmacen.id_producto,
                StockPorAlmacen.id_almacen,
                StockPorAlmacen.cantidad,
            )
            .filter(
                StockPorAlmacen.id_producto.in_(ids),
                StockPorAlmacen.id_almacen.in_(almacenes),
            )
            .all()
        )
        for pid, aid, cant in rows:
            pid = int(pid)
            q = int(cant or 0)
            if tid and int(aid) == int(tid):
                stock_t[pid] = q
            elif bid and int(aid) == int(bid):
                stock_b[pid] = q
        return stock_t, stock_b
    if not tid and not bid:
        prods = Producto.query.filter(Producto.id.in_(ids)).all()
        return {p.id: int(p.stock or 0) for p in prods}, stock_b
    return stock_t, stock_b


def _fmt_clp_busqueda_pos(valor):
    return f"${int(round(float(valor or 0))):,}".replace(",", ".")


def _producto_marca_desde_row(row, cols):
    for key in ("marca", "fabricante", "categoria", "subcategoria"):
        if key in cols:
            txt = (row.get(key) or "").strip()
            if txt:
                return txt[:64]
    return ""


def _precio_lista_desde_row_producto(row):
    return max(float(row.get("precio_venta") or 0), float(row.get("precio_mayoreo") or 0))


def _badges_busqueda_pos(item, precio_min, precio_max):
    badges = []
    st_t = int(item.get("stock_tienda") or 0)
    st_b = int(item.get("stock_bodega") or 0)
    precio = float(item.get("precio") or 0)
    if st_t > 0:
        badges.append({"tipo": "tienda", "label": "En mostrador"})
    elif st_b > 0:
        badges.append({"tipo": "bodega", "label": "Retiro bodega"})
    else:
        badges.append({"tipo": "sin_stock", "label": "Sin stock"})
    if precio_max > precio_min:
        if precio <= precio_min:
            badges.append({"tipo": "economica", "label": "Alternativa económica"})
        elif precio >= precio_max:
            badges.append({"tipo": "premium", "label": "Gama premium"})
    return badges


def _stock_ui_producto(producto):
    """Resumen consistente para vistas de inventario: maestro vs almacenes."""
    total_maestro = int(producto.stock or 0)
    if not producto or not _tablas_inventario_almacen_existen():
        return {
            'tienda': total_maestro,
            'bodega': 0,
            'total_almacenes': total_maestro,
            'total_maestro': total_maestro,
            'desajustado': False,
        }
    tid = id_almacen_tienda()
    bid = id_almacen_bodega()
    tienda = int(stock_producto_en_almacen(producto.id, tid) or 0) if tid else 0
    bodega = int(stock_producto_en_almacen(producto.id, bid) or 0) if bid else 0
    try:
        total_almacenes = int(db.session.execute(
            text("SELECT COALESCE(SUM(cantidad), 0) FROM stock_por_almacen WHERE id_producto = :p"),
            {"p": int(producto.id)},
        ).scalar() or 0)
    except Exception:
        db.session.rollback()
        total_almacenes = total_maestro
    return {
        'tienda': tienda,
        'bodega': bodega,
        'total_almacenes': total_almacenes,
        'total_maestro': total_maestro,
        'desajustado': total_almacenes != total_maestro,
    }


def _adjuntar_stock_ui(productos):
    for producto in productos or []:
        producto.stock_ui = _stock_ui_producto(producto)
    return productos


def precio_efectivo_pos_producto(producto):
    """Precio unitario para POS y filtros: mayor entre precio_venta y precio_mayoreo."""
    if not producto:
        return 0.0
    return max(float(producto.precio_venta or 0), float(producto.precio_mayoreo or 0))


def descontar_stock_venta_tienda(producto, consumo_stock):
    """
    Descuenta stock de venta (almacén TIENDA). Mantiene productos.stock como suma por almacén.
    Devuelve mensaje de error o None.
    """
    return _stock_service.descontar_stock_venta_tienda(producto, consumo_stock)


def incrementar_stock_venta_tienda(producto, consumo_stock):
    """Revierte un descuento de venta en TIENDA (opuesto a descontar_stock_venta_tienda)."""
    return _stock_service.incrementar_stock_venta_tienda(producto, consumo_stock)


def descontar_stock_venta_bodega(producto, consumo_stock):
    """Descuenta stock en almacén BODEGA (retiro físico). Devuelve error str o None."""
    return _stock_service.descontar_stock_venta_bodega(producto, consumo_stock)


def incrementar_stock_venta_bodega(producto, consumo_stock):
    """Revierte salida de bodega (anulación de retiro o corrección)."""
    return _stock_service.incrementar_stock_venta_bodega(producto, consumo_stock)


def _venta_metodo_pago_vacio(venta):
    mp = getattr(venta, 'metodo_pago', None)
    if mp is None:
        return True
    return str(mp).strip() == ''


def _venta_stock_ya_descontado(venta):
    """True si la mercadería ya salió de inventario tienda para esta venta."""
    st = (venta.estado or '').strip()
    if st in ('Abierta', 'Anulada'):
        return False
    if st == 'Pagado':
        return True
    if st == 'Pendiente':
        return not _venta_metodo_pago_vacio(venta)
    return False


def _revertir_operaciones_venta_antes_borrar(venta, usuario_nombre):
    """
    Desvincula cotización, revierte inventario/kardex y ajustes de cliente antes de borrar la venta.
    Retorna (True, None) o (False, mensaje_error).
    """
    usr = (usuario_nombre or '')[:100] or 'Sistema'
    vid = venta.id

    for cot in Cotizacion.query.filter_by(venta_id=vid).all():
        cot.venta_id = None
        if (cot.estado or '').strip() == 'Convertida':
            cot.estado = 'Vigente'
            cot.fecha_estado = datetime.utcnow()

    if not _venta_stock_ya_descontado(venta):
        return True, None

    detalles = list(venta.detalles or [])
    for d in detalles:
        producto = Producto.query.get(d.id_producto)
        if not producto:
            return False, f"No se encontró el producto en línea de venta #{d.id}."
        factor = _factor_venta_a_stock(producto)
        consumo = int(round((d.cantidad or 0) * factor))
        if consumo <= 0:
            continue
        err = incrementar_stock_venta_tienda(producto, consumo)
        if err:
            return False, err
        registrar_movimiento_kardex(
            producto.id,
            'ENTRADA',
            consumo,
            f"Reversa eliminación venta #{vid}",
            usuario=usr,
            id_almacen=id_almacen_tienda() or 1,
            referencia_tipo='venta_reversa',
            referencia_id=vid,
            stock_saldo=None,
        )

    if venta.metodo_pago == 'Credito' and venta.cliente_id:
        cli = Cliente.query.get(venta.cliente_id)
        if cli:
            mt = float(venta.monto_total or 0)
            cli.saldo_deudor = max(0.0, float(cli.saldo_deudor or 0) - mt)

    if (venta.estado or '').strip() == 'Pagado':
        sf = float(venta.saldo_favor_usado or 0)
        if sf > 0 and venta.cliente_id:
            _aplicar_mov_saldo_favor(
                venta.cliente_id,
                None,
                'CREDITO',
                sf,
                f'Reversa eliminación venta #{vid}',
            )

    return True, None


def _monto_medios_pago_reversa_venta_pagada(venta):
    """Neto cobrado fuera de saldo a favor (para registrar egreso de caja al revertir la venta)."""
    sf = float(venta.saldo_favor_usado or 0)
    total_sin_favor = max(0.0, float(venta.monto_total or 0) - sf)
    met_l = (venta.metodo_pago or '').strip().lower()
    if met_l == 'efectivo':
        por_ticket = float(venta.monto_recibido or 0) - float(venta.vuelto or 0)
        return max(0.0, por_ticket if por_ticket > 0 else total_sin_favor)
    return total_sin_favor


def _registrar_movimiento_caja_devolucion_venta(venta, usuario_registro):
    """
    Registra un egreso en movimiento_caja al eliminar una venta Pagada (no crédito).
    Retorna texto de advertencia o None si todo OK / no aplica.
    """
    if (venta.estado or '').strip() != 'Pagado':
        return None
    mp = (venta.metodo_pago or '').strip()
    if not mp or mp == 'Credito':
        return None
    cid = venta.caja_id
    if not cid:
        return 'La venta no tiene caja asociada; no se registró egreso en movimiento de caja.'
    monto = _monto_medios_pago_reversa_venta_pagada(venta)
    if monto <= 0:
        return 'sin_monto_medios'
    usr = (usuario_registro or '')[:80] or 'Sistema'
    resp = usr[:120]
    concepto = f"Devolución / reversa venta #{venta.id} ({mp})"
    db.session.add(
        MovimientoCaja(
            caja_id=int(cid),
            tipo='Egreso',
            concepto=concepto[:255],
            monto=float(monto),
            responsable_retiro=resp,
            usuario_registro=usr,
        )
    )
    return None


def aplicar_stock_desde_catalogo_a_tienda(producto):
    """
    Tras importar/editar productos.stock masivamente: todo el saldo del catálogo se interpreta como TIENDA.
    Reinicia BODEGA a 0 para ese producto y recalcula el total como suma por almacén.
    """
    if not producto or not _tablas_inventario_almacen_existen():
        return
    aid_t = id_almacen_tienda()
    aid_b = id_almacen_bodega()
    if not aid_t:
        return
    try:
        tgt = int(producto.stock or 0)
    except (TypeError, ValueError):
        tgt = 0
    if aid_b:
        fijar_stock_almacen(producto.id, aid_b, 0)
    fijar_stock_almacen(producto.id, aid_t, tgt)
    _refrescar_stock_total_producto(producto)


