# --- VENTA ---
class Venta(db.Model):
    __tablename__ = 'ventas'

    id = db.Column(db.Integer, primary_key=True)
    fecha = db.Column(db.DateTime, default=db.func.current_timestamp())
    monto_total = db.Column(db.Float, nullable=False, default=0.0)
    usuario = db.Column(db.String(50))
    estado = db.Column(db.String(20), default="Pendiente")
    
    # --- NUEVOS CAMPOS TRIBUTARIOS ---
    tipo_documento = db.Column(db.String(20), default="Boleta")  # Boleta o Factura (UI / lógica interna)
    # Folio oficial del DTE timbrado (SII); no duplicar en otros campos
    nro_documento = db.Column(db.Integer, nullable=True)
    neto = db.Column(db.Float, default=0.0)
    iva = db.Column(db.Float, default=0.0)
    # Facturación electrónica: cola asíncrona si falla SII (p. ej. PENDIENTE_ENVIO)
    dte_tipo = db.Column(db.Integer, nullable=True)  # 33 factura afecta, 39 boleta afecta, etc.
    dte_estado = db.Column(db.String(32), nullable=True)
    dte_track_id = db.Column(db.String(50), nullable=True)
    caf_id = db.Column(db.Integer, db.ForeignKey('cafs.id'), nullable=True)
    # ---------------------------------

    metodo_pago = db.Column(db.String(20), nullable=True)
    monto_recibido = db.Column(db.Float, nullable=True)
    vuelto = db.Column(db.Float, nullable=True)
    saldo_favor_usado = db.Column(db.Float, nullable=False, default=0.0)
    prioridad = db.Column(db.Integer)

    motivo_anulacion = db.Column(db.String(500), nullable=True)
    fecha_anulacion = db.Column(db.DateTime, nullable=True)
    usuario_anulacion = db.Column(db.String(80), nullable=True)
    punto_retiro = db.Column(db.String(30), nullable=True, default='Bodega')
    cotizacion_origen_id = db.Column(db.Integer, nullable=True)
    # Plan de cuotas: días corridos desde el cobro en caja. NULL = crédito sin plan de cuotas.
    credito_plan_codigo = db.Column(db.String(32), nullable=True)
    # Despacho físico desde bodega (Voice-to-Action); el vale sigue Pendiente hasta cobro en caja.
    bodega_despacho_estado = db.Column(db.String(20), nullable=True)  # SALIDA_PARCIAL | DESPACHADO
    bodega_despacho_json = db.Column(db.Text, nullable=True)  # JSON: detalle_id -> consumo stock ya salido de bodega
    bodega_despacho_ultimo_at = db.Column(db.DateTime, nullable=True)  # último despacho voz exitoso (worker alertas)
    # Plataforma retiro bodega (post-cobro): preparación + entregas parciales (stock bodega baja al registrar retiro).
    bodega_preparacion_estado = db.Column(db.String(24), nullable=True)
    bodega_preparacion_usuario = db.Column(db.String(80), nullable=True)
    bodega_preparacion_at = db.Column(db.DateTime, nullable=True)
    # Fase 3 — SLA bodega: timestamps para medir tiempos de preparación.
    bodega_preparacion_cobrado_at = db.Column(db.DateTime, nullable=True)
    bodega_preparacion_cerrado_at = db.Column(db.DateTime, nullable=True)
    # Fase 2 — sugerido preparar (solo informativo; vale Pendiente + retiro Bodega; no reserva stock).
    bodega_sugerido_preparar = db.Column(db.SmallInteger, nullable=False, default=0, server_default='0')
    bodega_sugerido_preparar_at = db.Column(db.DateTime, nullable=True)
    bodega_sugerido_preparar_usuario = db.Column(db.String(80), nullable=True)

    # Relaciones
    caja_id = db.Column(db.Integer, db.ForeignKey('caja.id'), nullable=True)
    caja = db.relationship('Caja', back_populates='ventas')

    cliente_id = db.Column(db.Integer, db.ForeignKey('clientes.id'), nullable=True)
    cliente = db.relationship('Cliente', backref='ventas')
    caf = db.relationship('Caf', foreign_keys=[caf_id], backref=db.backref('ventas', lazy='dynamic'))

    detalles = db.relationship(
        'DetalleVenta',
        backref='venta',
        lazy=True,
        cascade="all, delete-orphan"
    )

    # Lógica Tributaria: Desglose de IVA (Chile 19% — única fuente: desglosar_iva_clp)
    def desglosar_iva(self):
        """Calcula Neto e IVA desde monto_total bruto (Decimal, ROUND_HALF_UP)."""
        from core.domain.shared.iva_chile import desglosar_iva_clp

        bruto = int(round(float(self.monto_total or 0)))
        neto, iva, total = desglosar_iva_clp(bruto)
        self.neto = float(neto)
        self.iva = float(iva)
        self.monto_total = float(total)

    # Método para recalcular el total automáticamente
    def recalcular_total(self):
        if self.id:
            bruto = int(_monto_cobro_venta_bruto_sql(self.id) or 0)
        else:
            bruto = int(_venta_bruto_desde_detalles_lineas(self.detalles) or 0)
        self.monto_total = float(bruto)
        self.desglosar_iva()

    @property
    def total(self):
        return self.monto_total

    @total.setter
    def total(self, value):
        self.monto_total = float(value) if value else 0.0
        self.desglosar_iva() # Sincroniza impuestos al cambiar el total


