def _seo_extract_jsonld_types(doc):
    types = []
    for node in doc.xpath('//script[@type="application/ld+json"]'):
        raw = (node.text or '').strip()
        if not raw:
            continue
        try:
            parsed = json.loads(raw)
        except Exception:
            continue
        stack = [parsed]
        while stack:
            item = stack.pop()
            if isinstance(item, dict):
                atype = item.get('@type')
                if isinstance(atype, list):
                    types.extend([str(x) for x in atype if x])
                elif atype:
                    types.append(str(atype))
                if '@graph' in item and isinstance(item['@graph'], list):
                    stack.extend(item['@graph'])
            elif isinstance(item, list):
                stack.extend(item)
    return types


def _seo_score_snapshot(snapshot):
    score = 0
    if int(snapshot.get('status_code') or 0) == 200:
        score += 25
    title = snapshot.get('title') or ''
    meta = snapshot.get('meta_description') or ''
    h1 = snapshot.get('h1') or ''
    canonical = snapshot.get('canonical_url') or ''
    if 35 <= len(title) <= 70:
        score += 15
    elif title:
        score += 8
    if 80 <= len(meta) <= 180:
        score += 15
    elif meta:
        score += 8
    if h1:
        score += 10
    if canonical:
        score += 10
    if not snapshot.get('noindex'):
        score += 10
    if int(snapshot.get('schema_count') or 0) > 0:
        score += 10
    if int(snapshot.get('word_count') or 0) >= 180:
        score += 10
    if int(snapshot.get('internal_links') or 0) >= 2:
        score += 5
    return min(score, 100)


def _seo_fetch_internal_response(path):
    start = time.perf_counter()
    with app.test_client() as client:
        resp = client.get(path)
    elapsed_ms = int((time.perf_counter() - start) * 1000)
    return resp, elapsed_ms


def _seo_parse_page_snapshot(path):
    resp, elapsed_ms = _seo_fetch_internal_response(path)
    html_text = resp.get_data(as_text=True) if int(resp.status_code or 0) == 200 else ''
    title = ''
    meta_description = ''
    canonical_url = ''
    h1 = ''
    robots_meta = ''
    noindex = False
    schema_count = 0
    has_faq_schema = False
    has_org_schema = False
    has_website_schema = False
    has_breadcrumb_schema = False
    word_count = 0
    internal_links = 0

    if html_text:
        try:
            doc = lxml_html.fromstring(html_text)
            titles = doc.xpath('//title/text()')
            title = _web_analytics_clean(titles[0] if titles else '', 255)
            desc = doc.xpath('//meta[translate(@name,"ABCDEFGHIJKLMNOPQRSTUVWXYZ","abcdefghijklmnopqrstuvwxyz")="description"]/@content')
            meta_description = _web_analytics_clean(desc[0] if desc else '', 320)
            canon = doc.xpath('//link[translate(@rel,"ABCDEFGHIJKLMNOPQRSTUVWXYZ","abcdefghijklmnopqrstuvwxyz")="canonical"]/@href')
            canonical_url = _web_analytics_clean(canon[0] if canon else '', 500)
            h1s = doc.xpath('//h1')
            h1 = _web_analytics_clean(h1s[0].text_content() if h1s else '', 255)
            robots_vals = doc.xpath('//meta[translate(@name,"ABCDEFGHIJKLMNOPQRSTUVWXYZ","abcdefghijklmnopqrstuvwxyz")="robots"]/@content')
            robots_meta = _web_analytics_clean(robots_vals[0] if robots_vals else '', 180)
            noindex = 'noindex' in (robots_meta or '').lower()
            types = _seo_extract_jsonld_types(doc)
            schema_count = len(types)
            types_low = {t.lower() for t in types}
            has_faq_schema = 'faqpage' in types_low
            has_org_schema = 'organization' in types_low
            has_website_schema = 'website' in types_low
            has_breadcrumb_schema = 'breadcrumblist' in types_low
            body_text = " ".join(doc.xpath('//body//text()'))
            word_count = len(re.findall(r'[A-Za-zÀ-ÿ0-9]{2,}', body_text))
            public_domain = _web_analytics_domain(_public_site_base_url())
            for href in doc.xpath('//a[@href]/@href'):
                href = (href or '').strip()
                if not href or href.startswith('#') or href.startswith('mailto:') or href.startswith('tel:'):
                    continue
                if href.startswith('/'):
                    internal_links += 1
                    continue
                if public_domain and _web_analytics_domain(href).endswith(public_domain):
                    internal_links += 1
        except Exception:
            app.logger.exception('No se pudo parsear snapshot SEO de %s', path)

    snapshot = {
        'path': path,
        'public_url': _absolute_public_url(path),
        'status_code': int(resp.status_code or 0),
        'response_ms': elapsed_ms,
        'title': title,
        'meta_description': meta_description,
        'canonical_url': canonical_url,
        'h1': h1,
        'robots_meta': robots_meta,
        'noindex': noindex,
        'schema_count': schema_count,
        'has_faq_schema': has_faq_schema,
        'has_org_schema': has_org_schema,
        'has_website_schema': has_website_schema,
        'has_breadcrumb_schema': has_breadcrumb_schema,
        'word_count': word_count,
        'internal_links': internal_links,
    }
    snapshot['seo_score'] = _seo_score_snapshot(snapshot)
    return snapshot


def _seo_fetch_site_files():
    sitemap_resp, _ = _seo_fetch_internal_response('/sitemap.xml')
    robots_resp, _ = _seo_fetch_internal_response('/robots.txt')
    sitemap_text = sitemap_resp.get_data(as_text=True) if int(sitemap_resp.status_code or 0) == 200 else ''
    robots_text = robots_resp.get_data(as_text=True) if int(robots_resp.status_code or 0) == 200 else ''

    sitemap_count = 0
    if sitemap_text:
        try:
            root = etree.fromstring(sitemap_text.encode('utf-8'))
            sitemap_count = len(root.xpath('//*[local-name()="url"]'))
        except Exception:
            sitemap_count = sitemap_text.count('<url>')
    return {
        'sitemap_ok': int(sitemap_resp.status_code or 0) == 200,
        'sitemap_url_count': sitemap_count,
        'robots_ok': int(robots_resp.status_code or 0) == 200,
        'robots_allows_home': 'Allow: /' in robots_text,
    }


def _seo_organic_metrics_map(days=7):
    since = datetime.now() - timedelta(days=max(1, int(days or 7)))
    sessions = WebAnalyticsSession.query.filter(
        WebAnalyticsSession.started_at >= since,
        WebAnalyticsSession.medium == 'organic',
        WebAnalyticsSession.is_bot == False,
    ).all()
    conv_session_ids = {
        c.session_id for c in WebAnalyticsConversion.query.filter(WebAnalyticsConversion.created_at >= since).all()
        if c.session_id
    }
    by_path = defaultdict(lambda: {'sessions': 0, 'conversions': 0})
    for sess in sessions:
        path = (sess.landing_path or '/').strip() or '/'
        by_path[path]['sessions'] += 1
        if sess.id in conv_session_ids:
            by_path[path]['conversions'] += 1
    totals = {
        'sessions': sum(v['sessions'] for v in by_path.values()),
        'conversions': sum(v['conversions'] for v in by_path.values()),
    }
    return by_path, totals


def _run_seo_snapshot():
    if not _asegurar_tablas_seo_monitor():
        return {'ok': False, 'message': 'No se pudieron asegurar tablas SEO'}
    _seed_seo_keyword_targets()

    snapshot_date = date.today()
    organic_by_path, organic_totals = _seo_organic_metrics_map(days=7)
    page_rows = []
    for page in _seo_target_pages():
        snap = _seo_parse_page_snapshot(page['path'])
        snap['organic_sessions_7d'] = int(organic_by_path.get(page['path'], {}).get('sessions', 0))
        snap['organic_conversions_7d'] = int(organic_by_path.get(page['path'], {}).get('conversions', 0))
        row = SeoPageDailySnapshot.query.filter_by(snapshot_date=snapshot_date, path=page['path']).first()
        if row is None:
            row = SeoPageDailySnapshot(snapshot_date=snapshot_date, path=page['path'])
            db.session.add(row)
        for key, value in snap.items():
            setattr(row, key, value)
        row.checked_at = datetime.now()
        page_rows.append(row)

    site_files = _seo_fetch_site_files()
    avg_score = round(sum(int(r.seo_score or 0) for r in page_rows) / len(page_rows), 1) if page_rows else 0.0
    noindex_pages = sum(1 for r in page_rows if r.noindex)
    site_row = SeoSiteDailySnapshot.query.filter_by(snapshot_date=snapshot_date).first()
    if site_row is None:
        site_row = SeoSiteDailySnapshot(snapshot_date=snapshot_date, public_base_url=_public_site_base_url())
        db.session.add(site_row)
    site_row.public_base_url = _public_site_base_url()
    site_row.sitemap_ok = site_files['sitemap_ok']
    site_row.sitemap_url_count = int(site_files['sitemap_url_count'] or 0)
    site_row.robots_ok = site_files['robots_ok']
    site_row.robots_allows_home = bool(site_files['robots_allows_home'])
    site_row.tracked_pages = len(page_rows)
    site_row.avg_page_score = avg_score
    site_row.noindex_pages = noindex_pages
    site_row.organic_sessions_7d = int(organic_totals['sessions'])
    site_row.organic_conversions_7d = int(organic_totals['conversions'])
    site_row.checked_at = datetime.now()
    db.session.commit()
    return {'ok': True, 'pages': len(page_rows), 'avg_score': avg_score}


def _latest_keyword_metric_map():
    out = {}
    metrics = SeoKeywordDailyMetric.query.order_by(
        SeoKeywordDailyMetric.keyword_target_id.asc(),
        SeoKeywordDailyMetric.snapshot_date.desc(),
        SeoKeywordDailyMetric.id.desc(),
    ).all()
    for item in metrics:
        if item.keyword_target_id not in out:
            out[item.keyword_target_id] = item
    return out


def _asegurar_tabla_cafs_y_columnas_ventas_fe():
    """Tabla `cafs` + columnas DTE en `ventas` (facturación electrónica Fase 1)."""
    if app.config.get('_FE_PHASE1_OK'):
        return True
    try:
        Caf.__table__.create(bind=db.engine, checkfirst=True)
        insp = sa_inspect(db.engine)
        tables = set(insp.get_table_names())
        if 'ventas' not in tables:
            return False
        cols = {c['name'] for c in insp.get_columns('ventas')}
        dn = (db.engine.dialect.name or '').lower()
        cambios = False
        columnas = (
            ('dte_tipo', 'INTEGER NULL', 'INTEGER NULL'),
            ('dte_estado', 'VARCHAR(32) NULL', 'VARCHAR(32) NULL'),
            ('dte_track_id', 'VARCHAR(50) NULL', 'VARCHAR(50) NULL'),
            ('caf_id', 'INTEGER NULL', 'INTEGER NULL'),
        )
        for col_name, pg_sql, my_sql in columnas:
            if col_name in cols:
                continue
            if dn == 'postgresql':
                db.session.execute(
                    text(f'ALTER TABLE ventas ADD COLUMN IF NOT EXISTS {col_name} {pg_sql}')
                )
            else:
                db.session.execute(text(f'ALTER TABLE ventas ADD COLUMN {col_name} {my_sql}'))
            cambios = True
        if cambios:
            db.session.commit()
        app.config['_FE_PHASE1_OK'] = True
        return True
    except Exception as ex:
        db.session.rollback()
        app.logger.warning('No se pudo asegurar tabla cafs / columnas FE en ventas: %s', ex)
        return False


def _fecha_base_cuotas_credito(dt):
    if dt is None:
        return date.today()
    if hasattr(dt, 'date'):
        return dt.date()
    return dt


def _distribuir_monto_cuotas_clp(total, n):
    tot = int(round(float(total or 0)))
    if n <= 0 or tot <= 0:
        return [0] * max(0, n)
    base = tot // n
    rem = tot % n
    out = [base] * n
    out[-1] = base + rem
    return out


def _registrar_cuotas_credito_venta(venta, plan_codigo, fecha_base_dt):
    """Genera cuotas 30/60/90 días desde el cobro; elimina cuotas previas de la misma venta."""
    dias = PLANES_CUOTA_CREDITO_DIAS.get(plan_codigo)
    if not dias or not venta or not venta.id:
        return
    VentaCuotaCredito.query.filter_by(venta_id=venta.id).delete(synchronize_session=False)
    base_d = _fecha_base_cuotas_credito(fecha_base_dt)
    montos = _distribuir_monto_cuotas_clp(venta.monto_total, len(dias))
    for i, (dias_plazo, monto) in enumerate(zip(dias, montos), start=1):
        if monto <= 0:
            continue
        fv = base_d + timedelta(days=int(dias_plazo))
        db.session.add(
            VentaCuotaCredito(
                venta_id=venta.id,
                nro_cuota=i,
                dias_plazo=int(dias_plazo),
                fecha_vencimiento=fv,
                monto=float(monto),
                monto_pagado=0.0,
                estado='Pendiente',
            )
        )


def _sql_cuota_saldo_pendiente():
    """Saldo CLP aún no cubierto en la fila de cuota (monto - monto_pagado)."""
    return func.coalesce(VentaCuotaCredito.monto, 0) - func.coalesce(VentaCuotaCredito.monto_pagado, 0)


def _cuota_saldo_pendiente_row(cq):
    m = float(cq.monto or 0)
    mp = float(getattr(cq, 'monto_pagado', None) or 0)
    return max(0.0, float(int(round(m - mp))))


def _aplicar_abono_cascada_cuotas_cliente(cliente, monto_aplicar):
    """
    Aplica el abono a las cuotas abiertas del cliente, de la más antigua a la más reciente
    (por fecha_vencimiento e id). Actualiza monto_pagado y estado Pagada/Parcial.
    Retorna líneas de texto para el comentario del abono.
    """
    monto_aplicar = float(int(round(float(monto_aplicar or 0))))
    if monto_aplicar <= 0 or not cliente:
        return []
    cuotas = (
        VentaCuotaCredito.query.join(Venta, Venta.id == VentaCuotaCredito.venta_id)
        .filter(
            Venta.cliente_id == cliente.id,
            Venta.metodo_pago == 'Credito',
            or_(Venta.estado.is_(None), Venta.estado != 'Anulada'),
        )
        .order_by(VentaCuotaCredito.fecha_vencimiento.asc(), VentaCuotaCredito.id.asc())
        .all()
    )
    rem = monto_aplicar
    lineas = []
    for cq in cuotas:
        if rem <= 0:
            break
        pend = _cuota_saldo_pendiente_row(cq)
        if pend <= 0:
            continue
        x = min(rem, pend)
        mp_new = float(cq.monto_pagado or 0) + float(x)
        mtot = float(cq.monto or 0)
        cq.monto_pagado = min(mtot, float(int(round(mp_new))))
        if cq.monto_pagado + 0.5 >= mtot:
            cq.monto_pagado = mtot
            cq.estado = 'Pagada'
        else:
            cq.estado = 'Parcial'
        rem -= x
        lineas.append(f'Cuota {cq.nro_cuota} (Venta #{cq.venta_id}): ${x:,.0f}'.replace(',', '.'))
    return lineas


def _cobranza_env_int(name, default):
    try:
        v = int(float((os.getenv(name) or str(default)).strip()))
        return max(0, min(v, 365))
    except (TypeError, ValueError):
        return default


def _cobranza_dias_horizonte_default():
    return _cobranza_env_int('COBRANZA_DIAS_AVISO', 7)


def _cobranza_mora_dias_atras_default():
    return _cobranza_env_int('COBRANZA_MORA_DIAS_ATRAS', 90)


def _telefono_whatsapp_chile_digits(telefono):
    raw = ''.join(ch for ch in (telefono or '') if ch.isdigit())
    if not raw:
        return ''
    if raw.startswith('56'):
        return raw
    return '56' + raw


def _cobranza_mensaje_cuota(cliente_nombre, nro_cuota, fecha_venc, monto_pend, venta_id):
    fv = fecha_venc.strftime('%d/%m/%Y') if fecha_venc else '—'
    mtxt = f'${int(round(float(monto_pend))):,}'.replace(',', '.')
    nombre = (cliente_nombre or 'cliente').strip() or 'cliente'
    return (
        f'Estimado/a {nombre}, le recordamos su cuota n°{int(nro_cuota or 0)} '
        f'del documento #{int(venta_id)} con vencimiento {fv}. Monto pendiente: {mtxt}. '
        f'Ante cualquier duda puede responder este mensaje. Gracias.'
    )


def _cobranza_cuotas_pendientes_filas(hoy, dias_horizonte, mora_atras_dias):
    """Cuotas con saldo > 0, vencimiento entre (hoy - mora) y (hoy + horizonte), venta a crédito."""
    hoy = hoy or date.today()
    sup = hoy + timedelta(days=int(dias_horizonte))
    inf = hoy - timedelta(days=int(mora_atras_dias))
    pend = _sql_cuota_saldo_pendiente()
    log_hoy = aliased(CobranzaRecordatorioWhatsappLog)
    rows = (
        db.session.query(VentaCuotaCredito, Venta, Cliente, log_hoy.id)
        .select_from(VentaCuotaCredito)
        .join(Venta, Venta.id == VentaCuotaCredito.venta_id)
        .join(Cliente, Cliente.id == Venta.cliente_id)
        .outerjoin(
            log_hoy,
            and_(
                log_hoy.venta_cuota_credito_id == VentaCuotaCredito.id,
                log_hoy.fecha_envio == hoy,
            ),
        )
        .filter(
            Venta.metodo_pago == 'Credito',
            or_(Venta.estado.is_(None), Venta.estado != 'Anulada'),
            pend > 0.01,
            VentaCuotaCredito.fecha_vencimiento <= sup,
            VentaCuotaCredito.fecha_vencimiento >= inf,
        )
        .order_by(VentaCuotaCredito.fecha_vencimiento.asc(), VentaCuotaCredito.id.asc())
        .all()
    )
    out = []
    for cq, venta, cliente, log_id_hoy in rows:
        pendiente = _cuota_saldo_pendiente_row(cq)
        wa_digits = _telefono_whatsapp_chile_digits(cliente.telefono)
        out.append(
            {
                'cuota': cq,
                'venta_id': venta.id,
                'cliente_nombre': cliente.nombre,
                'cliente_id': cliente.id,
                'telefono': cliente.telefono,
                'wa_digits': wa_digits,
                'pendiente': pendiente,
                'ya_enviado_hoy': log_id_hoy is not None,
                'mensaje': _cobranza_mensaje_cuota(
                    cliente.nombre, cq.nro_cuota, cq.fecha_vencimiento, pendiente, venta.id
                ),
            }
        )
    return out


def _cobranza_sin_enviar_hoy_count(dias_horizonte=None, mora_atras_dias=None):
    hoy = date.today()
    d = dias_horizonte if dias_horizonte is not None else _cobranza_dias_horizonte_default()
    m = mora_atras_dias if mora_atras_dias is not None else _cobranza_mora_dias_atras_default()
    filas = _cobranza_cuotas_pendientes_filas(hoy, d, m)
    return sum(1 for f in filas if not f['ya_enviado_hoy'])


def _cobranza_dispatch_cron_secret():
    """Token compartido para cron (sin cookie de sesión)."""
    return (os.getenv('COBRANZA_DISPATCH_CRON_SECRET') or os.getenv('WHATSAPP_DISPATCH_CRON_SECRET') or '').strip()


def _observabilidad_cron_secret():
    """Bearer para jobs periódicos de snapshot SEO y purge de telemetría."""
    return (os.getenv('OBSERVABILIDAD_CRON_SECRET') or '').strip() or _cobranza_dispatch_cron_secret()


def _wa_cloud_config():
    return _whatsapp_service.wa_cloud_config()


def _whatsapp_cloud_send_text(to_e164_digits, body):
    return _whatsapp_service.whatsapp_cloud_send_text(to_e164_digits, body)


def _plan_cuotas_credito_valido(raw):
    s = (raw or '').strip()
    return s if s in PLANES_CUOTA_CREDITO_DIAS else ''


def _mensaje_resumen_plan_cuotas(plan_codigo):
    """Texto corto para flashes / UI."""
    c = (plan_codigo or '').strip()
    msgs = {
        '30_60_90': '3 cuotas a 30, 60 y 90 días corridos desde el cobro',
        'sem_4': '4 cuotas semanales (+7 a +28 días desde el cobro)',
        'sem_8': '8 cuotas semanales (+7 a +56 días desde el cobro)',
        'quin_4': '4 cuotas quincenales (+15 a +60 días desde el cobro)',
        'quin_6': '6 cuotas quincenales (+15 a +90 días desde el cobro)',
        'mens_6': '6 cuotas mensuales (+30 a +180 días desde el cobro)',
    }
    return msgs.get(c, c or '—')


