@app.route('/gerencia/registro-horas', methods=['GET', 'POST'])
@login_required
@permisos_required('ver_gerencia', 'panel_gerencia', 'gestionar_usuarios')
def gerencia_registro_horas():
    if not _usuario_autorizado_lhexia_interno():
        flash('Acceso restringido al módulo interno LhexIA.', 'warning')
        return redirect(url_for('inicio'))
    path = _ruta_registro_horas_csv()
    if request.method == 'POST':
        fecha = (request.form.get('fecha') or '').strip()
        rol = (request.form.get('rol') or '').strip()
        horas_raw = (request.form.get('horas') or '').strip()
        tema = (request.form.get('tema') or '').strip()
        referencia = (request.form.get('referencia') or '').strip()
        notas = (request.form.get('notas') or '').strip()
        if not re.match(r'^\d{4}-\d{2}-\d{2}$', fecha):
            flash('Fecha inválida (use AAAA-MM-DD).', 'danger')
            return redirect(url_for('gerencia_registro_horas'))
        try:
            datetime.strptime(fecha, '%Y-%m-%d')
        except ValueError:
            flash('Fecha inválida.', 'danger')
            return redirect(url_for('gerencia_registro_horas'))
        if rol not in ('desarrollador', 'ia_cursor', 'mixto'):
            flash('Rol inválido.', 'danger')
            return redirect(url_for('gerencia_registro_horas'))

        def _one_line(s, max_len):
            return ' '.join((s or '').splitlines()).strip()[:max_len]

        tema = _one_line(tema, 500)
        referencia = _one_line(referencia, 240)
        notas = _one_line(notas, 2000)
        if len(tema) < 2:
            flash('El tema es obligatorio (mínimo 2 caracteres).', 'danger')
            return redirect(url_for('gerencia_registro_horas'))
        horas_cell = ''
        if horas_raw:
            try:
                hv = float(horas_raw.replace(',', '.'))
                if hv < 0 or hv > 999:
                    raise ValueError()
                horas_cell = f'{hv:g}'
            except ValueError:
                flash('Horas inválidas (número entre 0 y 999; puede usar coma decimal).', 'danger')
                return redirect(url_for('gerencia_registro_horas'))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        new_file = not os.path.exists(path)
        with open(path, 'a', newline='', encoding='utf-8') as f:
            w = csv.writer(f)
            if new_file:
                w.writerow(['fecha', 'rol', 'horas', 'tema', 'referencia', 'notas'])
            w.writerow([fecha, rol, horas_cell, tema, referencia, notas])
        flash('Registro agregado al CSV del proyecto.', 'success')
        return redirect(url_for('gerencia_registro_horas'))
    ctx = _cargar_registro_horas_desde_csv()
    ctx['rh_fecha_default'] = date.today().isoformat()
    return render_template('gerencia_registro_horas.html', **ctx)


def _build_seo_monitor_dashboard():
    """
    Dashboard SEO local-only.

    Importante: esta vista NO debe llamar APIs externas en tiempo real
    (Search Console, providers SEO, scraping remoto, etc.). Solo consume
    snapshots y métricas ya persistidas localmente para garantizar latencia cero.
    """
    _asegurar_tablas_seo_monitor()
    _seed_seo_keyword_targets()
    latest_site = SeoSiteDailySnapshot.query.order_by(
        SeoSiteDailySnapshot.snapshot_date.desc(),
        SeoSiteDailySnapshot.id.desc(),
    ).first()
    latest_date = latest_site.snapshot_date if latest_site else None
    page_rows = []
    if latest_date:
        page_rows = SeoPageDailySnapshot.query.filter_by(snapshot_date=latest_date).order_by(
            SeoPageDailySnapshot.seo_score.desc(),
            SeoPageDailySnapshot.path.asc(),
        ).all()

    keyword_targets = SeoKeywordTarget.query.filter_by(active=True).order_by(
        SeoKeywordTarget.priority.desc(),
        SeoKeywordTarget.keyword.asc(),
    ).all()
    latest_metric_map = _latest_keyword_metric_map()
    keyword_rows = []
    for target in keyword_targets:
        metric = latest_metric_map.get(target.id)
        keyword_rows.append({
            'target': target,
            'metric': metric,
            'status': (
                'alto' if metric and metric.current_position and metric.current_position <= 3 else
                'medio' if metric and metric.current_position and metric.current_position <= 10 else
                'sin_dato' if not metric or metric.current_position is None else
                'bajo'
            )
        })

    issues = []
    for row in page_rows:
        if row.status_code != 200:
            issues.append({'path': row.path, 'issue': f'HTTP {row.status_code}'})
        if not row.title:
            issues.append({'path': row.path, 'issue': 'Sin title'})
        if not row.meta_description:
            issues.append({'path': row.path, 'issue': 'Sin meta description'})
        if not row.canonical_url:
            issues.append({'path': row.path, 'issue': 'Sin canonical'})
        if row.noindex:
            issues.append({'path': row.path, 'issue': 'Meta robots noindex'})
    issues = issues[:12]
    alerts = []
    if not latest_site:
        alerts.append({
            'severity': 'crit',
            'title': 'Sin snapshot SEO reciente',
            'detail': 'El dashboard todavía no tiene una foto técnica persistida del sitio.',
        })
    else:
        if not latest_site.sitemap_ok:
            alerts.append({
                'severity': 'crit',
                'title': 'Sitemap con problemas',
                'detail': 'La última corrida no pudo validar correctamente el sitemap público.',
            })
        if not latest_site.robots_ok:
            alerts.append({
                'severity': 'warn',
                'title': 'robots.txt requiere revisión',
                'detail': 'La última corrida no marcó `robots.txt` como saludable.',
            })
        if float(latest_site.avg_page_score or 0) < 75:
            alerts.append({
                'severity': 'warn',
                'title': 'Score SEO promedio bajo',
                'detail': f"El score promedio del sitio está en {round(float(latest_site.avg_page_score or 0), 1)}.",
            })
        if int(latest_site.noindex_pages or 0) > 0:
            alerts.append({
                'severity': 'warn',
                'title': 'Hay páginas noindex',
                'detail': f"Se detectaron {int(latest_site.noindex_pages or 0)} páginas con `noindex`.",
            })
        if int(latest_site.organic_sessions_7d or 0) >= 20 and int(latest_site.organic_conversions_7d or 0) == 0:
            alerts.append({
                'severity': 'warn',
                'title': 'Tráfico orgánico sin conversión',
                'detail': f"Hay {int(latest_site.organic_sessions_7d or 0)} sesiones orgánicas 7d y 0 conversiones registradas.",
            })
    weak_pages = [row for row in page_rows if int(row.seo_score or 0) < 70]
    if weak_pages:
        alerts.append({
            'severity': 'warn',
            'title': 'Páginas con score débil',
            'detail': f"{len(weak_pages)} páginas están bajo score 70 en el snapshot más reciente.",
        })
    high_priority_keywords = [
        row for row in keyword_rows
        if (row['target'].priority or '').upper() == 'ALTA' and row['status'] in ('bajo', 'sin_dato')
    ]
    if high_priority_keywords:
        alerts.append({
            'severity': 'warn',
            'title': 'Keywords críticas sin tracción suficiente',
            'detail': f"{len(high_priority_keywords)} keywords prioritarias siguen fuera de top 10 o sin dato.",
        })
    if not alerts:
        alerts.append({
            'severity': 'good',
            'title': 'Sin alertas SEO críticas',
            'detail': 'La última corrida muestra una base técnica estable para seguir iterando contenido y ranking.',
        })

    snapshots = SeoSiteDailySnapshot.query.order_by(SeoSiteDailySnapshot.snapshot_date.desc()).limit(14).all()
    snapshots.reverse()
    chart_labels = [s.snapshot_date.strftime('%d/%m') for s in snapshots]
    chart_scores = [float(s.avg_page_score or 0) for s in snapshots]
    chart_organic = [int(s.organic_sessions_7d or 0) for s in snapshots]

    organic_top = sorted(
        page_rows,
        key=lambda x: (int(x.organic_conversions_7d or 0), int(x.organic_sessions_7d or 0), int(x.seo_score or 0)),
        reverse=True,
    )[:8]

    summary = {
        'snapshot_date': latest_date,
        'tracked_pages': int(latest_site.tracked_pages or 0) if latest_site else 0,
        'avg_score': float(latest_site.avg_page_score or 0) if latest_site else 0.0,
        'sitemap_url_count': int(latest_site.sitemap_url_count or 0) if latest_site else 0,
        'sitemap_ok': bool(latest_site.sitemap_ok) if latest_site else False,
        'robots_ok': bool(latest_site.robots_ok) if latest_site else False,
        'organic_sessions_7d': int(latest_site.organic_sessions_7d or 0) if latest_site else 0,
        'organic_conversions_7d': int(latest_site.organic_conversions_7d or 0) if latest_site else 0,
        'noindex_pages': int(latest_site.noindex_pages or 0) if latest_site else 0,
    }
    return {
        'seo_summary': summary,
        'seo_page_rows': page_rows,
        'seo_keyword_rows': keyword_rows,
        'seo_alerts': alerts[:6],
        'seo_issues': issues,
        'seo_chart_labels': chart_labels,
        'seo_chart_scores': chart_scores,
        'seo_chart_organic': chart_organic,
        'seo_organic_top': organic_top,
    }


