def _fetch_vales_riesgo_meta_desde_vista(horas_umbral, limit=250):
    """
    Filas de vista_vales_riesgo_despacho con horas_desde_ref >= umbral.
    Requiere ejecutar sql/2026_05_08_vista_vales_riesgo_despacho_*.sql en la BD.
    """
    if not _vista_vales_riesgo_despacho_existe():
        return []
    sql = text(
        """
        SELECT venta_id, horas_desde_ref, ref_despacho_o_emision, bodega_despacho_estado, vendedor
        FROM vista_vales_riesgo_despacho
        WHERE horas_desde_ref >= :h
        ORDER BY ref_despacho_o_emision ASC
        LIMIT :lim
        """
    )
    rows = db.session.execute(sql, {'h': float(horas_umbral), 'lim': int(limit)}).fetchall()
    out = []
    for r in rows:
        out.append(
            {
                'venta_id': int(r[0]),
                'horas_desde_ref': float(r[1]) if r[1] is not None else None,
                'ref_despacho_o_emision': r[2],
                'bodega_despacho_estado': r[3],
                'vendedor': (r[4] or '').strip() if r[4] is not None else None,
            }
        )
    return out


def _buscar_cliente_por_telefono_loose(digits):
    d = ''.join(c for c in (digits or '') if c.isdigit())
    if len(d) < 8:
        return None
    for c in Cliente.query.filter(Cliente.telefono.isnot(None)).all():
        cd = ''.join(ch for ch in (c.telefono or '') if ch.isdigit())
        if not cd:
            continue
        if cd.endswith(d[-9:]) or d.endswith(cd[-9:]) or cd == d:
            return c
    return None


def _buscar_productos_texto_stock(qtext, limit=5):
    q = (qtext or '').strip()
    if len(q) < 2:
        return []
    like = f'%{q.lower()}%'
    return (
        Producto.query.filter(
            Producto.activo == True,
            or_(
                db.func.lower(Producto.nombre).like(like),
                db.func.lower(db.func.coalesce(Producto.codigo_barra, '')).like(like),
                db.func.lower(db.func.coalesce(Producto.codigo_interno, '')).like(like),
            ),
        )
        .order_by(Producto.stock.desc(), Producto.nombre.asc())
        .limit(limit)
        .all()
    )


# proceso de agregar productos a venta abierta desde punto de venta........................................

def _producto_por_codigo_chilemat_escaneo(cnorm: str):
    """Chilemat en ficha sin prefijo; etiquetas/factura a veces traen INT-."""
    if not cnorm:
        return None
    producto = (
        Producto.query.filter(
            Producto.codigo_chilemat.isnot(None),
            db.func.upper(db.func.trim(Producto.codigo_chilemat)) == cnorm,
        )
        .first()
    )
    if producto:
        return producto
    if cnorm.startswith('INT-'):
        alt = cnorm[4:].strip()
        if alt:
            return (
                Producto.query.filter(
                    Producto.codigo_chilemat.isnot(None),
                    db.func.upper(db.func.trim(Producto.codigo_chilemat)) == alt,
                )
                .first()
            )
    return None


def _pos_buscar_producto_por_codigo(codigo):
    """Resuelve producto por código de barras, interno o chilemat (misma lógica que el escáner POS)."""
    if not codigo:
        return None
    producto = None
    if codigo:
        cnorm = codigo.strip().upper()
        producto = (
            Producto.query.filter(db.func.upper(db.func.trim(Producto.codigo_barra)) == cnorm)
            .first()
        )
    if not producto and codigo:
        cnorm = codigo.strip().upper()
        producto = (
            Producto.query.filter(
                Producto.codigo_interno.isnot(None),
                db.func.upper(db.func.trim(Producto.codigo_interno)) == cnorm,
            )
            .first()
        )
    if not producto and codigo:
        cnorm = codigo.strip().upper()
        producto = _producto_por_codigo_chilemat_escaneo(cnorm)
    return producto


def _pos_cantidad_producto_en_venta(venta, producto_id):
    """Unidades de venta del producto ya cargadas en el vale abierto."""
    if not venta:
        return 0
    total = 0
    for d in list(venta.detalles or []):
        if int(d.id_producto) == int(producto_id):
            total += int(d.cantidad or 0)
    return total


def _pos_puede_sumar_unidad(producto, venta, caja_id=None, a_pedido=False):
    """
    Valida si cabe +1 unidad considerando stock tienda, otros vales Pendiente/Abierta
    y lo ya cargado en el vale actual.
    Retorna (ok, mensaje, error_code).
    """
    if not producto:
        return False, 'Producto no válido.', 'no_producto'
    if a_pedido:
        from services.pos_busqueda_service import pos_permite_venta_verde

        if not pos_permite_venta_verde():
            return False, 'Venta en verde no está habilitada para esta empresa.', 'venta_verde_off'
        return True, None, None
    factor = _factor_venta_a_stock(producto)
    if factor <= 0:
        return False, f'Conversión inválida para {producto.nombre}.', 'conversion'
    qty_prev = _pos_cantidad_producto_en_venta(venta, producto.id)
    cons_new = int(round((qty_prev + 1) * factor))
    disp = stock_disponible_venta_tienda(producto)
    excluir = getattr(venta, 'id', None)
    cid = caja_id or (getattr(venta, 'caja_id', None) if venta else None)
    comprometido = _stock_service.consumo_stock_comprometido_tienda_producto(
        producto, excluir_venta_id=excluir, caja_id=cid
    )
    if disp >= comprometido + cons_new:
        return True, None, None
    max_u = int(max(0, disp - comprometido) / factor) if factor else max(0, disp - comprometido)
    vpend = _stock_service.venta_pendiente_con_producto(
        producto.id, excluir_venta_id=excluir, caja_id=cid
    )
    if vpend:
        qty_en_vale = 0
        for d in list(vpend.detalles or []):
            if int(d.id_producto) == int(producto.id):
                qty_en_vale += int(d.cantidad or 0)
        return False, (
            f'«{producto.nombre}» ya está en el Vale N°{vpend.id} '
            f'(turno {vpend.prioridad}, {qty_en_vale} u.) pendiente en caja. '
            f'Cobre o anule ese vale antes de agregarlo a una venta nueva.'
        ), 'en_vale_pendiente'
    disp_b = stock_disponible_bodega(producto)
    if disp_b >= cons_new:
        return True, None, None
    if qty_prev > 0:
        max_u_b = int(max(0, disp_b) / factor) if factor else max(0, disp_b)
        return False, (
            f'Sin stock suficiente para {producto.nombre}. '
            f'Tienda: {max(0, disp - comprometido)} u.; bodega: {disp_b} u.; '
            f'en este vale ya lleva {qty_prev} (máx. tienda {max_u}, bodega {max_u_b}).'
        ), 'sin_stock'
    return False, (
        f'Sin stock disponible para {producto.nombre}. '
        f'Tienda: {max(0, disp - comprometido)} u. (comprometido otros vales: {comprometido}); '
        f'bodega: {disp_b} u.'
    ), 'sin_stock'


def _pos_agregar_producto_a_venta_abierta(producto, caja, vendedor_actual, a_pedido=False, punto_retiro_linea=None):
    """
    Agrega 1 unidad del producto al vale Abierta del vendedor.
    Si ya existe línea del mismo producto, incrementa cantidad (no duplica fila).
    Retorna dict con ok, error, mensaje, venta_total, items_count, producto_nombre, linea_incrementada.
    """
    if not producto:
        return {'ok': False, 'error': 'no_producto', 'mensaje': 'Producto no válido.'}
    db.session.refresh(producto)
    pu_ef = precio_efectivo_pos_producto(producto)
    if pu_ef <= 0:
        return {
            'ok': False,
            'error': 'sin_precio',
            'mensaje': f'«{producto.nombre}» no tiene precio de venta ni mayoreo.',
        }
    venta = _venta_abierta_por_caja_y_usuario(caja.id, vendedor_actual)
    ok_stock, msg_stock, err_stock = _pos_puede_sumar_unidad(
        producto, venta, caja_id=caja.id, a_pedido=bool(a_pedido)
    )
    if not ok_stock:
        return {'ok': False, 'error': err_stock or 'sin_stock', 'mensaje': msg_stock}
    linea_incrementada = False
    with transaccion_critica():
        if not venta:
            venta = Venta(
                usuario=vendedor_actual,
                estado='Abierta',
                monto_total=0,
                caja_id=caja.id,
                fecha=db.func.current_timestamp(),
            )
            db.session.add(venta)
            db.session.flush()
        _pos_cross_sell_sync_session_scope(venta.id)
        detalle = (
            DetalleVenta.query.filter_by(id_venta=venta.id, id_producto=producto.id)
            .order_by(DetalleVenta.id.asc())
            .first()
        )
        if detalle:
            if bool(a_pedido) != bool(getattr(detalle, 'a_pedido', False)):
                return {
                    'ok': False,
                    'error': 'mezcla_apedido',
                    'mensaje': (
                        f'«{producto.nombre}» ya está en el vale con otro tipo de entrega. '
                        'Use otra línea o elimine la existente.'
                    ),
                }
            linea_incrementada = True
            nueva_cant = int(detalle.cantidad or 0) + 1
            desc = float(detalle.descuento or 0)
            detalle.cantidad = nueva_cant
            detalle.subtotal = (detalle.precio_unitario * nueva_cant) * (1 - (desc / 100))
        else:
            ret_linea = None
            if _pos_retiro_por_linea_empresa():
                ret_linea = (punto_retiro_linea or 'Tienda').strip()
                if ret_linea not in ('Tienda', 'Bodega', 'Despacho'):
                    ret_linea = 'Tienda'
            detalle = DetalleVenta(
                id_venta=venta.id,
                id_producto=producto.id,
                cantidad=1,
                precio_unitario=pu_ef,
                descuento=0.0,
                subtotal=pu_ef,
                punto_retiro_linea=ret_linea,
                a_pedido=bool(a_pedido),
            )
            db.session.add(detalle)
        db.session.flush()
        venta.recalcular_total()
    db.session.commit()
    try:
        if _pos_cross_sell_enabled_session():
            cs = _pos_cross_sell_build_for_venta(venta.id)
            if cs:
                session['pos_cross_sell'] = cs
    except Exception:
        app.logger.exception('POS cross-sell')
    items = DetalleVenta.query.filter_by(id_venta=venta.id).count()
    total_clp = _pos_venta_total_clp(venta)
    return {
        'ok': True,
        'venta_id': venta.id,
        'venta_total': float(total_clp),
        'items_count': items,
        'producto_id': producto.id,
        'producto_nombre': producto.nombre,
        'linea_incrementada': linea_incrementada,
        'cantidad_en_vale': _pos_cantidad_producto_en_venta(venta, producto.id),
        'a_pedido': bool(a_pedido),
    }


def api_pos_vales_hoy():
    """Últimos vales del vendedor en la caja abierta (hoy) para panel POS premium."""
    if not usuario_tiene_permiso('pos_emitir_vale'):
        return jsonify({'ok': False, 'error': 'sin_permiso', 'items': []}), 403
    caja = obtener_caja_activa()
    if not caja:
        return jsonify({'ok': True, 'items': []})
    vendedor = _nombre_usuario_pos_actual()
    from datetime import time as dt_time

    hoy = datetime.now().date()
    inicio = datetime.combine(hoy, dt_time.min)
    fin = datetime.combine(hoy, dt_time.max)
    try:
        filas = (
            Venta.query.filter(
                Venta.caja_id == caja.id,
                Venta.usuario == vendedor,
                Venta.fecha >= inicio,
                Venta.fecha <= fin,
            )
            .order_by(Venta.id.desc())
            .limit(15)
            .all()
        )
    except Exception as ex:
        db.session.rollback()
        app.logger.exception('api_pos_vales_hoy: %s', ex)
        return jsonify({'ok': False, 'error': 'consulta', 'items': []}), 500
    items = []
    for v in filas:
        try:
            n_det = len(list(v.detalles or []))
        except Exception:
            db.session.rollback()
            n_det = 0
        total = int(round(float(v.monto_total or 0)))
        hora = ''
        if getattr(v, 'fecha', None):
            try:
                hora = v.fecha.strftime('%H:%M')
            except Exception:
                hora = ''
        items.append({
            'id': int(v.id),
            'estado': (v.estado or '').strip(),
            'total': total,
            'total_fmt': f'${total:,}'.replace(',', '.'),
            'lineas': n_det,
            'hora': hora,
        })
    return jsonify({'ok': True, 'items': items})


