def api_pos_retiro_linea():
    """JSON: actualiza punto_retiro_linea de un detalle (pantalla vendedora)."""
    if not usuario_tiene_permiso('pos_emitir_vale'):
        return jsonify({'ok': False, 'mensaje': 'Sin permiso.'}), 403
    data = request.get_json(silent=True) or {}
    detalle_id = data.get('detalle_id')
    if not detalle_id:
        return jsonify({'ok': False, 'mensaje': 'Línea no indicada.'}), 400
    if not _pos_retiro_por_linea_empresa():
        return jsonify({'ok': False, 'mensaje': 'Retiro por línea no está activado.'}), 400
    _asegurar_columnas_detalle_ventas_legacy()
    caja_activa = obtener_caja_activa()
    detalle = DetalleVenta.query.get(detalle_id)
    if not detalle or not detalle.venta or detalle.venta.estado != 'Abierta':
        return jsonify({'ok': False, 'mensaje': 'Línea no válida o venta no abierta.'}), 400
    if detalle.venta.caja_id != (caja_activa.id if caja_activa else None):
        return jsonify({
            'ok': False,
            'mensaje': 'No puede modificar ítems fuera de la venta activa del turno.',
        }), 400
    ret = (data.get('punto_retiro_linea') or '').strip()
    if ret not in ('Bodega', 'Tienda', 'Despacho'):
        return jsonify({'ok': False, 'mensaje': 'Retiro debe ser Tienda, Bodega o Despacho.'}), 400
    detalle.punto_retiro_linea = ret
    db.session.commit()
    venta = detalle.venta
    total = float(venta.monto_total or 0) if venta else 0.0
    cnt = DetalleVenta.query.filter_by(id_venta=venta.id).count() if venta else 0
    return jsonify({
        'ok': True,
        'punto_retiro_linea': ret,
        'venta_total': int(round(total)),
        'items_count': cnt,
    })


def api_pos_escanear_agregar():
    """JSON: escaneo de código → agrega línea al vale o indica producto no encontrado."""
    if not usuario_tiene_permiso('pos_emitir_vale'):
        return jsonify({'ok': False, 'error': 'sin_permiso'}), 403
    data = request.get_json(silent=True) or {}
    codigo = (data.get('codigo') or request.form.get('codigo') or '').strip()
    producto_id_raw = data.get('producto_id')
    producto = None
    if producto_id_raw:
        try:
            producto = Producto.query.get(int(producto_id_raw))
        except (TypeError, ValueError):
            producto = None
    if not producto and codigo:
        producto = _pos_buscar_producto_por_codigo(codigo)
    if not producto and not codigo:
        return jsonify({'ok': False, 'error': 'sin_codigo'}), 400
    caja = obtener_caja_activa()
    if not caja:
        return jsonify({'ok': False, 'error': 'sin_caja'}), 400
    session.pop('pos_cross_sell', None)
    if not producto:
        sugerencias = []
        try:
            for p in _buscar_productos_texto_stock(codigo, limit=5):
                sugerencias.append({
                    'id': p.id,
                    'nombre': p.nombre,
                    'codigo_barra': p.codigo_barra or '',
                    'stock_tienda': stock_disponible_venta_tienda(p),
                    'precio': precio_efectivo_pos_producto(p),
                })
        except Exception:
            sugerencias = []
        return jsonify({
            'ok': False,
            'error': 'no_encontrado',
            'codigo': codigo,
            'sugerencias': sugerencias,
        }), 404
    vendedor = _nombre_usuario_pos_actual()
    a_pedido = str(data.get('a_pedido', '')).strip().lower() in ('1', 'true', 'si', 'yes', 'on')
    retiro_raw = (data.get('punto_retiro_linea') or '').strip()
    punto_retiro = retiro_raw if retiro_raw in ('Tienda', 'Bodega', 'Despacho') else None
    res = _pos_agregar_producto_a_venta_abierta(
        producto, caja, vendedor, a_pedido=a_pedido, punto_retiro_linea=punto_retiro
    )
    if not res.get('ok'):
        code = 400
        if res.get('error') in ('sin_stock', 'en_vale_pendiente', 'mezcla_apedido'):
            code = 409
        return jsonify(res), code
    return jsonify(res)


def api_pos_producto_alta_rapida():
    """
    Alta mínima desde POS + opcional agregar al vale.
    JSON: codigo_barra, nombre, precio_venta, stock_tienda (default 1), agregar_vale (default true).
    """
    if not usuario_tiene_permiso('pos_emitir_vale'):
        return jsonify({'ok': False, 'error': 'sin_permiso'}), 403
    data = request.get_json(silent=True) or {}
    nombre = (data.get('nombre') or '').strip()[:100]
    codigo = _enrol_normalizar_codigo(data.get('codigo_barra') or data.get('codigo'))
    if not nombre:
        return jsonify({'ok': False, 'error': 'nombre_requerido'}), 400
    if not codigo:
        return jsonify({'ok': False, 'error': 'codigo_requerido'}), 400
    if _enrol_codigo_barra_ocupado(codigo):
        existente = _pos_buscar_producto_por_codigo(codigo)
        if existente and data.get('agregar_vale', True):
            caja = obtener_caja_activa()
            if not caja:
                return jsonify({'ok': False, 'error': 'sin_caja'}), 400
            res = _pos_agregar_producto_a_venta_abierta(existente, caja, _nombre_usuario_pos_actual())
            if res.get('ok'):
                res['ya_existia'] = True
            return jsonify(res), 200 if res.get('ok') else 400
        return jsonify({'ok': False, 'error': 'barras_duplicado'}), 409
    try:
        precio = float(data.get('precio_venta') or data.get('precio') or 0)
    except (TypeError, ValueError):
        precio = 0.0
    if precio <= 0:
        return jsonify({'ok': False, 'error': 'precio_requerido'}), 400
    try:
        stock_tienda = int(data.get('stock_tienda', 1))
    except (TypeError, ValueError):
        stock_tienda = 1
    stock_tienda = max(0, min(stock_tienda, 99999))
    caja = obtener_caja_activa()
    if not caja:
        return jsonify({'ok': False, 'error': 'sin_caja'}), 400
    agregar = data.get('agregar_vale', True)
    if str(agregar).lower() in ('0', 'false', 'off', 'no'):
        agregar = False
    try:
        with transaccion_critica():
            p = Producto(
                nombre=nombre,
                codigo_barra=codigo[:50],
                precio_venta=precio,
                precio_mayoreo=0,
                stock=0,
                activo=True,
                unidad='Unidad',
                unidad_venta='Unidad',
                unidad_compra='Unidad',
            )
            db.session.add(p)
            db.session.flush()
            aid_t = id_almacen_tienda()
            if aid_t and _tablas_inventario_almacen_existen() and stock_tienda > 0:
                _, err = ajustar_stock_almacen(p.id, aid_t, stock_tienda)
                if err:
                    raise _GuardarVentaAbort(err, 'danger')
                _refrescar_stock_total_producto(p)
            elif stock_tienda > 0:
                p.stock = stock_tienda
        db.session.commit()
    except _GuardarVentaAbort as ab:
        db.session.rollback()
        return jsonify({'ok': False, 'error': 'stock', 'mensaje': ab.message}), 400
    except Exception as ex:
        db.session.rollback()
        app.logger.exception('POS alta rápida producto')
        return jsonify({'ok': False, 'error': 'no_pudo_crear', 'mensaje': str(ex)[:200]}), 500
    if agregar:
        res = _pos_agregar_producto_a_venta_abierta(p, caja, _nombre_usuario_pos_actual())
        if not res.get('ok'):
            return jsonify({
                'ok': True,
                'creado': True,
                'producto_id': p.id,
                'agregado_vale': False,
                'mensaje_agregar': res.get('mensaje'),
            })
        res['creado'] = True
        res['agregado_vale'] = True
        return jsonify(res)
    return jsonify({'ok': True, 'creado': True, 'producto_id': p.id, 'agregado_vale': False})


def agregar_producto_venta():
    try:
        session.pop('pos_cross_sell', None)
        codigo = (request.form.get('codigo') or request.args.get('codigo') or '').strip()
        producto_id_raw = request.form.get('producto_id') or request.args.get('producto_id')
        caja = obtener_caja_activa()
        if not caja:
            flash("No hay caja abierta para operar en Punto de Venta.", "warning")
            return redirect(url_for('abrir_caja'))

        producto = None
        if producto_id_raw:
            try:
                producto = Producto.query.get(int(producto_id_raw))
            except (TypeError, ValueError):
                producto = None
        if not producto and codigo:
            producto = _pos_buscar_producto_por_codigo(codigo)
        if not producto:
            flash(f"Producto no encontrado ({codigo or 'sin código'}).", "warning")
            return redirect(url_for('punto_venta'))

        vendedor_actual = _nombre_usuario_pos_actual()
        res = _pos_agregar_producto_a_venta_abierta(producto, caja, vendedor_actual)
        if not res.get('ok'):
            flash(res.get('mensaje') or 'No se pudo agregar el producto.', 'warning')
            return redirect(url_for('punto_venta'))
        return redirect(url_for('punto_venta'))
    except Exception as ex:
        db.session.rollback()
        app.logger.exception("No se pudo agregar producto al vale: %s", ex)
        flash(f"No se pudo agregar el producto al vale: {ex}", "danger")
        return redirect(url_for('punto_venta'))

# proceso de eliminar producto de venta abierta desde punto de venta........................................

def eliminar_detalle(id):
    detalle = DetalleVenta.query.get_or_404(id)
    venta = detalle.venta
    with transaccion_critica():
        db.session.delete(detalle)
        venta.recalcular_total()
    db.session.commit()
    db.session.refresh(venta)
    n_lineas = DetalleVenta.query.filter_by(id_venta=venta.id).count()
    if (venta.estado or '') == 'Abierta':
        if n_lineas == 0 or float(venta.monto_total or 0) <= 0:
            _pos_cross_sell_clear_session_nueva_venta_pos()
    if request.form.get('pos_ajax') == '1':
        total = float(venta.monto_total or 0)
        return jsonify({
            'ok': True,
            'venta_total': int(round(total)),
            'items_count': n_lineas,
        })
    return redirect(url_for('punto_venta'))

#eliminar venta abierta o pendiente desde pantalla de ventas........................................................................

@app.route('/eliminar_venta/<int:id>', methods=['POST'])
@login_required
@caja_requerida
@permisos_required('gestionar_usuarios', 'anular_vale_caja')
def eliminar_venta(id):
    venta = Venta.query.options(joinedload(Venta.detalles)).get_or_404(id)
    st = (venta.estado or '').strip()
    if st == 'Anulada':
        flash('Las ventas anuladas no se eliminan desde esta pantalla.', 'warning')
        return redirect(url_for('mostrar_ventas'))

    stock_movido = _venta_stock_ya_descontado(venta)
    if stock_movido and not usuario_tiene_permiso('gestionar_usuarios'):
        flash(
            'Eliminar ventas ya cobradas o con inventario afectado requiere permiso de administración.',
            'danger',
        )
        return redirect(url_for('mostrar_ventas'))

    ok_rev, err_rev = _revertir_operaciones_venta_antes_borrar(
        venta,
        (current_user.nombre if current_user.is_authenticated else '') or 'Sistema',
    )
    if not ok_rev:
        db.session.rollback()
        flash(err_rev or 'No se pudo revertir efectos de la venta antes de eliminar.', 'danger')
        return redirect(url_for('mostrar_ventas'))

    vid = venta.id
    estado_prev = (venta.estado or '').strip()
    met_prev = (venta.metodo_pago or '').strip()
    saldo_fav_prev = float(venta.saldo_favor_usado or 0)
    usr_nom = (current_user.nombre if current_user.is_authenticated else '') or 'Sistema'
    warn_mov_caja = _registrar_movimiento_caja_devolucion_venta(venta, usr_nom)
    try:
        db.session.delete(venta)
        db.session.commit()
        if estado_prev == 'Abierta':
            _pos_cross_sell_clear_session_nueva_venta_pos()
        msg = f"Venta N°{vid} eliminada."
        if stock_movido:
            msg += (
                " Se revirtió inventario"
                + (" y saldo a favor del cliente" if estado_prev == 'Pagado' and saldo_fav_prev > 0 else "")
            )
        if estado_prev == 'Pagado' and met_prev not in ('', 'Credito') and warn_mov_caja is None:
            msg += " Se registró egreso en movimiento de caja por la devolución."
        flash(msg, 'success')
        if warn_mov_caja and warn_mov_caja not in ('sin_monto_medios',):
            flash(warn_mov_caja, 'warning')
    except Exception as e:
        db.session.rollback()
        flash(f"Error al eliminar la venta: {str(e)}", "danger")
    return redirect(url_for('mostrar_ventas'))


# proceso de finalización de venta, validación de cliente y emisión de vale................................

def _pos_ticket_vale_usuario_autorizado(venta):
    """Emisor del vale, cobrador de la misma caja (pendiente o borrador), o soporte/admin."""
    if not venta:
        return False
    try:
        if current_user.is_authenticated and getattr(current_user, 'rol', None):
            rn = (current_user.rol.nombre or '').strip().lower()
            if rn in ('admin', 'administrador', 'superadmin', 'super admin'):
                return True
    except Exception:
        pass
    if usuario_tiene_permiso('gestionar_usuarios'):
        return True
    caja = obtener_caja_activa()
    if not caja or venta.caja_id != caja.id:
        return False
    st = (venta.estado or '').strip()
    vend = _nombre_usuario_pos_actual()
    vu = (venta.usuario or '').strip()
    if st == 'Pendiente':
        if usuario_tiene_permiso('caja_cobrar_vale'):
            return True
        return vu == (vend or '').strip()
    if st == 'Abierta':
        if usuario_tiene_permiso('caja_cobrar_vale'):
            return True
        return usuario_tiene_permiso('pos_emitir_vale') and vu == (vend or '').strip()
    return False


def _redirect_tras_ticket_vale_denegado():
    if usuario_tiene_permiso('caja_cobrar_vale'):
        return redirect(url_for('caja_pendientes'))
    return redirect(url_for('punto_venta'))


def pos_ticket_vale(venta_id):
    """Ticket HTML tras emitir vale (impresión / bloques retiro por línea)."""
    venta = Venta.query.options(
        joinedload(Venta.cliente),
        joinedload(Venta.detalles).joinedload(DetalleVenta.producto),
        joinedload(Venta.detalles).joinedload(DetalleVenta.supervisor_autorizo),
    ).get_or_404(int(venta_id))
    st_ticket = (venta.estado or '').strip()
    if st_ticket not in ('Pendiente', 'Abierta'):
        flash('Solo puede ver el ticket de vales pendientes de cobro o borradores POS abiertos.', 'warning')
        return _redirect_tras_ticket_vale_denegado()
    ticket_es_borrador = st_ticket == 'Abierta'
    if not _pos_ticket_vale_usuario_autorizado(venta):
        flash('No tiene permiso para ver este vale.', 'danger')
        return _redirect_tras_ticket_vale_denegado()

    cliente = venta.cliente
    empresa_cfg = obtener_config_empresa()
    cotizacion_origen = (
        Cotizacion.query.get(venta.cotizacion_origen_id) if getattr(venta, 'cotizacion_origen_id', None) else None
    )
    buckets, subtotales, orden_retiro = _ticket_agrupar_detalles_por_retiro(venta)
    usar_bloques = _ticket_usar_bloques_por_retiro(venta, buckets)
    etiqueta_retiro_linea = {'Tienda': '[T]', 'Bodega': '[B]', 'Despacho': '[D]'}
    ticket_line_etiqueta = {}
    for d in venta.detalles or []:
        kk = _detalle_punto_retiro_efectivo(d, venta)
        ticket_line_etiqueta[d.id] = etiqueta_retiro_linea.get(kk, '[T]')

    detalles_picking = buckets.get('Bodega') or []

    qr_ticket_src = None
    despacho_ticket_url = None
    if not ticket_es_borrador and _pos_ticket_qr_despacho_empresa():
        tok = pos_despacho_vale_token_create(venta.id)
        if tok:
            despacho_ticket_url = url_for('pos_despacho_vale', vid=venta.id, t=tok, _external=True)
            try:
                qr_ticket_src = _qr_data_uri_png(despacho_ticket_url, box_size=3, border=1)
            except Exception:
                qr_ticket_src = None

    return render_template(
        'ticket_vale.html',
        venta=venta,
        detalles=list(venta.detalles or []),
        cliente=cliente,
        empresa_cfg=empresa_cfg,
        cotizacion_origen=cotizacion_origen,
        ticket_buckets=buckets,
        ticket_subtotales=subtotales,
        orden_retiro=orden_retiro,
        usar_bloques_por_retiro=usar_bloques,
        etiqueta_retiro_linea=etiqueta_retiro_linea,
        ticket_line_etiqueta=ticket_line_etiqueta,
        detalles_picking=detalles_picking,
        qr_ticket_src=qr_ticket_src,
        despacho_ticket_url=despacho_ticket_url,
        pos_ticket_qr_despacho=_pos_ticket_qr_despacho_empresa(),
        ticket_es_borrador=ticket_es_borrador,
    )


def pos_despacho_vale(vid):
    """Vista QR ticket: listado por canal (tienda/bodega/despacho) según permiso. Solo lectura; entrega en bodega_plataforma."""
    tok = (request.args.get('t') or '').strip()
    venta = Venta.query.options(
        joinedload(Venta.cliente),
        joinedload(Venta.detalles).joinedload(DetalleVenta.producto),
    ).get_or_404(int(vid))

    if tok:
        vv = pos_despacho_vale_token_verify(tok)
        if vv is None or int(vv) != int(venta.id):
            flash('Código QR del vale inválido o caducado. Vuelva a imprimir o escanear el ticket.', 'warning')
            return redirect(url_for('inicio'))
    elif not usuario_tiene_permiso('gestionar_usuarios'):
        flash('Para abrir esta pantalla debe escanear el código QR del ticket o tener permiso de administración.', 'warning')
        return redirect(url_for('inicio'))

    st = (venta.estado or '').strip()
    if st not in ('Pendiente', 'Pagado'):
        flash('Este vale no está disponible para despacho.', 'info')
        return redirect(url_for('inicio'))

    buckets, subtotales, orden_retiro = _ticket_agrupar_detalles_por_retiro(venta)
    ver_canal_tienda = usuario_tiene_permiso('pos_emitir_vale') or usuario_tiene_permiso('caja_cobrar_vale')
    ver_canal_bodega = usuario_tiene_permiso('bodega_operador')

    tiene_lineas = False
    if ver_canal_tienda:
        tiene_lineas = tiene_lineas or bool(buckets.get('Tienda') or buckets.get('Despacho'))
    if ver_canal_bodega:
        tiene_lineas = tiene_lineas or bool(buckets.get('Bodega') or buckets.get('Despacho'))

    return render_template(
        'pos/despacho_vale.html',
        venta=venta,
        cliente=venta.cliente,
        ticket_buckets=buckets,
        ticket_subtotales=subtotales,
        orden_retiro=orden_retiro,
        ver_canal_tienda=ver_canal_tienda,
        ver_canal_bodega=ver_canal_bodega,
        despacho_sin_lineas_visibles=(not tiene_lineas) and (ver_canal_tienda or ver_canal_bodega),
        empresa_cfg=obtener_config_empresa(),
        etiqueta_retiro_linea={'Tienda': '[T]', 'Bodega': '[B]', 'Despacho': '[D]'},
    )


def bodega_despacho_qr_vales():
    """Lista vales pendientes con retiro bodega (o mixto con líneas bodega) — enlaces con token igual que QR del ticket."""
    caja = obtener_caja_activa()
    cid = caja.id if caja else None
    if cid is None:
        return render_template(
            'bodega_despacho_qr_vales.html',
            vales=[],
            tokens={},
            caja=None,
            sin_caja_abierta=True,
        )

    q = (
        Venta.query.options(joinedload(Venta.cliente))
        .filter(
            Venta.estado == 'Pendiente',
            Venta.metodo_pago.is_(None),
            Venta.caja_id == cid,
            _sql_filtro_venta_cola_bodega(),
        )
        .order_by(Venta.prioridad.asc(), Venta.fecha.asc())
    )
    vales = q.limit(150).all()
    tokens = {}
    for v in vales:
        t = pos_despacho_vale_token_create(v.id)
        if t:
            tokens[v.id] = t
    return render_template(
        'bodega_despacho_qr_vales.html',
        vales=vales,
        tokens=tokens,
        caja=caja,
        sin_caja_abierta=False,
    )


def _pos_emit_origen_redirect_endpoint():
    """Tras emitir vale: mismo POS habitual o Command Deck (evitar pantalla sólo ticket)."""
    o = (request.form.get('pos_emit_origen') or '').strip().lower()
    return 'pos_command_deck' if o == 'command_deck' else 'punto_venta'


def _pos_ticket_modal_impresion_url_from_query():
    """URL del ticket para modal/iframe cuando GET trae ticket_iframe=<venta_id>."""
    raw = (request.args.get('ticket_iframe') or '').strip()
    if not raw.isdigit():
        return None
    vid = int(raw)
    if vid <= 0:
        return None
    return url_for('pos_ticket_vale', venta_id=vid)


def finalizar_venta():
    caja = obtener_caja_activa()
    if not caja:
        flash("No hay caja abierta para emitir vale.", "warning")
        return redirect(url_for('abrir_caja'))

    vendedor_actual = _nombre_usuario_pos_actual()
    # Cada vendedor finaliza su propio vale abierto.
    venta = _venta_abierta_por_caja_y_usuario(caja.id, vendedor_actual)
    if not venta:
        flash("No hay vale en armado. Escanee o busque productos y vuelva a intentar.", "warning")
        return redirect(url_for('punto_venta'))
    if not list(venta.detalles or []):
        flash("Agregue al menos un producto (escanear o búsqueda) antes de emitir el vale.", "warning")
        return redirect(url_for('punto_venta'))
    _asegurar_columnas_detalle_ventas_legacy()
    _asegurar_columnas_productos_legacy()
    from services.pos_autorizacion_descuento_service import detalle_descuento_autorizacion_valida

    lineas_sin_auth = []
    for d in list(venta.detalles or []):
        if float(d.descuento or 0) > 1e-6 and not detalle_descuento_autorizacion_valida(d):
            nom = (d.producto.nombre[:40] if d.producto else f'Línea {d.id}')
            lineas_sin_auth.append(nom)
    if lineas_sin_auth:
        flash(
            'No se puede emitir el vale: hay descuentos sin autorización de supervisor. '
            'Guarde cada línea con tarjeta/PIN o quite el descuento. '
            + '; '.join(lineas_sin_auth[:3]),
            'warning',
        )
        return redirect(url_for('punto_venta'))
    if float(venta.monto_total or 0) <= 0:
        try:
            venta.recalcular_total()
            db.session.commit()
        except Exception:
            db.session.rollback()
        if float(venta.monto_total or 0) <= 0:
            flash("El vale no tiene total. Verifique precios de los productos agregados.", "warning")
            return redirect(url_for('punto_venta'))
    # Persistencia explícita para reportes por vendedor.
    venta.usuario = vendedor_actual
    faltantes = _venta_validar_stock_tienda(venta)
    if faltantes:
        flash(
            "No se puede emitir el vale: falta stock en tienda para "
            + "; ".join(faltantes[:3]),
            "warning",
        )
        return redirect(url_for('punto_venta'))

    if _venta_tiene_lineas_a_pedido(venta):
        if str(request.form.get('compromiso_confirmado', '')).strip() != '1':
            flash(
                'Confirme el compromiso de entrega para los productos a pedido antes de emitir el vale.',
                'warning',
            )
            return redirect(url_for('punto_venta'))

    nombre = request.form.get('cliente_nombre')
    direccion = request.form.get('cliente_direccion')
    giro = request.form.get('cliente_giro')
    telefono = request.form.get('cliente_telefono')
    correo = request.form.get('cliente_correo')
    comuna = request.form.get('cliente_comuna')
    ciudad = request.form.get('cliente_ciudad')
    es_cliente_final = request.form.get('cliente_final') == '1'
    rut_form = (request.form.get('cliente_rut') or '').strip()
    if not es_cliente_final and not pos_rut_obligatorio_en_emitir():
        if not rut_form or not validar_rut(rut_form):
            es_cliente_final = True

    puntos_validos_linea = {'Bodega', 'Tienda', 'Despacho'}
    mixto_emp = _pos_retiro_por_linea_empresa()
    pr_final = None
    if mixto_emp:
        marcas = []
        for d in list(venta.detalles or []):
            pv = ((getattr(d, 'punto_retiro_linea', None) or '') or 'Tienda').strip()
            if pv not in puntos_validos_linea:
                flash(
                    'Retiro por línea: indique Tienda, Bodega o Despacho en cada producto (columna Retiro).',
                    'warning',
                )
                return redirect(url_for('punto_venta'))
            marcas.append(pv)
        uq = set(marcas)
        pr_final = list(uq)[0] if len(uq) == 1 else 'Mixto'
    else:
        punto_retiro = (request.form.get('punto_retiro') or '').strip()
        if (not punto_retiro) or punto_retiro == '__PENDIENTE__' or punto_retiro not in puntos_validos_linea:
            flash("Debe seleccionar dónde retirará el cliente (Bodega, Tienda o Despacho).", "warning")
            return redirect(url_for('punto_venta'))
        pr_final = punto_retiro

    try:
        with transaccion_critica():
            if es_cliente_final:
                cliente = obtener_o_crear_cliente_final()
            else:
                rut = rut_form or (request.form.get('cliente_rut') or '').strip()
                if not rut or not validar_rut(rut):
                    if pos_rut_obligatorio_en_emitir():
                        raise _GuardarVentaAbort(
                            "Debe identificar al cliente (RUT válido) o marcar cliente final (F3).",
                            "warning",
                        )
                    raise _GuardarVentaAbort("Error: RUT inválido.", "danger")

                cliente = Cliente.query.filter_by(rut=rut).first()

                if cliente:
                    nombre_in = (nombre or '').strip()
                    if nombre_in and nombre_in != (cliente.nombre or '').strip():
                        raise _GuardarVentaAbort(
                            "El cliente ya existe, no puedes cambiar el nombre.", "warning"
                        )
                    _aplicar_campos_contacto_cliente(
                        cliente,
                        direccion=direccion,
                        giro=giro,
                        telefono=telefono,
                        correo=correo,
                        comuna=comuna,
                        ciudad=ciudad,
                    )
                else:
                    if not nombre:
                        raise _GuardarVentaAbort(
                            "Error: Nombre es obligatorio para nuevo cliente.", "danger"
                        )
                    nombre_n = (nombre or '').strip()[:100]
                    cliente = Cliente(
                        nombre=nombre_n,
                        rut=rut,
                        giro=_limpiar_texto_cliente_ui(giro),
                        direccion=(_limpiar_texto_cliente_ui(direccion) or '')[:200] or None,
                        telefono=(_limpiar_texto_cliente_ui(telefono) or '')[:20] or None,
                        correo=(_limpiar_texto_cliente_ui(correo) or '')[:100] or None,
                        comuna=(_limpiar_texto_cliente_ui(comuna) or '')[:80] or None,
                        ciudad=(_limpiar_texto_cliente_ui(ciudad) or '')[:80] or None,
                    )
                    db.session.add(cliente)
                    db.session.flush()

            pendientes = Venta.query.filter_by(estado="Pendiente").count()
            prioridad = pendientes + 1

            from core.application.bootstrap import build_finalizar_venta_use_case
            from core.application.ventas.commands import FinalizarVentaCommand

            build_finalizar_venta_use_case(transaccion_critica=None, validar_stock=False).execute(
                FinalizarVentaCommand(
                    venta_id=venta.id,
                    cliente_id=cliente.id,
                    punto_retiro=pr_final,
                    usuario_vendedor=vendedor_actual,
                    prioridad_cola=prioridad,
                    retiro_por_linea=mixto_emp,
                )
            )
            venta = Venta.query.get(venta.id)
            # Fecha de negocio = emisión del vale (antes quedaba la del carrito Abierta).
            venta.fecha = datetime.now()
            if _venta_tiene_lineas_a_pedido(venta):
                from services.pos_compromiso_entrega_service import persistir_ventas_a_pedido

                persistir_ventas_a_pedido(venta, request.form, vendedor_actual)
        db.session.commit()
    except _GuardarVentaAbort as ab:
        db.session.rollback()
        flash(ab.message, ab.category)
        return redirect(url_for('punto_venta'))
    except Exception as ex:
        from core.domain.venta.exceptions import VentaDomainError

        db.session.rollback()
        if isinstance(ex, VentaDomainError):
            flash(str(ex), 'warning')
            return redirect(url_for('punto_venta'))
        app.logger.exception('finalizar_venta: %s', ex)
        flash(f'No se pudo emitir el vale: {ex}', 'danger')
        return redirect(url_for('punto_venta'))
    _pos_cross_sell_clear_session_nueva_venta_pos()
    _pos_wall_set_vale_emitido(venta, cliente, caja=caja)

    flash(f"Vale N°{venta.id} emitido para {cliente.nombre}. Turno {venta.prioridad}.", "success")
    ep = _pos_emit_origen_redirect_endpoint()
    if _pos_autoprint_ticket_emitido_empresa():
        return redirect(url_for(ep, ticket_iframe=str(venta.id)))
    return redirect(url_for(ep))

#edición de venta para vales pendientes desde pantalla de ventas........................................

@app.route('/editar_venta/<int:id>', methods=['GET', 'POST'])
@login_required
@caja_requerida
@permisos_required('pos_emitir_vale', 'caja_cobrar_vale', 'gestionar_usuarios')
def editar_venta(id):
    venta = Venta.query.get_or_404(id)
    st = (venta.estado or '').strip()
    if st == 'Anulada':
        flash('No se puede editar una venta anulada.', 'warning')
        return redirect(url_for('mostrar_ventas'))
    if st in ('Pagado',):
        flash('No se puede editar una venta ya cobrada desde esta pantalla.', 'warning')
        return redirect(url_for('mostrar_ventas'))
    if st == 'Pendiente' and not _venta_metodo_pago_vacio(venta):
        flash(
            'Ventas pendientes con método de pago registrado (p. ej. crédito) no se editan aquí.',
            'warning',
        )
        return redirect(url_for('mostrar_ventas'))
    productos = Producto.query.all()
    if request.method == 'POST':
        venta.usuario = request.form['usuario']
        # eliminar detalles anteriores
        for d in venta.detalles:
            db.session.delete(d)
        ids = request.form.getlist('id_producto[]')
        cantidades = request.form.getlist('cantidad[]')
        precios = request.form.getlist('precio_unitario[]')
        total = 0
        for i in range(len(ids)):
            id_producto = int(ids[i])
            cantidad = int(cantidades[i])
            precio_unitario = float(precios[i])
            subtotal = cantidad * precio_unitario
            total += subtotal
            detalle = DetalleVenta(
                id_venta=venta.id,
                id_producto=id_producto,
                cantidad=cantidad,
                precio_unitario=precio_unitario
            )
            db.session.add(detalle)
        venta.total = total
        db.session.commit()
        flash("Venta actualizada correctamente.", "success")
        return redirect(url_for('mostrar_ventas'))
    return render_template('editar_venta.html', venta=venta, productos=productos)


def _validar_autorizacion_descuento_pos(descuento_pct, request_form):
    """
    Valida tarjeta supervisor (+ PIN si % > umbral) o credenciales legacy.
    Retorna (supervisor_usuario|None, metodo_str|None, error_mensaje|None).
    """
    from services import pos_autorizacion_descuento_service as pos_aut_svc

    _asegurar_columnas_usuario_pin_autorizacion()
    _asegurar_tabla_usuario_tarjeta_autorizacion()

    umbral = _pos_descuento_umbral_pin_pct()
    token_raw = (request_form.get('supervisor_tarjeta') or '').strip()
    pin = (request_form.get('supervisor_pin') or '').strip()

    if token_raw:
        sup, err = pos_aut_svc.resolver_supervisor_por_tarjeta(
            db,
            {
                'Usuario': Usuario,
                'UsuarioTarjetaAutorizacion': UsuarioTarjetaAutorizacion,
                'usuario_obj_tiene_permiso': usuario_obj_tiene_permiso,
                'usuario_esta_activo': usuario_esta_activo,
            },
            token_raw,
        )
        if err == 'inactive':
            return None, None, 'La tarjeta pertenece a un usuario inactivo.'
        if err == 'no_permiso':
            return None, None, 'Ese supervisor no tiene permiso para autorizar descuentos.'
        if not sup:
            return None, None, 'Tarjeta de supervisor no reconocida o revocada.'
        if pos_aut_svc.requiere_pin_para_descuento(descuento_pct, umbral):
            if not pos_aut_svc.pin_valido_formato(pin):
                return (
                    None,
                    None,
                    f'Descuento sobre {umbral:g}%: ingrese PIN de 4 dígitos del supervisor.',
                )
            if not sup.check_pin_autorizacion(pin):
                return None, None, 'PIN de supervisor incorrecto.'
        elif pin and not sup.check_pin_autorizacion(pin):
            return None, None, 'PIN de supervisor incorrecto.'
        metodo = pos_aut_svc.metodo_autorizacion_label(descuento_pct, umbral, uso_password=False)
        return sup, metodo, None

    # Legacy: usuario + contraseña ERP (respaldo)
    ident_raw = (
        request_form.get('supervisor_identificador')
        or request_form.get('supervisor_correo')
        or ''
    ).strip()
    pwd = request_form.get('supervisor_clave') or ''
    if not ident_raw or not pwd:
        return (
            None,
            None,
            'Escanee la tarjeta del supervisor. Si el descuento supera el umbral, también el PIN de 4 dígitos.',
        )
    sup, err_lookup = resolver_usuario_por_identificador_pos(ident_raw)
    if err_lookup == 'ambiguous_email_local':
        return None, None, 'Varios correos coinciden; use el correo completo del supervisor.'
    if err_lookup == 'ambiguous_nombre':
        return None, None, 'Hay más de un usuario con ese nombre; use correo completo.'
    if (
        not sup
        or err_lookup == 'not_found'
        or not sup.check_password(pwd)
        or not usuario_esta_activo(sup)
        or not usuario_obj_tiene_permiso(sup, 'autorizar_descuento_pos')
    ):
        return None, None, 'Autorización inválida: usuario, permiso o contraseña incorrectos.'
    metodo = pos_aut_svc.metodo_autorizacion_label(descuento_pct, umbral, uso_password=True)
    return sup, metodo, None


def _registrar_autorizacion_descuento_en_linea(detalle, supervisor, metodo, desc_anterior, desc_nuevo):
    """Persiste quién autorizó y deja rastro en erp_audit_log."""
    detalle.descuento_autorizado_por_id = supervisor.id
    detalle.descuento_autorizado_en = datetime.utcnow()
    detalle.descuento_autorizado_metodo = (metodo or '')[:24]
    try:
        _audit_log(
            'pos_descuento_autorizado',
            'detalle_venta',
            detalle.id,
            datos_antes={
                'descuento_pct': desc_anterior,
                'venta_id': detalle.id_venta,
            },
            datos_despues={
                'descuento_pct': desc_nuevo,
                'venta_id': detalle.id_venta,
                'supervisor_id': supervisor.id,
                'supervisor_nombre': (supervisor.nombre or '')[:80],
                'metodo': metodo,
                'producto_id': detalle.id_producto,
            },
        )
    except Exception:
        pass


def pos_usuarios_autorizar_descuento():
    """Lista usuarios activos que pueden autorizar aumento de descuento en POS (autocompletado)."""
    q = (request.args.get('q') or '').strip().lower()
    items = []
    for u in Usuario.query.order_by(Usuario.nombre).all():
        if not usuario_esta_activo(u):
            continue
        if not usuario_obj_tiene_permiso(u, 'autorizar_descuento_pos'):
            continue
        nombre = (u.nombre or '').strip()
        correo = (u.correo or '').strip()
        if q and q not in nombre.lower() and q not in correo.lower():
            continue
        items.append({'nombre': nombre, 'correo': correo})
    return jsonify({'usuarios': items[:50]})


def _redirect_tras_actualizar_item_pos():
    """Tras POST desde Command Deck vuelve al deck; si no, al POS clásico."""
    if request.form.get('from_command_deck') == '1':
        return redirect(url_for('pos_command_deck'))
    return redirect(url_for('punto_venta'))


def _json_tras_actualizar_item_pos(detalle, ok=True, mensaje=None, status=400):
    """Respuesta AJAX pantalla vendedora (sin redirect)."""
    if request.form.get('pos_ajax') != '1':
        if mensaje:
            flash(mensaje, 'warning' if status < 500 else 'danger')
        return _redirect_tras_actualizar_item_pos()
    if not ok:
        return jsonify({'ok': False, 'mensaje': mensaje or 'No se pudo actualizar.'}), status
    venta = detalle.venta if detalle else None
    total = float(venta.monto_total or 0) if venta else 0.0
    cnt = (
        DetalleVenta.query.filter_by(id_venta=venta.id).count()
        if venta
        else 0
    )
    return jsonify({
        'ok': True,
        'venta_total': int(round(total)),
        'items_count': cnt,
    })


# proceso de actualización de cantidad y descuento en venta abierta desde punto de venta........................................
def actualizar_item():
    detalle_id = request.form.get('actualizar')

    if request.form.get('solo_retiro_linea') == '1':
        if not detalle_id:
            return _json_tras_actualizar_item_pos(
                None, ok=False, mensaje='Línea no indicada.'
            )
        if not _pos_retiro_por_linea_empresa():
            return _json_tras_actualizar_item_pos(
                None,
                ok=False,
                mensaje='Retiro por línea no está activado para esta empresa.',
            )
        _asegurar_columnas_detalle_ventas_legacy()
        caja_activa = obtener_caja_activa()
        detalle = DetalleVenta.query.get(detalle_id)
        if not detalle or not detalle.venta or detalle.venta.estado != 'Abierta':
            return _json_tras_actualizar_item_pos(
                None, ok=False, mensaje='Línea no válida o venta no abierta.'
            )
        if detalle.venta.caja_id != (caja_activa.id if caja_activa else None):
            return _json_tras_actualizar_item_pos(
                None,
                ok=False,
                mensaje='No puede modificar ítems fuera de la venta activa del turno.',
            )
        ret = (request.form.get('punto_retiro_linea') or '').strip()
        if ret not in ('Bodega', 'Tienda', 'Despacho'):
            return _json_tras_actualizar_item_pos(
                None,
                ok=False,
                mensaje='Seleccione Tienda, Bodega o Despacho.',
            )
        detalle.punto_retiro_linea = ret
        db.session.commit()
        return _json_tras_actualizar_item_pos(detalle, ok=True)

    solo_cantidad = request.form.get('solo_cantidad') == '1'
    try:
        cantidad = int(request.form.get(f'cantidad_{detalle_id}', 1))
        raw_desc = request.form.get(f'descuento_{detalle_id}', 0)
        descuento = float(raw_desc) if str(raw_desc).strip() != '' else 0.0
    except (TypeError, ValueError):
        flash("Cantidad o descuento inválido.", "warning")
        return _redirect_tras_actualizar_item_pos()

    if cantidad <= 0:
        flash("La cantidad debe ser mayor a 0.", "warning")
        return _redirect_tras_actualizar_item_pos()

    caja_activa = obtener_caja_activa()
    detalle = DetalleVenta.query.get(detalle_id)
    if not detalle:
        return _redirect_tras_actualizar_item_pos()

    if not detalle.venta or detalle.venta.estado != "Abierta" or detalle.venta.caja_id != (caja_activa.id if caja_activa else None):
        flash("No puede modificar ítems fuera de la venta activa del turno.", "warning")
        return _redirect_tras_actualizar_item_pos()

    desc_anterior = float(detalle.descuento or 0)
    if solo_cantidad:
        descuento = desc_anterior
    if descuento < 0:
        flash("El descuento no puede ser negativo.", "warning")
        return _redirect_tras_actualizar_item_pos()
    if descuento > 100:
        flash("El descuento no puede ser mayor al 100%.", "warning")
        return _redirect_tras_actualizar_item_pos()

    from services.pos_autorizacion_descuento_service import requiere_autorizacion_supervisor_pos

    producto_linea = detalle.producto if detalle else None
    requiere_auth = requiere_autorizacion_supervisor_pos(descuento, producto_linea)
    desc_con_credencial_supervisor = False
    supervisor_autorizo = None
    metodo_auth = None
    if requiere_auth:
        _asegurar_columnas_detalle_ventas_legacy()
        sup, metodo_auth, err_auth = _validar_autorizacion_descuento_pos(descuento, request.form)
        if err_auth:
            return _json_tras_actualizar_item_pos(detalle, ok=False, mensaje=err_auth)
        supervisor_autorizo = sup
        desc_con_credencial_supervisor = True

    if detalle.producto:
        f_prev = _factor_venta_a_stock(detalle.producto)
        cons_new = int(round(cantidad * f_prev))
        retiro_eff = _stock_service._punto_retiro_efectivo_linea(detalle.venta, detalle)
        if retiro_eff == 'Bodega':
            disp_b = stock_disponible_bodega(detalle.producto)
            if cons_new > disp_b:
                return _json_tras_actualizar_item_pos(
                    detalle,
                    ok=False,
                    mensaje=(
                        f'Stock insuficiente en bodega (disponible: {disp_b}, '
                        f'requerido: {cons_new}).'
                    ),
                )
        if retiro_eff != 'Bodega':
            disp_t = stock_disponible_venta_tienda(detalle.producto)
            comprometido = _stock_service.consumo_stock_comprometido_tienda_producto(
                detalle.producto,
                excluir_venta_id=detalle.venta.id,
                caja_id=detalle.venta.caja_id,
            )
            cant_prev = detalle.cantidad
            detalle.cantidad = cantidad
            need_t = _stock_service._consumo_tienda_linea(detalle.venta, detalle, f_prev)
            detalle.cantidad = cant_prev
        if retiro_eff != 'Bodega' and disp_t < comprometido + need_t:
            vpend = _stock_service.venta_pendiente_con_producto(
                detalle.producto.id,
                excluir_venta_id=detalle.venta.id,
                caja_id=detalle.venta.caja_id,
            )
            if vpend:
                msg_st = (
                    f"Producto en Vale N°{vpend.id} (turno {vpend.prioridad}) pendiente en caja. "
                    f"Cobre o anule ese vale primero."
                )
            else:
                max_u = int((disp_t - comprometido) / f_prev) if f_prev else 0
                msg_st = (
                    f"Stock insuficiente en tienda (otros vales comprometen stock). "
                    f"Cantidad máxima aproximada: {max(0, max_u)}."
                )
            return _json_tras_actualizar_item_pos(detalle, ok=False, mensaje=msg_st)

    with transaccion_critica():
        detalle.cantidad = cantidad
        detalle.descuento = descuento
        detalle.subtotal = (detalle.precio_unitario * cantidad) * (1 - (descuento / 100))
        if supervisor_autorizo and desc_con_credencial_supervisor:
            _registrar_autorizacion_descuento_en_linea(
                detalle,
                supervisor_autorizo,
                metodo_auth,
                desc_anterior,
                descuento,
            )
        elif (
            float(descuento or 0) > 1e-6
            and producto_linea
            and getattr(producto_linea, 'pos_descuento_preautorizado', False)
        ):
            from services.pos_autorizacion_descuento_service import (
                producto_descuento_preautorizado_cubre,
            )

            if producto_descuento_preautorizado_cubre(producto_linea, descuento):
                detalle.descuento_autorizado_por_id = None
                detalle.descuento_autorizado_en = datetime.utcnow()
                detalle.descuento_autorizado_metodo = 'producto_preautorizado'
                try:
                    _audit_log(
                        'pos_descuento_preautorizado_producto',
                        'detalle_venta',
                        detalle.id,
                        datos_despues={
                            'descuento_pct': descuento,
                            'producto_id': detalle.id_producto,
                            'venta_id': detalle.id_venta,
                        },
                    )
                except Exception:
                    pass
        elif float(descuento or 0) <= 1e-6:
            detalle.descuento_autorizado_por_id = None
            detalle.descuento_autorizado_en = None
            detalle.descuento_autorizado_metodo = None
        detalle.venta.recalcular_total()
    db.session.commit()

    if desc_con_credencial_supervisor:
        if request.form.get('pos_ajax') == '1':
            pass
        else:
            flash("Descuento aplicado con autorización de supervisor.", "success")

    return _json_tras_actualizar_item_pos(detalle, ok=True)


def _asegurar_tablas_cambios():
    """Asegura que las tablas y columnas del módulo de cambios existan.

    - Las tablas se crean a través de los modelos SQLAlchemy (db.create_all() en init_db).
      Aquí solo respaldamos el caso de bases que se actualizan sin re-ejecutar init_db.
    - Las columnas nuevas (ALTER TABLE) se agregan en sintaxis ANSI portable
      (sirve tanto para MySQL como para Postgres/Neon).
    """
    if app.config.get('_CAMBIOS_TABLAS_OK'):
        return True
    try:
        insp = sa_inspect(db.engine)
        tablas = set(insp.get_table_names())
        tablas_modelos = ['cambios_operacion', 'cambios_detalle',
                          'clientes_saldos_favor', 'movimientos_saldo_favor']
        if any(t not in tablas for t in tablas_modelos):
            db.create_all()
            insp = sa_inspect(db.engine)
            tablas = set(insp.get_table_names())

        if 'cambios_operacion' in tablas:
            cols_cambio = {c['name'] for c in insp.get_columns('cambios_operacion')}
            if 'venta_origen_id' not in cols_cambio:
                db.session.execute(text(
                    "ALTER TABLE cambios_operacion ADD COLUMN venta_origen_id INTEGER NULL"
                ))
                db.session.commit()
        app.config['_CAMBIOS_TABLAS_OK'] = True
        return True
    except Exception:
        db.session.rollback()
        return False


def _producto_por_codigo_pos(codigo):
    c = (codigo or '').strip().upper()
    if not c:
        return None
    p = Producto.query.filter(db.func.upper(db.func.trim(Producto.codigo_barra)) == c).first()
    if p:
        return p
    return (
        Producto.query.filter(
            Producto.codigo_interno.isnot(None),
            db.func.upper(db.func.trim(Producto.codigo_interno)) == c,
        ).first()
    )


def _parse_lineas_cambio(raw_txt):
    rows = []
    for idx, raw in enumerate((raw_txt or '').splitlines(), start=1):
        line = (raw or '').strip()
        if not line:
            continue
        parts = [p.strip() for p in line.replace(';', ',').split(',') if p.strip() != '']
        if len(parts) < 2:
            raise ValueError(f"Línea {idx}: use formato codigo,cantidad[,precio].")
        codigo = parts[0]
        try:
            cantidad = int(parts[1])
        except (TypeError, ValueError):
            raise ValueError(f"Línea {idx}: cantidad inválida.")
        if cantidad <= 0:
            raise ValueError(f"Línea {idx}: cantidad debe ser mayor a 0.")
        precio_manual = None
        if len(parts) >= 3:
            try:
                precio_manual = float(str(parts[2]).replace('.', '').replace(',', '.'))
            except (TypeError, ValueError):
                raise ValueError(f"Línea {idx}: precio inválido.")
            if precio_manual < 0:
                raise ValueError(f"Línea {idx}: precio no puede ser negativo.")
        rows.append({'codigo': codigo, 'cantidad': cantidad, 'precio_manual': precio_manual})
    return rows


def _saldo_favor_actual(cliente_id):
    if not cliente_id:
        return 0.0
    row = ClienteSaldoFavor.query.filter_by(cliente_id=cliente_id).first()
    return float(row.saldo or 0) if row else 0.0


def _aplicar_mov_saldo_favor(cliente_id, cambio_id, tipo, monto, observacion):
    if not cliente_id or float(monto or 0) <= 0:
        return 0.0
    reg = ClienteSaldoFavor.query.filter_by(cliente_id=cliente_id).first()
    if not reg:
        reg = ClienteSaldoFavor(cliente_id=cliente_id, saldo=0)
        db.session.add(reg)
        db.session.flush()
    actual = float(reg.saldo or 0)
    if tipo == 'CREDITO':
        nuevo = actual + float(monto)
    else:
        nuevo = max(0.0, actual - float(monto))
    reg.saldo = nuevo
    db.session.add(
        MovimientoSaldoFavor(
            cliente_id=cliente_id,
            cambio_id=cambio_id,
            tipo=tipo,
            monto=float(monto),
            saldo_resultante=nuevo,
            observacion=(observacion or '')[:255] if observacion else None,
        )
    )
    return nuevo


# CAJA vales pendientes (ruta registrada en blueprints/caja.py)
def caja_pendientes():
    _redondear_montos_ventas_pendientes()
    db.session.rollback()
    hoy = datetime.now().date()
    dt_ini_hoy = datetime.combine(hoy, datetime.min.time())
    dt_fin_hoy = datetime.combine(hoy + timedelta(days=1), datetime.min.time())

    caja_apertura = obtener_caja_activa()
    cid = caja_apertura.id if caja_apertura else None
    monto_apertura = caja_apertura.monto_inicial if caja_apertura else 0

    # Documentos cobrados hoy en esta caja (alineado al turno actual)
    q_pagado_hoy = Venta.query.filter(
        Venta.estado == "Pagado",
        Venta.fecha >= dt_ini_hoy,
        Venta.fecha < dt_fin_hoy,
    )
    if cid is not None:
        q_pagado_hoy = q_pagado_hoy.filter(Venta.caja_id == cid)
    tickets_emitidos = q_pagado_hoy.count()

    monto_vendido = (
        db.session.query(db.func.coalesce(db.func.sum(Venta.monto_total), 0))
        .filter(
            Venta.estado == "Pagado",
            Venta.fecha >= dt_ini_hoy,
            Venta.fecha < dt_fin_hoy,
        )
    )
    if cid is not None:
        monto_vendido = monto_vendido.filter(Venta.caja_id == cid)
    monto_vendido = float(monto_vendido.scalar() or 0)

    borradores_pos = []
    if cid is not None:
        borradores_pos = (
            Venta.query.options(joinedload(Venta.cliente), joinedload(Venta.detalles))
            .filter(Venta.estado == "Abierta", Venta.caja_id == cid)
            .order_by(Venta.fecha.desc())
            .all()
        )
    for v in borradores_pos:
        if _venta_count_detalles(v.id) > 0:
            _reparar_precios_cero_lineas_venta_abierta(v, flash_msg=False)
            db.session.refresh(v)
        falt = _venta_validar_stock_tienda(v)
        v.stock_cobrable = len(falt) == 0
        v.stock_alerta = "; ".join(falt[:2]) if falt else ""
        v.saldo_favor_disponible = _saldo_favor_actual(v.cliente_id) if v.cliente_id else 0.0
        v.cola_es_borrador = True
        v.monto_cobro_ui = _monto_cobro_venta_ui(v)
    # Borradores sin líneas no se cobran en caja (evita modal $0); completar en POS.
    borradores_pos = [v for v in borradores_pos if (v.monto_cobro_ui or 0) > 0]

    # Cola para cobrar en esta pantalla (mismo filtro que la tabla de vales)
    vales = (
        Venta.query.options(joinedload(Venta.cliente), joinedload(Venta.detalles))
        .filter(
            Venta.estado == "Pendiente",
            Venta.metodo_pago.is_(None),
        )
        .order_by(Venta.fecha.desc())
        .all()
    )
    for v in vales:
        falt = _venta_validar_stock_tienda(v)
        v.stock_cobrable = len(falt) == 0
        v.stock_alerta = "; ".join(falt[:2]) if falt else ""
        v.saldo_favor_disponible = _saldo_favor_actual(v.cliente_id) if v.cliente_id else 0.0
        v.cola_es_borrador = False
        v.monto_cobro_ui = _monto_cobro_venta_ui(v)

    _asegurar_columnas_ventas_bodega_despacho()
    # Vales emitidos (Pendiente) primero; luego borradores POS con total > 0.
    cola_combined = list(vales) + list(borradores_pos)
    for v in cola_combined:
        v.tiene_despacho_bodega = _venta_tiene_despacho_bodega(v)
    cot_ids = [v.cotizacion_origen_id for v in vales if v.cotizacion_origen_id]
    cot_ids.extend(v.cotizacion_origen_id for v in borradores_pos if v.cotizacion_origen_id)
    cot_ids = list(dict.fromkeys(cot_ids))
    cotizaciones_map = {}
    if cot_ids:
        cotizaciones_map = {
            c.id: c
            for c in Cotizacion.query.filter(Cotizacion.id.in_(cot_ids)).all()
        }
    db.session.rollback()
    monto_pendiente = float(
        db.session.query(db.func.coalesce(db.func.sum(Venta.monto_total), 0))
        .filter(Venta.estado == "Pendiente", Venta.metodo_pago.is_(None))
        .scalar()
        or 0
    )

    q_vuelto = db.session.query(db.func.coalesce(db.func.sum(Venta.vuelto), 0)).filter(
        Venta.fecha >= dt_ini_hoy,
        Venta.fecha < dt_fin_hoy,
        Venta.estado == "Pagado",
    )
    if cid is not None:
        q_vuelto = q_vuelto.filter(Venta.caja_id == cid)
    vuelto_entregado = float(q_vuelto.scalar() or 0)

    # Créditos registrados hoy para control operativo de caja
    creditos_hoy = (
        Venta.query.filter(
            Venta.fecha >= dt_ini_hoy,
            Venta.fecha < dt_fin_hoy,
            Venta.metodo_pago == "Credito",
        )
        .order_by(Venta.fecha.desc())
        .limit(15)
        .all()
    )

    bc_vales_cierre = []
    bc_tickets_cierre = []
    if caja_apertura:
        bc_vales_cierre, bc_tickets_cierre = _documentos_bloquean_cierre_caja(caja_apertura)
    db.session.rollback()

    return render_template(
        'caja_pendientes.html',
        tickets_emitidos=tickets_emitidos,
        monto_apertura=monto_apertura,
        monto_vendido=monto_vendido,
        monto_pendiente=monto_pendiente,
        vuelto_entregado=vuelto_entregado,
        vales=vales,
        cola_combined=cola_combined,
        creditos_hoy=creditos_hoy,
        cotizaciones_map=cotizaciones_map,
        planes_cuotas_credito=PLANES_CUOTA_CREDITO_OPCIONES,
        bloquean_cierre_total=len(bc_vales_cierre) + len(bc_tickets_cierre),
        bloquean_cierre_vales=bc_vales_cierre,
        bloquean_cierre_tickets=bc_tickets_cierre,
    )


def caja_cambios():
    if not _asegurar_tablas_cambios():
        flash("No se pudo preparar tablas de cambios/saldos. Revise permisos de BD.", "danger")
        return redirect(url_for('caja_pendientes'))

    cliente_id = request.form.get('cliente_id', type=int) if request.method == 'POST' else request.args.get('cliente_id', type=int)
    cliente = Cliente.query.get(cliente_id) if cliente_id else None

    if request.method == 'POST':
        caja_activa = obtener_caja_activa()
        if not caja_activa:
            flash("Debe tener caja abierta para registrar cambios.", "warning")
            return redirect(url_for('abrir_caja'))

        try:
            devueltos = _parse_lineas_cambio(request.form.get('lineas_devueltas'))
            entregados = _parse_lineas_cambio(request.form.get('lineas_entregadas'))
        except ValueError as ex:
            flash(str(ex), "warning")
            return redirect(url_for('caja_cambios', cliente_id=cliente_id or None))

        if not devueltos:
            flash("Debe ingresar al menos una línea devuelta.", "warning")
            return redirect(url_for('caja_cambios', cliente_id=cliente_id or None))

        observacion = (request.form.get('observacion') or '').strip()[:500]
        try:
            monto_pagado = float(request.form.get('monto_pagado') or 0)
            monto_devuelto = float(request.form.get('monto_devuelto_efectivo') or 0)
        except (TypeError, ValueError):
            flash("Monto pagado/devuelto inválido.", "warning")
            return redirect(url_for('caja_cambios', cliente_id=cliente_id or None))
        if monto_pagado < 0 or monto_devuelto < 0:
            flash("Los montos no pueden ser negativos.", "warning")
            return redirect(url_for('caja_cambios', cliente_id=cliente_id or None))

        try:
            usar_saldo = float(request.form.get('usar_saldo_favor') or 0)
        except (TypeError, ValueError):
            usar_saldo = 0
        usar_saldo = max(0.0, usar_saldo)

        detalle_devueltos = []
        detalle_entregados = []
        total_devuelto = 0.0
        total_entregado = 0.0
        aid_tienda = id_almacen_tienda() or 1

        try:
            for row in devueltos:
                p = _producto_por_codigo_pos(row['codigo'])
                if not p:
                    raise ValueError(f"No existe producto devuelto con código: {row['codigo']}")
                precio = row['precio_manual']
                if precio is None:
                    precio = precio_efectivo_pos_producto(p)
                if precio <= 0:
                    raise ValueError(f"Producto devuelto sin precio válido: {p.nombre}")
                subtotal = float(precio) * int(row['cantidad'])
                detalle_devueltos.append((p, int(row['cantidad']), float(precio), subtotal))
                total_devuelto += subtotal

            for row in entregados:
                p = _producto_por_codigo_pos(row['codigo'])
                if not p:
                    raise ValueError(f"No existe producto entregado con código: {row['codigo']}")
                precio = row['precio_manual']
                if precio is None:
                    precio = precio_efectivo_pos_producto(p)
                if precio <= 0:
                    raise ValueError(f"Producto entregado sin precio válido: {p.nombre}")
                qty = int(row['cantidad'])
                disp = stock_disponible_venta_tienda(p)
                if disp < qty:
                    raise ValueError(f"Stock insuficiente en tienda para {p.nombre}. Disponible: {disp}.")
                subtotal = float(precio) * qty
                detalle_entregados.append((p, qty, float(precio), subtotal))
                total_entregado += subtotal

            saldo_actual = _saldo_favor_actual(cliente.id) if cliente else 0.0
            saldo_usado = min(saldo_actual, usar_saldo)
            neto = float(total_entregado - total_devuelto - saldo_usado)
            if neto > 0 and monto_pagado + 1e-6 < neto:
                raise ValueError(f"Faltan ${neto - monto_pagado:,.0f} por pagar para cerrar el cambio.")
            if neto <= 0:
                if monto_pagado > 0:
                    raise ValueError("No corresponde monto pagado cuando hay saldo a favor/compensación.")
                saldo_resultante = abs(neto) - monto_devuelto
                if saldo_resultante > 0 and not cliente:
                    raise ValueError("Para dejar saldo a favor debe seleccionar cliente.")
                if saldo_resultante < -1e-6:
                    raise ValueError("Monto devuelto en efectivo excede la diferencia a favor del cliente.")
            else:
                if monto_devuelto > 0:
                    raise ValueError("No corresponde devolución en efectivo cuando el neto es por pagar.")

            venta_origen_id = request.form.get('venta_origen_id', type=int)
            if venta_origen_id:
                if not Venta.query.get(venta_origen_id):
                    venta_origen_id = None

            cambio = CambioOperacion(
                cliente_id=cliente.id if cliente else None,
                caja_id=caja_activa.id,
                usuario_id=current_user.id if current_user.is_authenticated else None,
                venta_origen_id=venta_origen_id,
                total_devuelto=total_devuelto,
                total_entregado=total_entregado,
                saldo_usado=saldo_usado,
                monto_pagado=monto_pagado,
                monto_devuelto_efectivo=monto_devuelto,
                saldo_generado=max(0.0, abs(neto) - monto_devuelto) if neto <= 0 else 0.0,
                observacion=observacion or None,
            )
            db.session.add(cambio)
            db.session.flush()

            for p, qty, precio, subtotal in detalle_devueltos:
                db.session.add(CambioDetalle(
                    cambio_id=cambio.id, producto_id=p.id, tipo='DEVUELTO',
                    cantidad=qty, precio_unitario=precio, subtotal=subtotal
                ))
                if _tablas_inventario_almacen_existen():
                    _, err = ajustar_stock_almacen(p.id, aid_tienda, qty, allow_negative=False)
                    if err:
                        raise ValueError(f"{p.nombre}: {err}")
                else:
                    p.stock = int((p.stock or 0) + qty)
                _refrescar_stock_total_producto(p)
                registrar_movimiento_kardex(
                    p.id, 'ENTRADA', qty, f"Cambio #{cambio.id} (producto devuelto)",
                    usuario=current_user.nombre, id_almacen=aid_tienda,
                    referencia_tipo='cambio', referencia_id=cambio.id
                )

            for p, qty, precio, subtotal in detalle_entregados:
                db.session.add(CambioDetalle(
                    cambio_id=cambio.id, producto_id=p.id, tipo='ENTREGADO',
                    cantidad=qty, precio_unitario=precio, subtotal=subtotal
                ))
                if _tablas_inventario_almacen_existen():
                    _, err = ajustar_stock_almacen(p.id, aid_tienda, -qty, allow_negative=False)
                    if err:
                        raise ValueError(f"{p.nombre}: {err}")
                else:
                    if int(p.stock or 0) < qty:
                        raise ValueError(f"Stock insuficiente para {p.nombre}.")
                    p.stock = int((p.stock or 0) - qty)
                _refrescar_stock_total_producto(p)
                registrar_movimiento_kardex(
                    p.id, 'SALIDA', qty, f"Cambio #{cambio.id} (producto entregado)",
                    usuario=current_user.nombre, id_almacen=aid_tienda,
                    referencia_tipo='cambio', referencia_id=cambio.id
                )

            if cliente and saldo_usado > 0:
                _aplicar_mov_saldo_favor(cliente.id, cambio.id, 'DEBITO', saldo_usado, f'Uso en cambio #{cambio.id}')
            if cliente and neto <= 0:
                saldo_nuevo = max(0.0, abs(neto) - monto_devuelto)
                if saldo_nuevo > 0:
                    _aplicar_mov_saldo_favor(cliente.id, cambio.id, 'CREDITO', saldo_nuevo, f'Saldo generado cambio #{cambio.id}')

            db.session.commit()
            if neto > 0:
                flash(f"Cambio #{cambio.id} registrado. Diferencia pagada: ${monto_pagado:,.0f}.", "success")
            else:
                msg = f"Cambio #{cambio.id} registrado."
                if cliente and cambio.saldo_generado > 0:
                    msg += f" Saldo a favor generado: ${cambio.saldo_generado:,.0f}."
                elif monto_devuelto > 0:
                    msg += f" Devuelto en efectivo: ${monto_devuelto:,.0f}."
                flash(msg, "success")
            return redirect(
                url_for(
                    'caja_cambios',
                    cliente_id=cliente.id if cliente else None,
                    ultimo_cambio=cambio.id,
                )
            )
        except Exception as ex:
            db.session.rollback()
            flash(f"No se pudo registrar el cambio: {ex}", "danger")
            return redirect(url_for('caja_cambios', cliente_id=cliente.id if cliente else None))

    clientes = Cliente.query.order_by(Cliente.nombre.asc()).all()
    recientes = CambioOperacion.query.order_by(CambioOperacion.id.desc()).limit(20).all()
    saldo_actual = _saldo_favor_actual(cliente.id) if cliente else 0.0
    ultimo_cambio = request.args.get('ultimo_cambio', type=int)
    cambio_reciente = CambioOperacion.query.get(ultimo_cambio) if ultimo_cambio else None
    return render_template(
        'caja_cambios.html',
        clientes=clientes,
        cliente_sel=cliente,
        saldo_actual=saldo_actual,
        recientes=recientes,
        cambio_reciente=cambio_reciente,
    )


def api_cambios_producto(codigo):
    p = _producto_por_codigo_pos(codigo)
    if not p:
        return jsonify(ok=False, mensaje='Producto no encontrado.'), 404
    precio = float(precio_efectivo_pos_producto(p) or 0)
    stock_t = stock_disponible_venta_tienda(p)
    return jsonify(
        ok=True,
        producto={
            'id': p.id,
            'codigo_barra': (p.codigo_barra or '').strip(),
            'codigo_interno': (p.codigo_interno or '').strip(),
            'nombre': p.nombre,
            'precio': precio,
            'stock_tienda': int(stock_t if stock_t is not None else (p.stock or 0)),
        }
    )


def _devoluciones_previas_por_producto(venta_id):
    rows = (
        db.session.query(CambioDetalle.producto_id, db.func.coalesce(db.func.sum(CambioDetalle.cantidad), 0))
        .join(CambioOperacion, CambioOperacion.id == CambioDetalle.cambio_id)
        .filter(
            CambioOperacion.venta_origen_id == venta_id,
            CambioDetalle.tipo == 'DEVUELTO',
        )
        .group_by(CambioDetalle.producto_id)
        .all()
    )
    return {int(pid): int(qty or 0) for pid, qty in rows}


def _venta_a_dict_para_cambio(v):
    devueltas_restantes = _devoluciones_previas_por_producto(v.id)
    detalles = []
    for d in (v.detalles or []):
        prod = d.producto
        producto_id = int(d.id_producto)
        cantidad_vendida = int(d.cantidad or 0)
        ya_devuelta_disponible = int(devueltas_restantes.get(producto_id, 0) or 0)
        ya_devuelta_linea = min(cantidad_vendida, ya_devuelta_disponible)
        cantidad_pendiente = max(0, cantidad_vendida - ya_devuelta_linea)
        devueltas_restantes[producto_id] = max(0, ya_devuelta_disponible - ya_devuelta_linea)
        if cantidad_pendiente <= 0:
            continue
        detalles.append({
            'producto_id': producto_id,
            'codigo_barra': ((prod.codigo_barra or '').strip() if prod else ''),
            'codigo_interno': ((prod.codigo_interno or '').strip() if prod else ''),
            'nombre': (prod.nombre if prod else f"Producto #{producto_id}"),
            'cantidad': cantidad_pendiente,
            'cantidad_original': cantidad_vendida,
            'cantidad_ya_devuelta': ya_devuelta_linea,
            'precio_unitario': float(d.precio_unitario or 0),
            'descuento': float(d.descuento or 0),
            'subtotal': float(d.subtotal or 0),
        })
    cambios_previos = CambioOperacion.query.filter_by(venta_origen_id=v.id).count()
    return {
        'id': v.id,
        'fecha': v.fecha.strftime('%d/%m/%Y %H:%M') if v.fecha else None,
        'estado': v.estado or '',
        'monto_total': float(v.monto_total or 0),
        'cliente_id': v.cliente_id,
        'cliente_nombre': v.cliente.nombre if v.cliente else None,
        'cliente_rut': (v.cliente.rut if v.cliente else None),
        'tiene_devoluciones_previas': cambios_previos > 0,
        'devolucion_completa': cambios_previos > 0 and not detalles,
        'detalles': detalles,
    }


def _pos_tv_reco_item_dict(prod, motivo=''):
    """Ítem enriquecido para TV cliente (precio POS efectivo + imagen)."""
    if not prod:
        return None
    try:
        precio = int(round(float(precio_efectivo_pos_producto(prod) or prod.precio_venta or 0)))
    except (TypeError, ValueError):
        precio = 0
    img = (getattr(prod, 'imagen_url', None) or '').strip()
    if not img:
        try:
            from services.chilemat_ficha_service import imagen_url_para_producto_erp

            img = imagen_url_para_producto_erp(prod.id) or ''
        except Exception:
            img = ''
    return {
        'id': int(prod.id),
        'nombre': (prod.nombre or 'Producto')[:80],
        'precio': precio,
        'imagen_url': img[:500] if img else None,
        'motivo': (motivo or '').strip()[:120],
    }


