def _pos_tv_precio_producto(prod):
    try:
        return float(precio_efectivo_pos_producto(prod) or prod.precio_venta or 0)
    except (TypeError, ValueError):
        return 0.0


def _pos_tv_ancla_texto(combined_lower):
    if 'clavo' in combined_lower or re.search(r'\bclav', combined_lower):
        return 'los clavos'
    if 'tornillo' in combined_lower:
        return 'los tornillos'
    if 'escuadra' in combined_lower:
        return 'las escuadras'
    if 'perno' in combined_lower:
        return 'los pernos'
    return 'sus fijaciones'


def _pos_tv_detectar_familias(combined_lower):
    fam = []
    if any(t in combined_lower for t in _POS_TV_FIJACION_TRIGGERS):
        fam.append('fijacion')
    if any(t in combined_lower for t in _POS_TV_OBRA_PESADA_TRIGGERS):
        fam.append('obra_pesada')
    if any(t in combined_lower for t in ('pintura', 'latex', 'esmalte', 'barniz', 'sellador')):
        fam.append('pintura')
    if any(t in combined_lower for t in ('pvc', 'tuber', 'tubo', 'cañer', 'caner', 'codo pvc')):
        fam.append('pvc')
    if any(t in combined_lower for t in ('madera', 'mdf', 'melamina', 'contrachap')):
        fam.append('madera')
    if any(t in combined_lower for t in ('fierro', 'perfil', 'malla acma', 'alambre', 'clavo esp')):
        if 'fijacion' not in fam:
            fam.append('madera')
    return fam or ['general']


def _pos_tv_contexto_carrito(prods_cart, venta):
    combined_lower = ' '.join(_pos_blob_producto(p) for p in (prods_cart or [])).lower()
    familias = _pos_tv_detectar_familias(combined_lower)
    ticket = float(getattr(venta, 'monto_total', None) or 0)
    ticket_bajo = ticket < 28000
    ticket_medio = ticket < 75000
    obra_pesada = 'obra_pesada' in familias
    fijacion_dom = 'fijacion' in familias and not obra_pesada
    permite_electrico = obra_pesada or (
        not fijacion_dom and ticket >= 75000 and any(
            t in combined_lower for t in ('madera', 'fierro', 'perfil', 'tabique', 'hormigon', 'cemento')
        )
    )
    return {
        'combined_lower': combined_lower,
        'familias': familias,
        'familia_principal': familias[0],
        'ticket_total': ticket,
        'ticket_bajo': ticket_bajo,
        'ticket_medio': ticket_medio,
        'permite_electrico_caro': permite_electrico,
        'ancla_label': _pos_tv_ancla_texto(combined_lower),
        'fijacion_dom': fijacion_dom,
    }


def _pos_tv_perfil_recomendacion(ctx):
    fam = ctx.get('familia_principal') or 'general'
    if fam == 'fijacion' and ctx.get('fijacion_dom'):
        return _POS_TV_PERFIL_FIJACION
    if fam == 'obra_pesada':
        return _POS_TV_PERFIL_OBRA
    if fam == 'pintura':
        return _POS_TV_PERFIL_PINTURA
    if fam == 'pvc':
        return _POS_TV_PERFIL_PVC
    if fam == 'madera':
        return _POS_TV_PERFIL_MADERA
    if 'fijacion' in ctx.get('familias', []):
        return _POS_TV_PERFIL_FIJACION
    return _POS_TV_PERFIL_GENERAL


def _pos_tv_max_precio_item(ctx, perfil):
    if ctx.get('permite_electrico_caro') or perfil.get('permite_electrico_caro'):
        return None
    ticket = float(ctx.get('ticket_total') or 0)
    if ctx.get('ticket_bajo'):
        return max(12000, min(32000, ticket * 1.35 if ticket > 0 else 28000))
    if ctx.get('ticket_medio'):
        return 48000
    return 65000


def _pos_tv_nombre_excluido(nombre_lower, exclude_patterns, max_precio, prod):
    if any(ex in nombre_lower for ex in (exclude_patterns or ())):
        return True
    if max_precio and _pos_tv_precio_producto(prod) > max_precio:
        return True
    return False


def _pos_tv_candidates_for_keyword(kw, excluded_ids, limit=50):
    likes = _pos_cross_sell_sql_likes_for_keyword(kw)
    if not likes:
        return []
    ors = []
    for like in likes:
        ors.append(
            db.or_(
                db.func.lower(Producto.nombre).like(like),
                db.func.lower(db.func.coalesce(Producto.subcategoria, '')).like(like),
                db.func.lower(db.func.coalesce(Producto.categoria, '')).like(like),
            )
        )
    q = Producto.query.filter(Producto.activo == True, Producto.stock > 0, db.or_(*ors))
    if excluded_ids:
        q = q.filter(~Producto.id.in_(list(excluded_ids)))
    canon_kw = _pos_cross_sell_canonical_suggest_keyword(kw)
    if canon_kw == 'lija':
        q = q.filter(~db.func.lower(Producto.nombre).like('%lijador%'))
    cands = q.order_by(Producto.precio_venta.asc(), Producto.nombre.asc()).limit(limit).all()
    if not cands and canon_kw and canon_kw in _POS_CROSS_SELL_KW_LIKE_PATTERNS:
        like_fallback = f'%{canon_kw}%'
        q2 = Producto.query.filter(
            Producto.activo == True,
            Producto.stock > 0,
            db.or_(
                db.func.lower(Producto.nombre).like(like_fallback),
                db.func.lower(db.func.coalesce(Producto.subcategoria, '')).like(like_fallback),
                db.func.lower(db.func.coalesce(Producto.categoria, '')).like(like_fallback),
            ),
        )
        if excluded_ids:
            q2 = q2.filter(~Producto.id.in_(list(excluded_ids)))
        if canon_kw == 'lija':
            q2 = q2.filter(~db.func.lower(Producto.nombre).like('%lijador%'))
        cands = q2.order_by(Producto.precio_venta.asc(), Producto.nombre.asc()).limit(limit).all()
    return cands


def _pos_tv_score_candidato(prod, kw, ctx, max_precio):
    n = (prod.nombre or '').lower()
    sc = _pos_cross_sell_rank_sugerencia(prod, kw)
    precio = _pos_tv_precio_producto(prod)
    if ctx.get('ticket_bajo'):
        sc += max(0.0, 35.0 - precio / 1200.0)
    elif ctx.get('ticket_medio'):
        sc += max(0.0, 18.0 - precio / 2500.0)
    if max_precio and precio <= max_precio * 0.65:
        sc += 12.0
    if any(ex in n for ex in _POS_TV_ELECTRIC_EXPENSIVE):
        sc -= 200.0
    return sc, precio


def _pos_tv_pick_coherente(kw, motivo, seen, ctx, perfil):
    max_precio = _pos_tv_max_precio_item(ctx, perfil)
    exclude = tuple(perfil.get('exclude_nombre') or ())
    if not ctx.get('permite_electrico_caro'):
        exclude = tuple(set(exclude + _POS_TV_ELECTRIC_EXPENSIVE))
    best_p, best_sc = None, -99999.0
    for p in _pos_tv_candidates_for_keyword(kw, seen):
        n = (p.nombre or '').lower()
        if _pos_tv_nombre_excluido(n, exclude, max_precio, p):
            continue
        sc, _ = _pos_tv_score_candidato(p, kw, ctx, max_precio)
        if sc > best_sc:
            best_sc, best_p = sc, p
    if best_p is None or best_sc < 8.0:
        return None
    return best_p, motivo


def _pos_tv_productos_historial_cliente(cliente_id, exclude_ids, ctx, perfil, limit=2):
    """Productos que el cliente ya compró (Pagado), filtrados por coherencia TV."""
    if not cliente_id:
        return []
    try:
        cid = int(cliente_id)
    except (TypeError, ValueError):
        return []
    excl = {int(x) for x in (exclude_ids or []) if x is not None}
    cut = datetime.now() - timedelta(days=420)
    pid_counts = defaultdict(int)
    rows = (
        db.session.query(DetalleVenta.id_producto)
        .join(Venta, Venta.id == DetalleVenta.id_venta)
        .filter(
            Venta.cliente_id == cid,
            Venta.estado == 'Pagado',
            Venta.fecha >= cut,
            DetalleVenta.id_producto.isnot(None),
        )
        .all()
    )
    for (pid,) in rows:
        try:
            ip = int(pid)
        except (TypeError, ValueError):
            continue
        if ip not in excl:
            pid_counts[ip] += 1
    if not pid_counts:
        return []
    top_ids = sorted(pid_counts.keys(), key=lambda x: -pid_counts[x])[: max(limit * 3, 6)]
    prods = (
        Producto.query.filter(
            Producto.id.in_(top_ids),
            Producto.activo == True,
            Producto.stock > 0,
        )
        .all()
    )
    prods.sort(key=lambda p: -pid_counts.get(p.id, 0))
    max_precio = _pos_tv_max_precio_item(ctx, perfil)
    exclude = tuple(perfil.get('exclude_nombre') or ())
    if not ctx.get('permite_electrico_caro'):
        exclude = tuple(set(exclude + _POS_TV_ELECTRIC_EXPENSIVE))
    out = []
    for p in prods:
        n = (p.nombre or '').lower()
        if _pos_tv_nombre_excluido(n, exclude, max_precio, p):
            continue
        out.append(p)
        if len(out) >= limit:
            break
    return out


def _pos_tv_same_category_fill(prods_cart, exclude_ids, max_add=4):
    """Otros productos de la misma categoría/subcategoría con stock."""
    excl = set(exclude_ids or [])
    cats = {(p.categoria or '').strip() for p in (prods_cart or []) if (p.categoria or '').strip()}
    subs = {(p.subcategoria or '').strip() for p in (prods_cart or []) if (p.subcategoria or '').strip()}
    ors = []
    for c in cats:
        ors.append(Producto.categoria == c)
    for s in subs:
        ors.append(Producto.subcategoria == s)
    if not ors:
        return []
    q = Producto.query.filter(Producto.activo == True, Producto.stock > 0, db.or_(*ors))
    if excl:
        q = q.filter(~Producto.id.in_(list(excl)))
    return q.order_by(Producto.stock.desc(), Producto.nombre.asc()).limit(max_add).all()


def _pos_tv_popular_fill(exclude_ids, max_add=4):
    """Último recurso: productos activos con más stock (ferretería general)."""
    excl = set(exclude_ids or [])
    q = Producto.query.filter(Producto.activo == True, Producto.stock > 0)
    if excl:
        q = q.filter(~Producto.id.in_(list(excl)))
    return q.order_by(Producto.stock.desc(), Producto.nombre.asc()).limit(max_add).all()


def _pos_live_wall_recomendaciones_tv(venta):
    """
    Recomendaciones coherentes para TV cliente (sin sesión POS).
    Perfil por familia de producto + tope de precio según ticket.
    """
    if not venta or not venta.detalles:
        return None
    pids = [int(d.id_producto) for d in venta.detalles if d.id_producto]
    if not pids:
        return None

    prods_cart = Producto.query.filter(Producto.id.in_(pids)).all()
    ctx = _pos_tv_contexto_carrito(prods_cart, venta)
    perfil = _pos_tv_perfil_recomendacion(ctx)
    ancla = ctx.get('ancla_label') or 'sus productos'

    titulo = (perfil.get('titulo') or 'LhexIA IA recomienda para su compra')[:120]
    try:
        subtitulo = (perfil.get('subtitulo') or 'Sugerencias según lo que lleva hoy').format(ancla=ancla)[:200]
    except (KeyError, ValueError):
        subtitulo = 'Sugerencias según lo que lleva hoy'

    seen = set(pids)
    candidatos = []

    for kw, motivo_tpl, prio in perfil.get('sugerencias') or ():
        if len(candidatos) >= 6:
            break
        try:
            motivo = motivo_tpl.format(ancla=ancla)
        except (KeyError, ValueError):
            motivo = motivo_tpl
        picked = _pos_tv_pick_coherente(kw, motivo, seen, ctx, perfil)
        if not picked:
            continue
        prod, mot = picked
        if prod.id in seen:
            continue
        seen.add(prod.id)
        candidatos.append((prio, prod.id, mot))

    if venta.cliente_id and len(candidatos) < 4:
        for prod in _pos_tv_productos_historial_cliente(venta.cliente_id, seen, ctx, perfil, limit=2):
            if prod.id in seen:
                continue
            seen.add(prod.id)
            candidatos.append((72, prod.id, 'Lo compró antes — le puede servir de nuevo'))

    familia_perfil = perfil.get('familia') or 'general'
    if len(candidatos) < 4 and familia_perfil in ('obra_pesada', 'pvc', 'pintura'):
        panel = _pos_cross_sell_match_rules(pids, rejected_rule_ids=[])
        if panel and isinstance(panel, dict):
            stat = (panel.get('mensaje') or panel.get('stat_copy') or '').strip()
            if stat and familia_perfil != 'fijacion':
                subtitulo = stat[:200]
            prio_base = 68
            for it in (panel.get('items') or [])[:4]:
                if not isinstance(it, dict):
                    continue
                try:
                    pid = int(it.get('id') or 0)
                except (TypeError, ValueError):
                    continue
                if not pid or pid in seen:
                    continue
                prod = db.session.get(Producto, pid)
                if not prod:
                    continue
                n = (prod.nombre or '').lower()
                max_p = _pos_tv_max_precio_item(ctx, perfil)
                if _pos_tv_nombre_excluido(n, perfil.get('exclude_nombre'), max_p, prod):
                    continue
                seen.add(pid)
                motivo = stat[:120] if stat else 'Suele llevarse junto en esta compra'
                candidatos.append((prio_base, pid, motivo))
                prio_base -= 2

    if len(candidatos) < 2:
        for kw, motivo_tpl, prio in _POS_TV_PERFIL_GENERAL.get('sugerencias', ()):
            picked = _pos_tv_pick_coherente(kw, motivo_tpl, seen, ctx, _POS_TV_PERFIL_GENERAL)
            if not picked:
                continue
            prod, mot = picked
            if prod.id in seen:
                continue
            seen.add(prod.id)
            candidatos.append((prio - 20, prod.id, mot))
            if len(candidatos) >= 4:
                break

    candidatos.sort(key=lambda x: (-x[0], x[1]))
    items_tv = []
    for _, pid, motivo in candidatos:
        if len(items_tv) >= 4:
            break
        prod = db.session.get(Producto, pid)
        row = _pos_tv_reco_item_dict(prod, motivo)
        if row and row.get('id'):
            items_tv.append(row)

    if len(items_tv) < 2:
        return None

    items_tv.sort(key=lambda x: int(x.get('precio') or 0))

    return {
        'titulo': titulo,
        'subtitulo': subtitulo,
        'items': items_tv[:4],
    }


def _parse_folio_vale(q):
    """Acepta 'VL000123', 'VL123', '123' y devuelve int o None."""
    if not q:
        return None
    s = q.strip().upper()
    if s.startswith('VL'):
        s = s[2:]
    s = s.lstrip('0') or '0'
    try:
        return int(s)
    except ValueError:
        return None


def _cliente_por_rut_cambios(q):
    """Busca cliente por RUT (formato flexible). None si no hay coincidencia."""
    q = (q or '').strip()
    if not q:
        return None
    rut_limpio = q.replace('.', '').replace('-', '').replace(' ', '').upper()
    rut_db_normalizado = q.replace('.', '').upper()
    if '-' not in rut_db_normalizado and len(rut_db_normalizado) >= 2:
        rut_db_normalizado = rut_db_normalizado[:-1] + '-' + rut_db_normalizado[-1]
    return (
        Cliente.query.filter(
            or_(
                Cliente.rut == q,
                Cliente.rut == rut_db_normalizado,
                db.func.replace(db.func.replace(Cliente.rut, '.', ''), '-', '') == rut_limpio,
            )
        ).first()
    )


def _json_cambios_lista_ventas_cliente(cliente):
    ventas = (
        Venta.query.filter(Venta.cliente_id == cliente.id)
        .order_by(Venta.fecha.desc(), Venta.id.desc())
        .limit(15)
        .all()
    )
    return jsonify(
        ok=True,
        modo='lista',
        cliente={
            'id': cliente.id,
            'nombre': cliente.nombre,
            'rut': cliente.rut or '',
        },
        ventas=[
            {
                'id': v.id,
                'fecha': v.fecha.strftime('%d/%m/%Y %H:%M') if v.fecha else '',
                'estado': v.estado or '',
                'monto_total': float(v.monto_total or 0),
            }
            for v in ventas
        ],
    )


def api_cambios_buscar_venta():
    """Busca venta original para precargar líneas en cambio.

    Reglas de búsqueda:
      - Prefijo VL o folio numérico → venta directa.
      - RUT (con guión/puntos o dígitos válidos) → lista de ventas del cliente.
      - Si no encuentra nada, retorna ok=False con mensaje claro.
    """
    q = (request.args.get('q') or '').strip()
    if not q:
        return jsonify(ok=False, mensaje='Indique folio o RUT a buscar.'), 400

    qup = q.upper()

    if qup.startswith('VL'):
        folio = _parse_folio_vale(q)
        if folio is None:
            return jsonify(ok=False, mensaje=f'Folio inválido: {q}'), 400
        v = Venta.query.get(folio)
        if not v:
            return jsonify(ok=False, mensaje=f'No existe vale con folio #{folio}.'), 404
        return jsonify(ok=True, modo='venta', venta=_venta_a_dict_para_cambio(v))

    parece_rut = ('-' in q) or ('.' in q) or validar_rut(q)
    if parece_rut:
        cliente = _cliente_por_rut_cambios(q)
        if not cliente:
            return jsonify(ok=False, mensaje=f'No se encontró cliente con RUT {q}.'), 404
        return _json_cambios_lista_ventas_cliente(cliente)

    if q.isdigit():
        folio = int(q.lstrip('0') or '0')
        if folio > 0:
            v = Venta.query.get(folio)
            if v:
                return jsonify(ok=True, modo='venta', venta=_venta_a_dict_para_cambio(v))
        return jsonify(ok=False, mensaje=f'No existe vale con folio #{folio}.'), 404

    return jsonify(ok=False, mensaje='Sin resultados. Pruebe folio (ej. 1234 o VL001234) o RUT del cliente.'), 404


def api_cambios_venta_detalle(id):
    v = Venta.query.get_or_404(id)
    return jsonify(ok=True, venta=_venta_a_dict_para_cambio(v))


def ticket_cambio(id):
    cambio = CambioOperacion.query.get_or_404(id)
    devueltos = [d for d in (cambio.detalles or []) if (d.tipo or '').upper() == 'DEVUELTO']
    entregados = [d for d in (cambio.detalles or []) if (d.tipo or '').upper() == 'ENTREGADO']
    neto = float((cambio.total_entregado or 0) - (cambio.total_devuelto or 0) - (cambio.saldo_usado or 0))
    return render_template(
        'ticket_cambio.html',
        cambio=cambio,
        devueltos=devueltos,
        entregados=entregados,
        neto=neto,
        auto_print=(request.args.get('auto_print') == '1'),
    )


def caja_cambios_historial():
    if not _asegurar_tablas_cambios():
        flash("No se pudo preparar tablas de cambios/saldos. Revise permisos de BD.", "danger")
        return redirect(url_for('caja_pendientes'))

    q_cliente_id = request.args.get('cliente_id', type=int)
    q_vendedor = (request.args.get('vendedor') or '').strip()
    q_desde = (request.args.get('desde') or '').strip()
    q_hasta = (request.args.get('hasta') or '').strip()

    q = CambioOperacion.query

    if q_cliente_id:
        q = q.filter(CambioOperacion.cliente_id == q_cliente_id)

    if q_vendedor:
        like_v = f"%{q_vendedor}%"
        q = (
            q.outerjoin(Usuario, CambioOperacion.usuario_id == Usuario.id)
            .filter(or_(Usuario.nombre.like(like_v), Usuario.correo.like(like_v)))
            .distinct()
        )

    try:
        if q_desde:
            desde_dt = datetime.strptime(q_desde, '%Y-%m-%d')
            q = q.filter(CambioOperacion.fecha >= desde_dt)
    except ValueError:
        flash("La fecha 'desde' no es válida.", "warning")

    try:
        if q_hasta:
            hasta_dt = datetime.strptime(q_hasta, '%Y-%m-%d') + timedelta(days=1)
            q = q.filter(CambioOperacion.fecha < hasta_dt)
    except ValueError:
        flash("La fecha 'hasta' no es válida.", "warning")

    limite = 500
    cambios = q.order_by(CambioOperacion.fecha.desc(), CambioOperacion.id.desc()).limit(limite).all()

    total_cambios = len(cambios)
    sum_devuelto = sum(float(c.total_devuelto or 0) for c in cambios)
    sum_entregado = sum(float(c.total_entregado or 0) for c in cambios)
    sum_saldo_usado = sum(float(c.saldo_usado or 0) for c in cambios)
    sum_pagado = sum(float(c.monto_pagado or 0) for c in cambios)
    sum_devuelto_efectivo = sum(float(c.monto_devuelto_efectivo or 0) for c in cambios)
    sum_saldo_generado = sum(float(c.saldo_generado or 0) for c in cambios)
    neto_rango = sum_entregado - sum_devuelto - sum_saldo_usado

    clientes = Cliente.query.order_by(Cliente.nombre.asc()).all()

    return render_template(
        'caja_cambios_historial.html',
        cambios=cambios,
        total_cambios=total_cambios,
        sum_devuelto=sum_devuelto,
        sum_entregado=sum_entregado,
        sum_saldo_usado=sum_saldo_usado,
        sum_pagado=sum_pagado,
        sum_devuelto_efectivo=sum_devuelto_efectivo,
        sum_saldo_generado=sum_saldo_generado,
        neto_rango=neto_rango,
        clientes=clientes,
        q_cliente_id=q_cliente_id,
        q_vendedor=q_vendedor,
        q_desde=q_desde,
        q_hasta=q_hasta,
        limite=limite,
    )


def caja_saldos_favor():
    """Clientes con saldo a favor vigente por devoluciones/cambios."""
    if not _asegurar_tablas_cambios():
        flash("No se pudo preparar tablas de saldos a favor. Revise permisos de BD.", "danger")
        return redirect(url_for('caja_pendientes'))

    q = (request.args.get('q') or '').strip()
    consulta = (
        ClienteSaldoFavor.query
        .join(Cliente, Cliente.id == ClienteSaldoFavor.cliente_id)
        .filter(ClienteSaldoFavor.saldo > 0)
    )
    if q:
        like_q = f"%{q}%"
        consulta = consulta.filter(or_(Cliente.nombre.like(like_q), Cliente.rut.like(like_q)))

    saldos = (
        consulta
        .order_by(ClienteSaldoFavor.saldo.desc(), Cliente.nombre.asc())
        .limit(500)
        .all()
    )
    total_saldo = sum(float(s.saldo or 0) for s in saldos)
    clientes_con_saldo = len(saldos)
    ultimos_movs = {}
    if saldos:
        ids = [s.cliente_id for s in saldos]
        movimientos = (
            MovimientoSaldoFavor.query
            .filter(MovimientoSaldoFavor.cliente_id.in_(ids))
            .order_by(MovimientoSaldoFavor.fecha.desc(), MovimientoSaldoFavor.id.desc())
            .all()
        )
        for mov in movimientos:
            ultimos_movs.setdefault(mov.cliente_id, mov)

    return render_template(
        'caja_saldos_favor.html',
        saldos=saldos,
        ultimos_movs=ultimos_movs,
        total_saldo=total_saldo,
        clientes_con_saldo=clientes_con_saldo,
        busqueda=q,
        limite=500,
    )


def _anular_venta_colacaja_metadatos_y_permiso(venta, caja_act):
    """Valida anulación desde cola (vale sin cobrar / borrador POS). Raise ValueError con mensaje para el usuario."""
    st = (venta.estado or '').strip()
    mp = venta.metodo_pago
    mp_vacio = mp is None or (isinstance(mp, str) and not mp.strip())
    puede_pendiente = st == 'Pendiente' and mp_vacio
    puede_borrador = (
        st == 'Abierta'
        and mp_vacio
        and caja_act
        and (venta.caja_id is None or venta.caja_id == caja_act.id)
    )
    if not puede_pendiente and not puede_borrador:
        raise ValueError(
            'Solo se pueden anular vales pendientes de cobro o borradores POS abiertos '
            '(sin método de pago) de la caja actual.'
        )
    if puede_pendiente and _venta_tiene_despacho_bodega(venta):
        if not (
            usuario_tiene_permiso('anular_vale_con_despacho_bodega')
            or usuario_tiene_permiso('gestionar_usuarios')
        ):
            raise ValueError(
                'Este vale tiene despacho registrado en bodega (voz). '
                'Se requiere permiso anular_vale_con_despacho_bodega o gestionar_usuarios para anular y revertir stock.'
            )
    datos_antes = {
        'estado': st,
        'bodega_despacho_estado': getattr(venta, 'bodega_despacho_estado', None),
        'bodega_despacho_json': getattr(venta, 'bodega_despacho_json', None),
    }
    hubo_despacho = bool(puede_pendiente and _venta_tiene_despacho_bodega(venta))
    return {
        'st': st,
        'datos_antes': datos_antes,
        'hubo_despacho': hubo_despacho,
        'puede_pendiente': puede_pendiente,
    }


def _anular_venta_colacaja_mutar(venta, motivo, usr_an, meta):
    if meta['hubo_despacho']:
        _revertir_stock_bodega_por_anulacion(venta, usr_an or 'Caja')
    venta.estado = 'Anulada'
    venta.motivo_anulacion = motivo or None
    venta.fecha_anulacion = datetime.now()
    venta.usuario_anulacion = usr_an


def anular_vale_caja(id):
    """Vale emitido y no cobrado: cliente no retorna. Revierte despacho de bodega si hubo (voz) con permiso extra."""
    _asegurar_columnas_ventas_bodega_despacho()
    venta = Venta.query.options(joinedload(Venta.detalles)).get_or_404(id)
    caja_act = obtener_caja_activa()
    motivo = (request.form.get('motivo') or '').strip()[:500]
    usr_an = (current_user.nombre or '')[:80] if current_user.is_authenticated else None
    try:
        meta = _anular_venta_colacaja_metadatos_y_permiso(venta, caja_act)
    except ValueError as ve:
        msg = str(ve)
        flash(msg, 'danger' if 'despacho registrado' in msg else 'warning')
        return redirect(url_for('caja_pendientes'))
    try:
        with transaccion_critica():
            _anular_venta_colacaja_mutar(venta, motivo, usr_an, meta)
        _audit_log(
            'anular_vale',
            'venta',
            venta.id,
            usuario=usr_an,
            datos_antes=meta['datos_antes'],
            datos_despues={
                'estado': 'Anulada',
                'motivo': motivo,
                'revirtio_bodega': meta['hubo_despacho'],
            },
        )
        db.session.commit()
    except Exception as ex:
        db.session.rollback()
        err = str(ex).lower()
        if 'unknown column' in err or 'motivo_anulacion' in err:
            flash(
                'Ejecutá en MySQL la migración sql/2026_05_04_ventas_anulacion_vale.sql y vuelve a intentar.',
                'danger',
            )
        else:
            flash(f'No se pudo anular el vale: {ex}', 'danger')
        return redirect(url_for('caja_pendientes'))
    st = meta['st']
    hubo_despacho = meta['hubo_despacho']
    tipo_doc = 'Borrador POS' if st == 'Abierta' else 'Vale'
    if hubo_despacho:
        flash(
            f'{tipo_doc} #{venta.id} anulado. Se revirtió el stock de bodega asociado al despacho por voz.',
            'success',
        )
    else:
        flash(f'{tipo_doc} #{venta.id} anulado. No descontó stock de tienda (no estaba cobrado).', 'success')
    return redirect(url_for('caja_pendientes'))


def _cobro_respuesta_json_solicitada() -> bool:
    """True si el cliente (tótem / SPA) espera JSON en lugar de redirect HTML."""
    if (request.args.get('formato') or '').strip().lower() == 'json':
        return True
    accept = (request.headers.get('Accept') or '').lower()
    return 'application/json' in accept


def procesar_cobro_caja(id):
    db.session.rollback()
    venta = Venta.query.options(joinedload(Venta.cliente), joinedload(Venta.detalles)).get_or_404(id)
    if (venta.estado or '').strip() == 'Abierta':
        venta.recalcular_total()
    caja_activa = Caja.query.filter_by(estado="Abierta").order_by(Caja.id.desc()).first()
    metodo = request.form.get('metodo_pago')
    tipo_doc = request.form.get('tipo_documento', 'Boleta')
    if venta.estado == 'Anulada':
        flash(f"El vale #{venta.id} est├í anulado y no puede cobrarse.", "warning")
        return redirect(url_for('caja_pendientes'))
    if venta.estado == 'Abierta':
        if not caja_activa or (venta.caja_id and venta.caja_id != caja_activa.id):
            flash("Este borrador no corresponde a la caja abierta; no se puede cobrar desde aqu├¡.", "warning")
            return redirect(url_for('caja_pendientes'))
    elif venta.estado != 'Pendiente':
        flash(f"El documento #{venta.id} no est├í en cola de cobro.", "warning")
        return redirect(url_for('caja_pendientes'))
    if venta.metodo_pago is not None:
        flash(f"El vale #{venta.id} ya fue procesado anteriormente.", "info")
        return redirect(url_for('caja_pendientes'))
    faltantes_stock = _venta_validar_stock_tienda(venta)
    if faltantes_stock:
        flash(
            "No se puede cobrar el vale por stock insuficiente en tienda: "
            + "; ".join(faltantes_stock[:3]),
            "warning",
        )
        return redirect(url_for('caja_pendientes'))

    try:
        monto_recibido = float(request.form.get('monto_recibido') or 0)
        usar_saldo_favor = float(request.form.get('usar_saldo_favor') or 0)
    except (TypeError, ValueError):
        flash("Monto recibido inv├ílido.", "warning")
        return redirect(url_for('caja_pendientes'))
    if monto_recibido < 0 or usar_saldo_favor < 0:
        flash("Los montos no pueden ser negativos.", "warning")
        return redirect(url_for('caja_pendientes'))
    saldo_cliente_actual = _saldo_favor_actual(venta.cliente_id) if venta.cliente_id else 0.0
    saldo_favor_usado = min(float(usar_saldo_favor or 0), saldo_cliente_actual, float(venta.monto_total or 0))
    total_a_pagar = max(0.0, float(venta.monto_total or 0) - saldo_favor_usado)

    try:
        from core.application.bootstrap import build_descontar_stock_cobro_service

        stock_cobro_svc = build_descontar_stock_cobro_service()
        lineas_stock = stock_cobro_svc.preparar_lineas(venta.id)

        # Partimos la transacci├│n real desde un estado limpio. Esto evita que
        # un SELECT/validaci├│n previa deje Postgres en InFailedSqlTransaction.
        db.session.rollback()
        venta = Venta.query.options(joinedload(Venta.cliente), joinedload(Venta.detalles)).get_or_404(id)
        if (venta.estado or '').strip() == 'Abierta':
            _reparar_precios_cero_lineas_venta_abierta(venta, flash_msg=False)
            venta = Venta.query.options(joinedload(Venta.cliente), joinedload(Venta.detalles)).get_or_404(id)
            venta.recalcular_total()
            if float(venta.monto_total or 0) <= 0:
                bruto = _monto_cobro_venta_bruto_sql(venta.id)
                if bruto > 0:
                    venta.monto_total = float(bruto)
                    venta.desglosar_iva()
        caja_activa = Caja.query.filter_by(estado="Abierta").order_by(Caja.id.desc()).first()

        try:
            stock_validar_invariante_venta(venta)
        except ValueError as inv_e:
            flash(str(inv_e), 'danger')
            return redirect(url_for('caja_pendientes'))

        # Validaciones de pago fuera del savepoint (evita rollback/redirect dentro de transaccion_critica).
        if metodo != "Credito":
            if saldo_favor_usado > 0:
                if not venta.cliente_id:
                    flash("Para usar saldo a favor el vale debe tener cliente identificado.", "warning")
                    return redirect(url_for('caja_pendientes'))
                saldo_cliente_actual = _saldo_favor_actual(venta.cliente_id)
                saldo_favor_usado = min(saldo_favor_usado, saldo_cliente_actual, float(venta.monto_total or 0))
                total_a_pagar = max(0.0, float(venta.monto_total or 0) - saldo_favor_usado)
            if monto_recibido < total_a_pagar:
                flash(
                    "El monto recibido no puede ser menor al total pendiente despu├®s de saldo a favor.",
                    "warning",
                )
                return redirect(url_for('caja_pendientes'))

        estado_antes_cobro = venta.estado
        usr_cobro = (current_user.nombre or '')[:120] if current_user.is_authenticated else None

        with transaccion_critica():
            from core.application.bootstrap import build_procesar_cobro_use_case
            from core.application.ventas.commands import ProcesarCobroCommand

            plan_cuotas = None
            if metodo == "Credito":
                plan_cuotas = _plan_cuotas_credito_valido(request.form.get('credito_plan_cuotas'))

            build_procesar_cobro_use_case(transaccion_critica=None).execute(
                ProcesarCobroCommand(
                    venta_id=venta.id,
                    caja_id=caja_activa.id,
                    metodo_pago=metodo,
                    tipo_documento=tipo_doc,
                    monto_recibido=monto_recibido,
                    saldo_favor_usado=saldo_favor_usado,
                    credito_plan_codigo=plan_cuotas,
                    usuario_cobro=usr_cobro,
                )
            )
            venta = Venta.query.options(joinedload(Venta.detalles)).filter_by(id=venta.id).first()
            venta.fecha = datetime.now()

            if metodo == "Credito":
                VentaCuotaCredito.query.filter_by(venta_id=venta.id).delete(synchronize_session=False)
                if plan_cuotas:
                    _registrar_cuotas_credito_venta(venta, plan_cuotas, venta.fecha)
                if venta.cliente:
                    venta.cliente.saldo_deudor = (venta.cliente.saldo_deudor or 0) + venta.monto_total
            else:
                if saldo_favor_usado > 0:
                    _aplicar_mov_saldo_favor(
                        venta.cliente_id,
                        None,
                        'DEBITO',
                        saldo_favor_usado,
                        f'Uso en venta #{venta.id}',
                    )
                if app.config.get('_BODEGA_SUGERIDO_COL_OK'):
                    venta.bodega_sugerido_preparar = 0
                    venta.bodega_sugerido_preparar_at = None
                    venta.bodega_sugerido_preparar_usuario = None
                if app.config.get('_BODEGA_RETIRO_COL_OK') and _punto_retiro_es_bodega(venta):
                    venta.bodega_preparacion_estado = 'PENDIENTE'
                    venta.bodega_preparacion_usuario = None
                    venta.bodega_preparacion_at = None
                    venta.bodega_preparacion_cobrado_at = datetime.now()

            stock_cobro_svc.aplicar_descontos(
                venta.id,
                lineas_stock,
                metodo,
                usr_cobro or (current_user.nombre if current_user.is_authenticated else None),
            )

            _audit_log(
                'cobro_vale',
                'venta',
                venta.id,
                usuario=usr_cobro,
                datos_antes={'estado': estado_antes_cobro, 'metodo_pago': None},
                datos_despues={'estado': venta.estado, 'metodo_pago': metodo, 'tipo_documento': tipo_doc},
            )

        db.session.commit()

        # Facturaci├│n electr├│nica (post-commit): no bloquea cobro; savepoint en servicio revierte folio si falla.
        dte_estado_ui: Optional[str] = None
        fe_mod = None
        if metodo != 'Credito' and getattr(venta, 'estado', None) == 'Pagado':
            from services import facturacion_electronica_service as fe_mod

            v_fe = (
                Venta.query.options(
                    joinedload(Venta.detalles).joinedload(DetalleVenta.producto),
                    joinedload(Venta.cliente),
                )
                .filter_by(id=venta.id)
                .first()
            )
            if v_fe:
                try:
                    dte_estado_ui = fe_mod.post_cobro_emision_fe(
                        db.session,
                        v_fe,
                        Caf,
                        obtener_config_empresa,
                        app.logger,
                        erp_root=app.root_path,
                    )
                    db.session.commit()
                except Exception as ex_fe_post:
                    db.session.rollback()
                    app.logger.exception('FE envoltura post-cobro (persistencia FE): %s', ex_fe_post)
                    if fe_mod.debe_emitir_fe_en_erp(v_fe.tipo_documento):
                        try:
                            fe_mod.marcar_venta_dte_pendiente_envio(
                                v_fe,
                                fe_mod.resolver_dte_tipo_por_tipo_documento(v_fe.tipo_documento),
                            )
                            db.session.commit()
                        except Exception:
                            db.session.rollback()
                        dte_estado_ui = fe_mod.DTE_ESTADO_PENDIENTE_ENVIO
                    else:
                        fe_mod.marcar_venta_boleta_sin_fe_erp(v_fe)
                        db.session.commit()
                        dte_estado_ui = fe_mod.DTE_ESTADO_EXTERNO_BOLETA
                venta = Venta.query.filter_by(id=venta.id).first() or venta

        if metodo == "Credito":
            msg_cred = f"Vale #{venta.id} registrado a cr├®dito para {venta.cliente.nombre if venta.cliente else 'cliente'}."
            if (venta.credito_plan_codigo or '').strip():
                msg_cred += f" Plan: {_mensaje_resumen_plan_cuotas(venta.credito_plan_codigo)}."
            if _cobro_respuesta_json_solicitada():
                return jsonify(
                    {
                        'exito': True,
                        'venta_id': venta.id,
                        'turno': int(getattr(venta, 'prioridad', None) or 0),
                        'vuelto': float(venta.vuelto or 0),
                        'vuelto_fmt': f"${float(venta.vuelto or 0):,.0f}".replace(',', '.'),
                        'monto_total': float(venta.monto_total or 0),
                        'estado': venta.estado,
                        'metodo_pago': metodo,
                        'dte_estado': dte_estado_ui,
                    }
                )
            flash(msg_cred, "success")
            return redirect(url_for('caja_pendientes', ultima_venta=venta.id))
        else:
            msg_fin = f"┬íVenta #{venta.id} finalizada! Vuelto: ${venta.vuelto:,.0f}"
            if (venta.punto_retiro or '').strip().lower() == 'bodega':
                msg_fin += (
                    " Retiro en bodega: el vale aparece en la plataforma de bodega; "
                    "los operadores reciben aviso sonoro en pantalla (consulta cada pocos segundos)."
                )
            if _cobro_respuesta_json_solicitada():
                return jsonify(
                    {
                        'exito': True,
                        'venta_id': venta.id,
                        'turno': int(getattr(venta, 'prioridad', None) or 0),
                        'vuelto': float(venta.vuelto or 0),
                        'vuelto_fmt': f"${float(venta.vuelto or 0):,.0f}".replace(',', '.'),
                        'monto_total': float(venta.monto_total or 0),
                        'monto_total_fmt': f"${float(venta.monto_total or 0):,.0f}".replace(',', '.'),
                        'estado': venta.estado,
                        'metodo_pago': metodo,
                        'dte_estado': dte_estado_ui,
                    }
                )
            flash(msg_fin, "success")
            return redirect(
                url_for(
                    'ver_ticket_cobro',
                    id=venta.id,
                    vuelto=f"{float(venta.vuelto or 0):.2f}",
                    auto_print='1',
                )
            )

    except Exception as e:  # <--- Ahora este except s├¡ tiene su try
        from core.domain.venta.exceptions import VentaDomainError

        db.session.rollback()
        if isinstance(e, VentaDomainError):
            if _cobro_respuesta_json_solicitada():
                return jsonify({'exito': False, 'error': str(e)}), 400
            flash(str(e), 'warning')
            return redirect(url_for('caja_pendientes'))
        app.logger.exception('procesar_cobro_caja FALLO vale #%s: %s', id, e)
        if _cobro_respuesta_json_solicitada():
            return jsonify({'exito': False, 'error': str(e)}), 500
        flash(f"Error cr├¡tico al procesar pago: {str(e)}", "danger")
        return redirect(url_for('caja_pendientes'))


def ver_ticket_cobro(id):
    venta = (
        Venta.query.options(joinedload(Venta.detalles), joinedload(Venta.cuotas_credito))
        .get_or_404(id)
    )
    if venta.estado != 'Pagado':
        flash("El vale de retiro solo está disponible para ventas pagadas.", "warning")
        return redirect(url_for('caja_pendientes'))
    return render_template(
        'ticket_cobro.html',
        venta=venta,
        detalles=venta.detalles or [],
        cajero_nombre=(current_user.nombre or '').strip() if current_user.is_authenticated else '',
        auto_print=(request.args.get('auto_print') == '1'),
        vuelto=float((request.args.get('vuelto') or venta.vuelto or 0)),
    )

def _buscar_productos_json(
    q: str,
    *,
    filtro_pos: str = 'catalogo',
    enriquecido: bool = True,
    out_lim: int | None = None,
):
    """
    Búsqueda unificada POS / cotizaciones (nombre, códigos, marca, stock tienda+bodega).
    Devuelve {'results': [...], 'meta': {...}} compatible con Select2 o tarjetas enriquecidas.
    """
    q = (q or '').strip()
    if len(q) < 2:
        return {'results': [], 'meta': {}}
    if not _asegurar_columnas_productos_legacy():
        return {'results': [], 'meta': {}}

    from services.pos_busqueda_service import (
        construir_badges_semaforo,
        enriquecer_item_busqueda_pos,
        filtrar_productos_por_filtro_pos,
        ordenar_candidatos_busqueda,
    )

    filtro_pos = str(filtro_pos or 'catalogo').lower()
    if filtro_pos not in ('operativo', 'tienda', 'catalogo'):
        filtro_pos = 'catalogo'
    filtro_estricto_stock = filtro_pos in ('operativo', 'tienda')
    fetch_limit = 260 if filtro_estricto_stock else 80

    try:
        insp = sa_inspect(db.engine)
        cols = {c['name'] for c in insp.get_columns('productos')}
        if not {'id', 'nombre'}.issubset(cols):
            return {'results': [], 'meta': {}}

        campos = ['id', 'nombre']
        for c in (
            'codigo_barra', 'codigo_interno', 'codigo_chilemat',
            'precio_venta', 'precio_mayoreo', 'stock', 'unidad', 'unidad_venta',
            'marca', 'fabricante', 'categoria', 'subcategoria',
        ):
            if c in cols:
                campos.append(c)

        dn = (db.engine.dialect.name or '').lower()
        params = {'lim': fetch_limit, 'qplain': q}
        if dn == 'postgresql':
            def _substr_match(col: str) -> str:
                return f"lower(COALESCE({col},'')) LIKE '%' || lower(:qplain) || '%'"
        elif dn in ('mysql', 'mysqldb', 'mariadb'):
            def _substr_match(col: str) -> str:
                return f"LOCATE(lower(:qplain), lower(COALESCE({col},''))) > 0"
        else:
            _substr_match = None

        if _substr_match:
            filtros = [_substr_match('nombre')]
            for c in (
                'codigo_barra', 'codigo_interno', 'codigo_chilemat',
                'marca', 'fabricante', 'categoria', 'subcategoria',
            ):
                if c in cols:
                    filtros.append(_substr_match(c))
        else:
            like = f'%{q}%'
            params['like'] = like
            filtros = ['LOWER(nombre) LIKE LOWER(:like)']
            for c in (
                'codigo_barra', 'codigo_interno', 'codigo_chilemat',
                'marca', 'fabricante', 'categoria', 'subcategoria',
            ):
                if c in cols:
                    filtros.append(f'LOWER({c}) LIKE LOWER(:like)')

        where_parts = [f"({' OR '.join(filtros)})"]
        if 'activo' in cols:
            where_parts.insert(0, '(activo IS NULL OR activo = TRUE)')
        if filtro_estricto_stock:
            precio_exprs = []
            if 'precio_venta' in cols:
                precio_exprs.append('COALESCE(precio_venta, 0)')
            if 'precio_mayoreo' in cols:
                precio_exprs.append('COALESCE(precio_mayoreo, 0)')
            if precio_exprs:
                where_parts.append(f"(({') + ('.join(precio_exprs)}) > 0)")

        if dn == 'postgresql':
            ord_expr = "strpos(lower(COALESCE(nombre,'')), lower(:qplain))"
            ord_suffix = ' ASC NULLS LAST, nombre ASC '
        elif dn in ('mysql', 'mysqldb', 'mariadb'):
            ord_expr = "LOCATE(lower(:qplain), lower(COALESCE(nombre,'')))"
            ord_suffix = ' ASC, nombre ASC '
        else:
            ord_expr = '1'
            ord_suffix = ' ASC, nombre ASC '

        sql = (
            f"SELECT {', '.join(campos)} "
            f"FROM productos "
            f"WHERE {' AND '.join(where_parts)} "
            f"ORDER BY ({ord_expr}){ord_suffix}"
            f'LIMIT :lim'
        )
        productos = db.session.execute(text(sql), params).mappings().all()
    except Exception as ex:
        db.session.rollback()
        app.logger.exception('_buscar_productos_json falló: %s', ex)
        return {'results': [], 'meta': {}}

    pid_list = [int(r['id']) for r in productos if r.get('id') is not None]
    if pid_list:
        stock_t_map, stock_b_map = stock_tienda_bodega_por_producto_ids(pid_list)
    else:
        stock_t_map, stock_b_map = {}, {}

    cfg_emp = obtener_config_empresa()
    n_antes_filtro_stock = len(productos) if productos else 0
    if filtro_estricto_stock and productos:
        productos = filtrar_productos_por_filtro_pos(
            productos, stock_t_map, stock_b_map, filtro_pos, cfg_emp
        )

    if out_lim is None:
        out_lim = 15 if enriquecido else 28

    candidatos = []
    for p in productos:
        pid = int(p.get('id'))
        codigo = (
            (p.get('codigo_barra') or '').strip()
            or (p.get('codigo_interno') or '').strip()
            or (p.get('codigo_chilemat') or '').strip()
        )
        nombre = (p.get('nombre') or '').strip()
        sufijo = codigo if codigo else f'id {pid}'
        if enriquecido:
            st_t = int(stock_t_map.get(pid, 0))
            st_b = int(stock_b_map.get(pid, 0))
            precio = _precio_lista_desde_row_producto(p)
            unidad = (p.get('unidad_venta') or p.get('unidad') or 'un').strip() or 'un'
            item = enriquecer_item_busqueda_pos(
                pid=pid,
                row=p,
                cols=cols,
                stock_tienda=st_t,
                stock_bodega=st_b,
                nombre=nombre,
                codigo=codigo or f'id {pid}',
                precio=precio,
                precio_fmt=_fmt_clp_busqueda_pos(precio),
                marca=_producto_marca_desde_row(p, cols),
                unidad=unidad,
                cfg=cfg_emp,
            )
        else:
            item = {
                'id': str(pid),
                'producto_id': pid,
                'text': f'{nombre} ({sufijo})',
            }
        candidatos.append(item)

    if enriquecido and candidatos:
        precios = [float(c.get('precio') or 0) for c in candidatos]
        pmin, pmax = min(precios), max(precios)
        for c in candidatos:
            c['badges'] = construir_badges_semaforo(c, pmin, pmax)
        candidatos = ordenar_candidatos_busqueda(candidatos)

    meta = {}
    if filtro_estricto_stock and n_antes_filtro_stock > 0 and not candidatos:
        meta['filtrados_por_stock'] = True
    return {'results': candidatos[:out_lim], 'meta': meta}


def _cotizacion_item_desde_busqueda(row: dict) -> dict:
    """Formato plano para agregar línea en formulario cotización."""
    pid = row.get('producto_id') or row.get('id')
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        pid = None
    return {
        'id': pid,
        'codigo': row.get('codigo') or '',
        'nombre': row.get('nombre') or row.get('text') or '',
        'precio': float(row.get('precio') or 0),
        'precio_fmt': row.get('precio_fmt') or _fmt_clp_busqueda_pos(row.get('precio') or 0),
        'unidad': row.get('unidad') or '',
        'stock': int(row.get('stock_total') or 0),
        'stock_tienda': int(row.get('stock_tienda') or 0),
        'stock_bodega': int(row.get('stock_bodega') or 0),
        'semaforo': row.get('semaforo') or '',
        'semaforo_label': row.get('semaforo_label') or '',
        'marca': row.get('marca') or '',
        'badges': row.get('badges') or [],
    }


