def _rut_sin_formato(rut: str) -> str:
    """RUT comparable: solo dígitos + dígito verificador (K mayúscula)."""
    return (rut or '').replace('.', '').replace('-', '').replace(' ', '').upper().strip()


def _rut_variantes_busqueda(rut_raw: str):
    """Cadenas de RUT a probar contra Cliente.rut (evita SQL REPLACE anidado que falla en algunos MySQL)."""
    key = _rut_sin_formato(rut_raw)
    out = {rut_raw.strip(), key}
    if len(key) >= 2:
        cuerpo, dv = key[:-1], key[-1]
        out.add(f"{cuerpo}-{dv}")
        if dv == 'K':
            out.add(f"{cuerpo}-k")
        if cuerpo.isdigit():
            try:
                n = int(cuerpo)
                out.add(f"{n:,}".replace(",", ".") + "-" + dv)
                if dv == 'K':
                    out.add(f"{n:,}".replace(",", ".") + "-k")
            except ValueError:
                pass
    return [x for x in out if x]


def _limpiar_texto_cliente_ui(val):
    """None, vacío o el texto literal 'None'/'null' → None (evita mostrar 'None' en POS y APIs)."""
    if val is None:
        return None
    s = str(val).strip()
    if not s or s.lower() in ('none', 'null', 'undefined', 'nan'):
        return None
    return s


def _aplicar_campos_contacto_cliente(cliente, *, direccion, giro, telefono, correo, comuna, ciudad):
    """Persiste datos de facturación en el maestro cliente (el formulario manda; vacío limpia columna)."""
    d = _limpiar_texto_cliente_ui(direccion)
    cliente.direccion = (d[:200] if d else None)
    g = _limpiar_texto_cliente_ui(giro)
    cliente.giro = (g[:100] if g else None)
    t = _limpiar_texto_cliente_ui(telefono)
    cliente.telefono = (t[:20] if t else None)
    m = _limpiar_texto_cliente_ui(correo)
    cliente.correo = (m[:100] if m else None)
    co = _limpiar_texto_cliente_ui(comuna)
    cliente.comuna = (co[:80] if co else None)
    ci = _limpiar_texto_cliente_ui(ciudad)
    cliente.ciudad = (ci[:80] if ci else None)


@app.route('/consultar_cliente')
@login_required
def consultar_cliente():
    """Busca cliente por RUT tolerando distinto formato guardado en BD (con/sin puntos)."""
    try:
        rut_raw = (request.args.get('rut') or '').strip()
        if not rut_raw:
            return jsonify({'existe': False, 'error': 'sin_rut'}), 400
        key = _rut_sin_formato(rut_raw)
        if len(key) < 8:
            return jsonify({'existe': False, 'error': 'rut_corto'}), 400

        variantes = _rut_variantes_busqueda(rut_raw)
        cliente = Cliente.query.filter(Cliente.rut.in_(variantes)).first()

        if cliente:
            saldo_favor = _saldo_favor_actual(cliente.id)
            payload_cli = {
                'id': int(cliente.id),
                'nombre': cliente.nombre,
                'direccion': _limpiar_texto_cliente_ui(cliente.direccion) or '',
                'giro': _limpiar_texto_cliente_ui(cliente.giro) or '',
                'telefono': _limpiar_texto_cliente_ui(cliente.telefono) or '',
                'correo': _limpiar_texto_cliente_ui(cliente.correo) or '',
                'comuna': _limpiar_texto_cliente_ui(cliente.comuna) or '',
                'ciudad': _limpiar_texto_cliente_ui(cliente.ciudad) or '',
                'saldo_favor': saldo_favor,
            }
            cred = _pos_credito_resumen(cliente)
            if cred:
                payload_cli['credito'] = cred
            return jsonify({
                'existe': True,
                'cliente': payload_cli,
            })
        return jsonify({'existe': False})
    except Exception as ex:
        return jsonify({'existe': False, 'error': 'servidor', 'mensaje': str(ex)}), 500

