@app.route('/kardex')
@permisos_required('ver_inventario', 'admin_inventario', 'gestionar_usuarios')
def kardex():
    pid = request.args.get('producto_id', type=int)
    tipo = (request.args.get('tipo') or '').strip()
    qtext = (request.args.get('q') or '').strip()
    fecha_inicio = (request.args.get('fecha_inicio') or '').strip()
    fecha_fin = (request.args.get('fecha_fin') or '').strip()
    page = request.args.get('page', 1, type=int)
    per_page = 40

    consulta = MovimientoInventario.query.options(
        joinedload(MovimientoInventario.producto)
    ).order_by(MovimientoInventario.fecha.desc(), MovimientoInventario.id.desc())

    if pid:
        consulta = consulta.filter(MovimientoInventario.id_producto == pid)
    if tipo in ('ENTRADA', 'SALIDA', 'AJUSTE'):
        consulta = consulta.filter(MovimientoInventario.tipo_movimiento == tipo)
    if qtext:
        like = f"%{qtext}%"
        consulta = consulta.join(Producto, Producto.id == MovimientoInventario.id_producto).filter(
            or_(
                Producto.nombre.like(like),
                Producto.codigo_barra.like(like),
                MovimientoInventario.motivo.like(like),
            )
        )
    if fecha_inicio:
        try:
            fi = datetime.strptime(fecha_inicio, '%Y-%m-%d')
            consulta = consulta.filter(MovimientoInventario.fecha >= fi)
        except ValueError:
            pass
    if fecha_fin:
        try:
            ff = datetime.strptime(fecha_fin, '%Y-%m-%d') + timedelta(days=1)
            consulta = consulta.filter(MovimientoInventario.fecha < ff)
        except ValueError:
            pass

    pagination = consulta.paginate(page=page, per_page=per_page, error_out=False)
    productos_sel = Producto.query.filter_by(activo=True).order_by(Producto.nombre).limit(800).all()
    return render_template(
        'kardex.html',
        movimientos=pagination.items,
        pagination=pagination,
        productos_sel=productos_sel,
        filtros={
            'producto_id': pid,
            'tipo': tipo,
            'q': qtext,
            'fecha_inicio': fecha_inicio,
            'fecha_fin': fecha_fin,
        },
    )


_OC_ESTADOS_VALIDOS = ('Borrador', 'Enviada', 'Parcial', 'Cerrada', 'Anulada')


def _extraer_seguimientos_oc(observacion, limit=3):
    """Extrae hitos [SEGUIMIENTO ...] desde observación de la OC."""
    raw = (observacion or '').strip()
    if not raw:
        return []
    items = []
    for part in raw.split('|'):
        token = part.strip()
        if not token.startswith('[SEGUIMIENTO '):
            continue
        cierre = token.find(']')
        if cierre == -1:
            continue
        fecha_txt = token[len('[SEGUIMIENTO '):cierre].strip()
        detalle = token[cierre + 1:].strip(' -')
        if detalle:
            items.append({'fecha': fecha_txt, 'detalle': detalle})
    if not items:
        return []
    items.reverse()
    return items[:max(1, int(limit or 1))]


def _ultima_fecha_seguimiento_oc(observacion):
    """Retorna datetime del último [SEGUIMIENTO ...] encontrado en observación."""
    raw = (observacion or '').strip()
    if not raw:
        return None
    ult = None
    for part in raw.split('|'):
        token = part.strip()
        if not token.startswith('[SEGUIMIENTO '):
            continue
        cierre = token.find(']')
        if cierre == -1:
            continue
        fecha_txt = token[len('[SEGUIMIENTO '):cierre].strip()
        dt = None
        for fmt in ('%Y-%m-%d %H:%M', '%Y-%m-%d'):
            try:
                dt = datetime.strptime(fecha_txt, fmt)
                break
            except ValueError:
                continue
        if dt and (ult is None or dt > ult):
            ult = dt
    return ult


def _registrar_seguimiento_oc(oc, estado_seg, nota_seg=''):
    """Agrega un hito de seguimiento a la observación de una OC."""
    estado_seg = (estado_seg or '').strip()[:60]
    nota_seg = (nota_seg or '').strip()[:180]
    if not estado_seg:
        return False
    marca = f"[SEGUIMIENTO {datetime.now().strftime('%Y-%m-%d %H:%M')}] {estado_seg}"
    if nota_seg:
        marca += f" - {nota_seg}"
    obs_prev = (oc.observacion or '').strip()
    if obs_prev:
        oc.observacion = f"{obs_prev} | {marca}"[:500]
    else:
        oc.observacion = marca[:500]
    return True


@app.route('/compras/ordenes')
@permisos_required('gestionar_compras', 'admin_inventario', 'gestionar_usuarios')
def lista_ordenes_compra():
    if not _tablas_orden_compra_existen():
        flash('Ejecute la migración sql/2026_05_03_ordenes_compra.sql en la base de datos.', 'warning')
        return redirect(url_for('inicio'))
    ordenes = (
        OrdenCompra.query.options(
            joinedload(OrdenCompra.proveedor),
            joinedload(OrdenCompra.detalles),
        )
        .order_by(OrdenCompra.id.desc())
        .limit(500)
        .all()
    )
    sin_seg_dias = max(0, int(request.args.get('sin_seg_dias', 0) or 0))
    solo_pendientes = (request.args.get('solo_pendientes', '1') or '1').strip() == '1'
    ahora = datetime.now()
    estados_pendientes = {'Borrador', 'Enviada', 'Parcial'}

    if sin_seg_dias > 0:
        limite = ahora - timedelta(days=sin_seg_dias)
        filtradas = []
        for o in ordenes:
            if solo_pendientes and (o.estado or '') not in estados_pendientes:
                continue
            ult_seg = _ultima_fecha_seguimiento_oc(o.observacion)
            if (ult_seg is None) or (ult_seg < limite):
                filtradas.append(o)
        ordenes = filtradas

    oc_alerta_ids = set()
    for o in ordenes:
        if (o.estado or '') in estados_pendientes:
            ult_seg = _ultima_fecha_seguimiento_oc(o.observacion)
            if not ult_seg or (ahora - ult_seg).days >= 3:
                oc_alerta_ids.add(int(o.id))

    return render_template(
        'ordenes_compra_lista.html',
        ordenes=ordenes,
        sin_seg_dias=sin_seg_dias,
        solo_pendientes=solo_pendientes,
        oc_alerta_ids=oc_alerta_ids,
    )


