@app.route('/compras/ordenes/nueva', methods=['GET', 'POST'])
@login_required
def orden_compra_nueva():
    if not _tablas_orden_compra_existen():
        flash('Ejecute la migración sql/2026_05_03_ordenes_compra.sql', 'warning')
        return redirect(url_for('inicio'))
    proveedores = Proveedor.query.order_by(Proveedor.nombre).all()
    canales_compra_map = obtener_canales_proveedor()
    producto_sugerido_id = request.values.get('producto_id_sugerido', type=int) or request.values.get('producto_id', type=int)
    producto_sugerido = Producto.query.get(producto_sugerido_id) if producto_sugerido_id else None

    sugerencias_payload_raw = (request.values.get('sugerencias_payload') or '').strip()
    sugerencias_multi = []
    if sugerencias_payload_raw:
        try:
            raw_items = json.loads(sugerencias_payload_raw)
            if isinstance(raw_items, list):
                ids = [int(it.get('id')) for it in raw_items if isinstance(it, dict) and str(it.get('id', '')).isdigit()]
                productos_map = {p.id: p for p in Producto.query.filter(Producto.id.in_(ids)).all()} if ids else {}
                for it in raw_items:
                    if not isinstance(it, dict):
                        continue
                    pid = int(it.get('id')) if str(it.get('id', '')).isdigit() else None
                    if not pid or pid not in productos_map:
                        continue
                    try:
                        qty = float(it.get('qty') or 0)
                    except (TypeError, ValueError):
                        qty = 0
                    qty = max(0.0, qty)
                    if qty <= 0:
                        continue
                    sugerencias_multi.append({
                        "producto": productos_map[pid],
                        "cantidad": qty,
                    })
        except Exception:
            sugerencias_multi = []
    proveedor_sugerido_id = None
    if sugerencias_multi and _tablas_orden_compra_existen():
        try:
            ids_productos_ia = [s["producto"].id for s in sugerencias_multi if s.get("producto")]
            if ids_productos_ia:
                filas_prov = (
                    db.session.query(OrdenCompra.proveedor_id, db.func.count(DetalleOrdenCompra.id))
                    .join(DetalleOrdenCompra, DetalleOrdenCompra.orden_compra_id == OrdenCompra.id)
                    .filter(
                        OrdenCompra.proveedor_id.isnot(None),
                        OrdenCompra.estado != 'Anulada',
                        DetalleOrdenCompra.producto_id.in_(ids_productos_ia),
                    )
                    .group_by(OrdenCompra.proveedor_id)
                    .order_by(db.func.count(DetalleOrdenCompra.id).desc(), OrdenCompra.proveedor_id.asc())
                    .all()
                )
                if filas_prov:
                    proveedor_sugerido_id = int(filas_prov[0][0])
        except Exception:
            proveedor_sugerido_id = None

    if request.method == 'POST':
        prov_id = request.form.get('proveedor_id', type=int)
        numero = (request.form.get('numero') or '').strip()[:50]
        if not prov_id or not numero:
            flash('Proveedor y número de OC son obligatorios.', 'warning')
            return render_template(
                'orden_compra_form.html',
                proveedores=proveedores,
                canales_compra_map=canales_compra_map,
                oc=None,
                estados=_OC_ESTADOS_VALIDOS,
                hoy=datetime.now().strftime('%Y-%m-%d'),
                producto_sugerido=producto_sugerido,
                sugerencias_multi=sugerencias_multi,
                sugerencias_payload=sugerencias_payload_raw,
                proveedor_sugerido_id=proveedor_sugerido_id,
            )
        if OrdenCompra.query.filter_by(proveedor_id=prov_id, numero=numero).first():
            flash('Ya existe una orden con ese número para el proveedor.', 'warning')
            return render_template(
                'orden_compra_form.html',
                proveedores=proveedores,
                canales_compra_map=canales_compra_map,
                oc=None,
                estados=_OC_ESTADOS_VALIDOS,
                hoy=datetime.now().strftime('%Y-%m-%d'),
                producto_sugerido=producto_sugerido,
                sugerencias_multi=sugerencias_multi,
                sugerencias_payload=sugerencias_payload_raw,
                proveedor_sugerido_id=proveedor_sugerido_id,
            )
        try:
            fecha_e = datetime.strptime((request.form.get('fecha_emision') or '').strip(), '%Y-%m-%d').date()
        except ValueError:
            fecha_e = datetime.now().date()
        estado = (request.form.get('estado') or 'Borrador').strip()
        if estado not in _OC_ESTADOS_VALIDOS:
            estado = 'Borrador'
        oc = OrdenCompra(
            proveedor_id=prov_id,
            numero=numero,
            fecha_emision=fecha_e,
            estado=estado,
            observacion=(request.form.get('observacion') or '').strip()[:500] or None,
            usuario_creador=(current_user.nombre if current_user.is_authenticated else None),
        )
        if sugerencias_multi:
            marca_ia = f"[IA] Selección asistida ({len(sugerencias_multi)} SKU) {datetime.now().strftime('%Y-%m-%d %H:%M')}"
            obs_prev = (oc.observacion or '').strip()
            if obs_prev:
                oc.observacion = f"{obs_prev} | {marca_ia}"[:500]
            else:
                oc.observacion = marca_ia[:500]
        db.session.add(oc)
        db.session.flush()
        if producto_sugerido:
            db.session.add(
                DetalleOrdenCompra(
                    orden_compra_id=oc.id,
                    producto_id=producto_sugerido.id,
                    cantidad=1,
                    precio_unitario=float(producto_sugerido.precio_compra or 0),
                )
            )
        for s in sugerencias_multi:
            p = s["producto"]
            db.session.add(
                DetalleOrdenCompra(
                    orden_compra_id=oc.id,
                    producto_id=p.id,
                    cantidad=max(1.0, float(s["cantidad"])),
                    precio_unitario=float(p.precio_compra or 0),
                )
            )
        db.session.commit()
        if sugerencias_multi:
            flash(f'Orden de compra creada con {len(sugerencias_multi)} línea(s) sugerida(s) por IA.', 'success')
        else:
            flash('Orden de compra creada. Agregue líneas de productos.', 'success')
        return redirect(url_for('orden_compra_editar', oid=oc.id))
    return render_template(
        'orden_compra_form.html',
        proveedores=proveedores,
        canales_compra_map=canales_compra_map,
        oc=None,
        estados=_OC_ESTADOS_VALIDOS,
        hoy=datetime.now().strftime('%Y-%m-%d'),
        producto_sugerido=producto_sugerido,
        sugerencias_multi=sugerencias_multi,
        sugerencias_payload=sugerencias_payload_raw,
        proveedor_sugerido_id=proveedor_sugerido_id,
    )


@app.route('/compras/ordenes/<int:oid>', methods=['GET', 'POST'])
@login_required
def orden_compra_editar(oid):
    if not _tablas_orden_compra_existen():
        flash('Ejecute la migración sql/2026_05_03_ordenes_compra.sql', 'warning')
        return redirect(url_for('inicio'))
    oc = (
        OrdenCompra.query.options(
            joinedload(OrdenCompra.proveedor),
            joinedload(OrdenCompra.detalles).joinedload(DetalleOrdenCompra.producto),
        ).get_or_404(oid)
    )
    proveedores = Proveedor.query.order_by(Proveedor.nombre).all()
    canales_compra_map = obtener_canales_proveedor()
    canal_oc = canal_compra_proveedor(oc.proveedor_id) if oc.proveedor_id else "manual"
    if request.method == 'POST':
        act = (request.form.get('action') or '').strip()
        try:
            if act == 'guardar_cabecera':
                prov_id = request.form.get('proveedor_id', type=int)
                numero = (request.form.get('numero') or '').strip()[:50]
                if not prov_id or not numero:
                    flash('Proveedor y número son obligatorios.', 'warning')
                else:
                    dup = (
                        OrdenCompra.query.filter(
                            OrdenCompra.proveedor_id == prov_id,
                            OrdenCompra.numero == numero,
                            OrdenCompra.id != oc.id,
                        ).first()
                    )
                    if dup:
                        flash('Otra orden ya usa ese número para el proveedor.', 'warning')
                    else:
                        try:
                            fecha_e = datetime.strptime((request.form.get('fecha_emision') or '').strip(), '%Y-%m-%d').date()
                        except ValueError:
                            fecha_e = oc.fecha_emision
                        estado = (request.form.get('estado') or oc.estado).strip()
                        if estado not in _OC_ESTADOS_VALIDOS:
                            estado = oc.estado
                        oc.proveedor_id = prov_id
                        oc.numero = numero
                        oc.fecha_emision = fecha_e
                        oc.estado = estado
                        oc.observacion = (request.form.get('observacion') or '').strip()[:500] or None
                        db.session.commit()
                        flash('Cabecera actualizada.', 'success')
            elif act == 'registrar_seguimiento':
                estado_seg = (request.form.get('seguimiento_estado') or '').strip()[:60]
                nota_seg = (request.form.get('seguimiento_nota') or '').strip()[:180]
                if not _registrar_seguimiento_oc(oc, estado_seg, nota_seg):
                    flash('Seleccione un estado de seguimiento.', 'warning')
                else:
                    db.session.commit()
                    flash('Seguimiento registrado en la OC.', 'success')
            elif act == 'add_line':
                pid = request.form.get('producto_id', type=int)
                try:
                    cant = float(request.form.get('cantidad', 0) or 0)
                    pu = float(request.form.get('precio_unitario', 0) or 0)
                except (TypeError, ValueError):
                    flash('Cantidad o precio inválidos.', 'warning')
                    return redirect(url_for('orden_compra_editar', oid=oid))
                if not pid or cant <= 0:
                    flash('Seleccione producto y cantidad mayor a cero.', 'warning')
                elif not Producto.query.get(pid):
                    flash('Producto no encontrado.', 'warning')
                else:
                    db.session.add(
                        DetalleOrdenCompra(
                            orden_compra_id=oc.id,
                            producto_id=pid,
                            cantidad=cant,
                            precio_unitario=max(0.0, pu),
                        )
                    )
                    db.session.commit()
                    flash('Línea agregada.', 'success')
            elif act == 'eliminar_linea':
                did = request.form.get('detalle_id', type=int)
                det = DetalleOrdenCompra.query.get(did) if did else None
                if det and det.orden_compra_id == oc.id:
                    db.session.delete(det)
                    db.session.commit()
                    flash('Línea eliminada.', 'success')
            else:
                flash('Acción no reconocida.', 'warning')
        except Exception as ex:
            db.session.rollback()
            flash(f'Error: {ex}', 'danger')
        return redirect(url_for('orden_compra_editar', oid=oid))
    total_estimado = sum(
        (float(d.cantidad or 0) * float(d.precio_unitario or 0)) for d in (oc.detalles or [])
    )
    seguimientos_oc = _extraer_seguimientos_oc(oc.observacion, limit=3)
    return render_template(
        'orden_compra_form.html',
        proveedores=proveedores,
        canales_compra_map=canales_compra_map,
        canal_oc=canal_oc,
        seguimientos_oc=seguimientos_oc,
        oc=oc,
        estados=_OC_ESTADOS_VALIDOS,
        total_estimado=total_estimado,
        hoy=datetime.now().strftime('%Y-%m-%d'),
    )


def _usuario_puede_bodega_voice():
    if not getattr(current_user, 'is_authenticated', False):
        return False
    if _rol_es_administrador_por_nombre(getattr(current_user, 'rol', None)):
        return True
    return usuario_tiene_permiso('bodega_operador')


def _openai_api_key():
    return (os.getenv('OPENAI_API_KEY') or '').strip()


def _bodega_normalizar_busqueda(s):
    t = (s or '').lower().strip()
    for ch in ',.;:-_/\\':
        t = t.replace(ch, ' ')
    return ' '.join(t.split())


def _bodega_score_nombre_vs_query(nombre, query):
    n = _bodega_normalizar_busqueda(nombre)
    q = _bodega_normalizar_busqueda(query)
    if not q or not n:
        return 0
    toks = [x for x in q.split() if len(x) > 1]
    if not toks:
        toks = [q]
    score = 0
    for t in toks:
        if t in n:
            score += 3
        elif any(w.startswith(t) for w in n.split()):
            score += 1
    if q and n.startswith(q[: min(24, len(q))]):
        score += 4
    return score


def _bodega_whisper_transcribe(audio_bytes, filename='audio.webm'):
    key = _openai_api_key()
    if not key:
        return None, 'openai_key_missing'
    try:
        files = {'file': (filename or 'audio.webm', audio_bytes, 'application/octet-stream')}
        data = {'model': 'whisper-1'}
        r = requests.post(
            'https://api.openai.com/v1/audio/transcriptions',
            headers={'Authorization': f'Bearer {key}'},
            files=files,
            data=data,
            timeout=120,
        )
        if not r.ok:
            return None, f'whisper_http_{r.status_code}:{(r.text or "")[:600]}'
        j = r.json()
        return (j.get('text') or '').strip(), None
    except Exception as e:
        return None, str(e)


def _bodega_gpt_parse_comando(transcript):
    key = _openai_api_key()
    if not key:
        return None, 'openai_key_missing'
    system = (
        'Eres un asistente de bodega de ferretería. Tu tarea es extraer: '
        '1. Acción (descontar, verificar stock, marcar despacho), 2. Producto, 3. Cantidad, '
        '4. Número de Vale/Documento. Responde SOLO en JSON con las claves exactas: '
        '"accion", "producto", "cantidad", "numero_vale". '
        'accion en minúsculas: descontar, verificar_stock o marcar_despacho. '
        'cantidad es número o null. numero_vale es número entero o null.'
    )
    try:
        r = requests.post(
            'https://api.openai.com/v1/chat/completions',
            headers={'Authorization': f'Bearer {key}', 'Content-Type': 'application/json'},
            json={
                'model': 'gpt-4o-mini',
                'temperature': 0.1,
                'messages': [
                    {'role': 'system', 'content': system},
                    {'role': 'user', 'content': transcript},
                ],
            },
            timeout=90,
        )
        if not r.ok:
            return None, f'gpt_http_{r.status_code}:{(r.text or "")[:600]}'
        msg = (r.json().get('choices') or [{}])[0].get('message') or {}
        raw = (msg.get('content') or '').strip()
        if not raw:
            return None, 'gpt_empty'
        raw = re.sub(r'^```(?:json)?\s*', '', raw, flags=re.I)
        raw = re.sub(r'\s*```$', '', raw)
        return json.loads(raw), None
    except json.JSONDecodeError as e:
        return None, f'gpt_json:{e}'
    except Exception as e:
        return None, str(e)


def _bodega_parse_cantidad(v):
    if v is None or v == '':
        return None
    try:
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return max(1, v)
        if isinstance(v, float):
            return max(1, int(v))
        s = str(v).strip().replace(',', '.')
        return max(1, int(float(s)))
    except (TypeError, ValueError):
        return None


def _bodega_voice_ejecutar(parsed, usuario_nom):
    """Ejecuta intención parseada por GPT. Retorna dict con ok, speak, wa_sent, error, data."""
    acc = (parsed.get('accion') or '').strip().lower().replace('-', '_')
    acc = re.sub(r'_+', '_', acc.replace(' ', '_')).strip('_')
    prod_q = (parsed.get('producto') or '').strip()
    cant_gpt = _bodega_parse_cantidad(parsed.get('cantidad'))
    vid_raw = parsed.get('numero_vale')
    try:
        vid = int(vid_raw) if vid_raw is not None and str(vid_raw).strip() != '' else None
    except (TypeError, ValueError):
        vid = None

    if acc == 'verificar_stock':
        if not prod_q:
            return {'ok': False, 'error': 'sin_producto', 'speak': 'No entendí qué producto verificar.'}
        pq = prod_q[:80].replace('%', '').replace('_', '')
        q_like = f'%{pq}%'
        hits = (
            Producto.query.filter(Producto.activo == True)
            .filter(db.func.lower(Producto.nombre).like(q_like))
            .order_by(Producto.nombre.asc())
            .limit(8)
            .all()
        )
        if not hits:
            for t in [x for x in _bodega_normalizar_busqueda(prod_q).split() if len(x) >= 3][:3]:
                hits = (
                    Producto.query.filter(Producto.activo == True)
                    .filter(db.func.lower(Producto.nombre).like(f'%{t}%'))
                    .order_by(Producto.nombre.asc())
                    .limit(6)
                    .all()
                )
                if hits:
                    break
        if not hits:
            return {
                'ok': True,
                'data': {'hits': []},
                'speak': f'No encontré producto similar a {prod_q} en el catálogo.',
            }
        lines = []
        for p in hits[:5]:
            st_t = stock_disponible_venta_tienda(p)
            st_b = stock_disponible_bodega(p)
            lines.append(f'{p.nombre}: tienda {st_t}, bodega {st_b}.')
        speak = ' '.join(lines)
        return {'ok': True, 'data': {'hits': [{'id': p.id, 'nombre': p.nombre} for p in hits[:5]]}, 'speak': speak}

    if acc not in ('descontar', 'marcar_despacho'):
        return {
            'ok': False,
            'error': 'accion_no_soportada',
            'speak': 'Acción no reconocida. Decí descontar, verificar stock o marcar despacho.',
        }

    if vid is None:
        return {'ok': False, 'error': 'sin_vale', 'speak': 'Necesito el número de vale o documento.'}
    if not prod_q:
        return {'ok': False, 'error': 'sin_producto', 'speak': 'Necesito el nombre del producto.'}

    venta = Venta.query.options(
        joinedload(Venta.cliente),
        joinedload(Venta.detalles).joinedload(DetalleVenta.producto),
    ).get(vid)
    if not venta:
        return {'ok': False, 'error': 'vale_no_existe', 'speak': f'No existe el vale {vid}.'}
    st = (venta.estado or '').strip()
    mp = venta.metodo_pago
    mp_vacio = mp is None or (isinstance(mp, str) and not str(mp).strip())
    if st != 'Pendiente' or not mp_vacio:
        return {'ok': False, 'error': 'vale_no_cobrable_bodega', 'speak': f'El documento {vid} no está pendiente de cobro en caja.'}

    best_d, best_sc = None, -1
    for d in venta.detalles or []:
        p = d.producto or Producto.query.get(d.id_producto)
        if not p:
            continue
        sc = _bodega_score_nombre_vs_query(p.nombre or '', prod_q)
        if sc > best_sc:
            best_sc, best_d = sc, d
    if not best_d or best_sc < 1:
        return {'ok': False, 'error': 'producto_no_en_vale', 'speak': f'No encontré {prod_q} en el vale {vid}.'}

    producto = best_d.producto or Producto.query.get(best_d.id_producto)
    factor = _factor_venta_a_stock(producto)
    need = int(round((best_d.cantidad or 0) * factor))
    already = _venta_consumo_ya_despachado_bodega(venta, best_d.id)
    remaining = max(0, need - already)
    if remaining <= 0:
        return {'ok': False, 'error': 'linea_ya_despachada', 'speak': f'Esa línea del vale {vid} ya fue despachada por bodega.'}

    if acc == 'marcar_despacho' or cant_gpt is None:
        consumo_delta = remaining
    else:
        pedido = int(round(cant_gpt * factor))
        consumo_delta = min(remaining, max(1, pedido))

    aid_b = id_almacen_bodega()
    if not aid_b or not _tablas_inventario_almacen_existen():
        return {'ok': False, 'error': 'sin_almacen_bodega', 'speak': 'Almacén bodega no configurado.'}

    disp_b = stock_disponible_bodega(producto)
    if disp_b < consumo_delta:
        return {
            'ok': False,
            'error': 'stock_bodega_insuficiente',
            'speak': f'Stock insuficiente en bodega para {producto.nombre}. Hay {disp_b}, se piden {consumo_delta}.',
        }

    datos_antes_dsp = {
        'bodega_despacho_json': getattr(venta, 'bodega_despacho_json', None),
        'bodega_despacho_estado': getattr(venta, 'bodega_despacho_estado', None),
        'detalle_id': best_d.id,
        'consumo_delta': int(consumo_delta),
    }
    wa_digits = None
    wa_body = None
    if venta.cliente:
        wa_digits = _telefono_whatsapp_chile_digits(getattr(venta.cliente, 'telefono', None))
        if wa_digits and len(wa_digits) >= 10:
            uqty = max(1, int(round(consumo_delta / factor))) if factor > 0 else int(consumo_delta)
            wa_body = (
                f'¡Buenas noticias! Tus {uqty} {producto.nombre} acaban de salir de bodega hacia tu domicilio'
            )

    try:
        with transaccion_critica():
            _, err = ajustar_stock_almacen(producto.id, aid_b, -int(consumo_delta))
            if err:
                raise ValueError(err)

            m = _venta_bodega_despacho_map(venta)
            m[str(best_d.id)] = already + int(consumo_delta)
            venta.bodega_despacho_json = json.dumps(m, ensure_ascii=False)
            _refrescar_stock_total_producto(producto)
            _venta_actualizar_estado_despacho_bodega(venta)
            venta.bodega_despacho_ultimo_at = datetime.now()
            stock_validar_invariante_venta(venta)

            registrar_movimiento_kardex(
                producto.id,
                'SALIDA',
                int(consumo_delta),
                f'Despacho bodega vale #{vid} (voz) por {usuario_nom}',
                usuario=usuario_nom,
                id_almacen=aid_b,
                referencia_tipo='venta',
                referencia_id=venta.id,
                stock_saldo=None,
            )
            _audit_log(
                'bodega_despacho_voz',
                'venta',
                venta.id,
                usuario=usuario_nom,
                datos_antes=datos_antes_dsp,
                datos_despues={
                    'bodega_despacho_estado': venta.bodega_despacho_estado,
                    'detalle_id': best_d.id,
                    'consumo_delta': int(consumo_delta),
                },
            )
        db.session.commit()
    except Exception as ex:
        db.session.rollback()
        app.logger.exception('bodega voice commit: %s', ex)
        msg = str(ex) if ex else 'error'
        return {'ok': False, 'error': 'commit', 'speak': f'No se pudo guardar el despacho. {msg[:100]}'}

    wa_ok = False
    if wa_digits and wa_body:
        wa_ok, _det = _whatsapp_cloud_send_text(wa_digits, wa_body)

    out = {
        'ok': True,
        'wa_sent': wa_ok,
        'data': {
            'vale_id': vid,
            'bodega_despacho_estado': venta.bodega_despacho_estado,
            'consumo_delta': consumo_delta,
            'producto': producto.nombre,
        },
    }
    if wa_ok:
        out['speak'] = f'Entendido, vale {vid} actualizado y cliente notificado.'
    else:
        out['speak'] = f'Entendido, vale {vid} actualizado. WhatsApp no enviado al cliente.'
    return out


def _punto_retiro_es_bodega(venta):
    """True si el vale tiene trabajo de retiro en bodega (todo Bodega, o Mixto con líneas Bodega)."""
    if not venta:
        return False
    pr = (getattr(venta, 'punto_retiro', None) or '').strip().lower()
    if pr == 'bodega':
        return True
    if pr == 'mixto' and _pos_retiro_por_linea_empresa():
        for d in venta.detalles or []:
            if (_detalle_punto_retiro_efectivo(d, venta) or '').strip().lower() == 'bodega':
                return True
    return False


def _detalle_pendiente_retiro_bodega_unidades(detalle):
    venta = getattr(detalle, 'venta', None)
    if venta is not None and _pos_retiro_por_linea_empresa():
        if (_detalle_punto_retiro_efectivo(detalle, venta) or '').strip().lower() != 'bodega':
            return 0
    ent = int(getattr(detalle, 'cantidad_entregada_retiro_bodega', None) or 0)
    vend = int(detalle.cantidad or 0)
    return max(0, vend - ent)


def _venta_actualizar_estado_plataforma_retiro(venta):
    if not _punto_retiro_es_bodega(venta):
        return
    if (venta.estado or '').strip() != 'Pagado':
        return
    detalles = list(venta.detalles or [])
    if _pos_retiro_por_linea_empresa():
        detalles = [d for d in detalles if (_detalle_punto_retiro_efectivo(d, venta) or '').strip().lower() == 'bodega']
    if not detalles:
        venta.bodega_preparacion_estado = 'CERRADO'
        venta.bodega_preparacion_cerrado_at = datetime.now()
        return
    if all(_detalle_pendiente_retiro_bodega_unidades(d) <= 0 for d in detalles):
        venta.bodega_preparacion_estado = 'CERRADO'
        venta.bodega_preparacion_cerrado_at = datetime.now()
        return
    if any(int(getattr(d, 'cantidad_entregada_retiro_bodega', None) or 0) > 0 for d in detalles):
        cur = (venta.bodega_preparacion_estado or '').strip()
        if cur != 'CERRADO':
            venta.bodega_preparacion_estado = 'ENTREGA_PARCIAL'


def _bodega_sla_minutos(dt_inicio, dt_fin=None):
    """Calcula minutos entre dos datetimes; si dt_fin es None usa ahora."""
    if not dt_inicio:
        return None
    fin = dt_fin or datetime.now()
    delta = fin - dt_inicio
    return max(0, int(delta.total_seconds() / 60))


_SLA_TIERS = {
    'PENDIENTE':        (5, 10, 20),
    'EN_PREPARACION':   (10, 20, 40),
    'ENTREGA_PARCIAL':  (8, 15, 30),
    'LISTO_RETIRO':     (15, 30, 60),
}


def _bodega_sla_prioridad(minutos, estado):
    """Retorna (tier, css_class, label) segun minutos + estado.

    Tiers: 0=on_track, 1=attention, 2=delayed, 3=critical.
    PENDIENTE escala mas rapido (nadie lo tomo).
    LISTO_RETIRO es tolerante (espera al cliente).
    """
    if minutos is None:
        return 0, 'sla-none', 'Sin dato'
    umbrales = _SLA_TIERS.get((estado or '').strip(), (15, 40, 80))
    if minutos >= umbrales[2]:
        return 3, 'sla-critical', 'Urgente'
    if minutos >= umbrales[1]:
        return 2, 'sla-delayed', 'Demorado'
    if minutos >= umbrales[0]:
        return 1, 'sla-attention', 'Atención'
    return 0, 'sla-ok', 'En tiempo'


def _bodega_enriquecer_vales_sla(vales, ahora=None):
    """Agrega atributos SLA a una lista de vales (para templates)."""
    ahora = ahora or datetime.now()
    for v in vales:
        cob = getattr(v, 'bodega_preparacion_cobrado_at', None)
        mins = _bodega_sla_minutos(cob, ahora) if cob else None
        estado = (v.bodega_preparacion_estado or '').strip()
        tier, css, label = _bodega_sla_prioridad(mins, estado)
        setattr(v, 'sla_min', mins)
        setattr(v, 'sla_tier', tier)
        setattr(v, 'sla_css', css)
        setattr(v, 'sla_label', label)
        setattr(v, 'sla_cobrado_iso', cob.isoformat() if cob else '')


def bodega_cuadro_mando():
    """Cuadro de mando bodega (Fase 3): KPI, SLA, ranking operador, cola, top SKU."""
    _asegurar_columnas_bodega_retiro()
    _asegurar_columnas_bodega_sugerido_preparar()
    _asegurar_columnas_ventas_bodega_despacho()

    _filtro_base_post = and_(
        Venta.estado == 'Pagado',
        _sql_filtro_venta_cola_bodega(),
        Venta.bodega_preparacion_estado.isnot(None),
        Venta.bodega_preparacion_estado != 'CERRADO',
    )

    post_rows = (
        db.session.query(Venta.bodega_preparacion_estado, func.count(Venta.id))
        .filter(_filtro_base_post)
        .group_by(Venta.bodega_preparacion_estado)
        .all()
    )
    conteo_post = {str(r[0] or ''): int(r[1]) for r in post_rows}
    total_post_abiertos = sum(conteo_post.values())

    vales_post_recientes = (
        Venta.query.options(joinedload(Venta.cliente))
        .filter(_filtro_base_post)
        .order_by(Venta.fecha.desc())
        .limit(15)
        .all()
    )
    ahora = datetime.now()
    _bodega_enriquecer_vales_sla(vales_post_recientes, ahora)

    n_pre_cobro = (
        Venta.query.filter(
            Venta.estado == 'Pendiente',
            or_(Venta.metodo_pago.is_(None), Venta.metodo_pago == ''),
            _sql_filtro_venta_cola_bodega(),
        ).count()
    )
    n_pre_cobro_sugerido = (
        Venta.query.filter(
            Venta.estado == 'Pendiente',
            or_(Venta.metodo_pago.is_(None), Venta.metodo_pago == ''),
            _sql_filtro_venta_cola_bodega(),
            Venta.bodega_sugerido_preparar > 0,
        ).count()
    )
    vales_pre_cobro = (
        Venta.query.options(joinedload(Venta.cliente))
        .filter(
            Venta.estado == 'Pendiente',
            or_(Venta.metodo_pago.is_(None), Venta.metodo_pago == ''),
            _sql_filtro_venta_cola_bodega(),
        )
        .order_by(Venta.bodega_sugerido_preparar.desc(), Venta.fecha.asc())
        .limit(24)
        .all()
    )

    # --- SLA: promedio de vales cerrados hoy ---
    hoy_inicio = datetime.combine(date.today(), datetime.min.time())
    cerrados_hoy = (
        Venta.query.filter(
            Venta.estado == 'Pagado',
            _sql_filtro_venta_cola_bodega(),
            Venta.bodega_preparacion_estado == 'CERRADO',
            Venta.bodega_preparacion_cerrado_at >= hoy_inicio,
        ).all()
    )
    sla_tiempos = []
    for v in cerrados_hoy:
        cob = getattr(v, 'bodega_preparacion_cobrado_at', None)
        cer = getattr(v, 'bodega_preparacion_cerrado_at', None)
        if cob and cer:
            sla_tiempos.append(int((cer - cob).total_seconds() / 60))
    sla_promedio_hoy = int(sum(sla_tiempos) / len(sla_tiempos)) if sla_tiempos else None
    sla_max_hoy = max(sla_tiempos) if sla_tiempos else None
    cerrados_hoy_count = len(cerrados_hoy)

    # --- Ranking operador (últimos 7 días) ---
    hace_7d = ahora - timedelta(days=7)
    ranking_rows = (
        db.session.query(
            Venta.bodega_preparacion_usuario,
            func.count(Venta.id),
        )
        .filter(
            Venta.estado == 'Pagado',
            _sql_filtro_venta_cola_bodega(),
            Venta.bodega_preparacion_estado == 'CERRADO',
            Venta.bodega_preparacion_cerrado_at >= hace_7d,
            Venta.bodega_preparacion_usuario.isnot(None),
            Venta.bodega_preparacion_usuario != '',
        )
        .group_by(Venta.bodega_preparacion_usuario)
        .order_by(func.count(Venta.id).desc())
        .limit(10)
        .all()
    )
    ranking_operadores = [{'nombre': r[0], 'cerrados': int(r[1])} for r in ranking_rows]

    # --- Top SKU pendiente ---
    pend_uv = DetalleVenta.cantidad - func.coalesce(DetalleVenta.cantidad_entregada_retiro_bodega, 0)
    agg = (
        db.session.query(DetalleVenta.id_producto, func.sum(pend_uv).label('pend_sum'))
        .join(Venta, Venta.id == DetalleVenta.id_venta)
        .filter(_filtro_base_post, pend_uv > 0)
        .group_by(DetalleVenta.id_producto)
        .order_by(func.sum(pend_uv).desc())
        .limit(18)
        .all()
    )
    top_pendiente_retiro = []
    if agg:
        pids = [int(r[0]) for r in agg if r[0] is not None]
        prods = {p.id: p for p in Producto.query.filter(Producto.id.in_(pids)).all()} if pids else {}
        for pid, pend_sum in agg:
            if pid is None:
                continue
            p = prods.get(int(pid))
            ps = int(pend_sum or 0)
            if not p or ps <= 0:
                continue
            disp = stock_disponible_bodega(p)
            factor = _factor_venta_a_stock(p)
            nec_base = max(1, int(round(ps * factor))) if factor else ps
            top_pendiente_retiro.append(
                {
                    'producto': p,
                    'pendiente_uv': ps,
                    'necesita_base': nec_base,
                    'disp_bodega': disp,
                    'alerta': disp < nec_base,
                }
            )

    tv = getattr(request, '_bodega_tv', False)
    return render_template(
        'bodega_cuadro_mando.html',
        _base_template='base_tv.html' if tv else 'base.html',
        conteo_post=conteo_post,
        total_post_abiertos=total_post_abiertos,
        vales_post_recientes=vales_post_recientes,
        vales_pre_cobro=vales_pre_cobro,
        n_pre_cobro=n_pre_cobro,
        n_pre_cobro_sugerido=n_pre_cobro_sugerido,
        top_pendiente_retiro=top_pendiente_retiro,
        sla_promedio_hoy=sla_promedio_hoy,
        sla_max_hoy=sla_max_hoy,
        cerrados_hoy_count=cerrados_hoy_count,
        ranking_operadores=ranking_operadores,
    )


def bodega_export_dia():
    """Fase 3: export CSV con actividad de bodega del día."""
    hoy_inicio = datetime.combine(date.today(), datetime.min.time())
    vales = (
        Venta.query.options(joinedload(Venta.cliente))
        .filter(
            Venta.estado == 'Pagado',
            _sql_filtro_venta_cola_bodega(),
            Venta.bodega_preparacion_estado.isnot(None),
            or_(
                Venta.bodega_preparacion_cobrado_at >= hoy_inicio,
                and_(
                    Venta.bodega_preparacion_estado != 'CERRADO',
                    Venta.bodega_preparacion_cobrado_at.isnot(None),
                ),
            ),
        )
        .order_by(Venta.id.asc())
        .limit(500)
        .all()
    )
    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow([
        'Vale', 'Cliente', 'Estado', 'Operador',
        'Cobrado', 'Cerrado', 'SLA (min)',
    ])
    for v in vales:
        cob = getattr(v, 'bodega_preparacion_cobrado_at', None)
        cer = getattr(v, 'bodega_preparacion_cerrado_at', None)
        sla = _bodega_sla_minutos(cob, cer) if cob else ''
        writer.writerow([
            v.id,
            v.cliente.nombre if v.cliente else '',
            v.bodega_preparacion_estado or '',
            v.bodega_preparacion_usuario or '',
            cob.strftime('%Y-%m-%d %H:%M') if cob else '',
            cer.strftime('%Y-%m-%d %H:%M') if cer else '',
            sla,
        ])
    output.seek(0)
    fname = f'bodega_{date.today().isoformat()}.csv'
    return Response(
        output.getvalue(),
        mimetype='text/csv',
        headers={'Content-Disposition': f'attachment; filename={fname}'},
    )


def bodega_cuadro_mando_fullscreen():
    """Fase 3: modo TV/kiosk — mismo cuadro de mando sin menú lateral, auto-refresh 30s."""
    request._bodega_tv = True
    return bodega_cuadro_mando()


def api_bodega_retiros_cola_snapshot():
    """Polling JSON: cola de retiros bodega (Pagado + punto Bodega + no CERRADO)."""
    if not current_user.is_authenticated:
        return jsonify({'ok': False, 'error': 'auth'}), 401
    if not usuario_tiene_permiso('bodega_operador'):
        return jsonify({'ok': False, 'error': 'permiso'}), 403
    if not _asegurar_columnas_bodega_retiro():
        return jsonify({'ok': False, 'error': 'schema'}), 500
    rows = (
        db.session.query(Venta.id)
        .filter(
            Venta.estado == 'Pagado',
            _sql_filtro_venta_cola_bodega(),
            Venta.bodega_preparacion_estado.isnot(None),
            Venta.bodega_preparacion_estado != 'CERRADO',
        )
        .order_by(Venta.id.asc())
        .limit(400)
        .all()
    )
    open_ids = [int(r[0]) for r in rows]
    return jsonify({
        'ok': True,
        'count': len(open_ids),
        'open_ids': open_ids,
        'max_id': max(open_ids) if open_ids else None,
    })


