def _audit_bodega_voice_fallo(code, usuario_nom=None, extra=None):
    """Audita fallo de comando de voz sin guardar audio ni transcripción (solo códigos)."""
    if not _asegurar_tabla_erp_audit_log():
        return
    try:
        nom = (usuario_nom or (current_user.nombre if current_user.is_authenticated else '') or 'Bodega')[:120]
        chunk = {'code': str(code or '')[:80]}
        if isinstance(extra, dict):
            for k in ('accion', 'vale_id', 'parse_err', 'exc'):
                if k in extra and extra[k] is not None:
                    val = extra[k]
                    chunk[k] = str(val)[:400] if k in ('parse_err', 'exc') else val
        _audit_log('bodega_voice_fallo', 'bodega_voice', None, usuario=nom, datos_despues=chunk)
        db.session.commit()
    except Exception:
        db.session.rollback()


def _audit_bodega_voice_consulta_ok(accion, usuario_nom=None, extra=None):
    """Audita consulta de voz exitosa sin mutación (p. ej. verificar_stock)."""
    if not _asegurar_tabla_erp_audit_log():
        return
    try:
        nom = (usuario_nom or (current_user.nombre if current_user.is_authenticated else '') or 'Bodega')[:120]
        chunk = {'accion': str(accion or '')[:40]}
        if isinstance(extra, dict):
            for k, v in list(extra.items())[:6]:
                if v is not None:
                    chunk[str(k)[:24]] = v
        _audit_log('bodega_voice_consulta_ok', 'bodega_voice', None, usuario=nom, datos_despues=chunk)
        db.session.commit()
    except Exception:
        db.session.rollback()


def api_bodega_voice_command():
    usuario_nom = (current_user.nombre if current_user.is_authenticated else '') or 'Bodega'
    if not _usuario_puede_bodega_voice():
        _audit_bodega_voice_fallo('sin_permiso', usuario_nom)
        return (
            jsonify({'ok': False, 'error': 'sin_permiso', 'speak': 'No tienes permiso de operador de bodega.'}),
            403,
        )
    if not _asegurar_columnas_ventas_bodega_despacho():
        _audit_bodega_voice_fallo('db_columnas', usuario_nom)
        return jsonify({'ok': False, 'error': 'db_columnas', 'speak': 'Error de base de datos.'}), 500

    if not _openai_api_key():
        _audit_bodega_voice_fallo('openai_key_missing', usuario_nom)
        return jsonify(
            {
                'ok': False,
                'error': 'openai_key_missing',
                'speak': 'Falta configurar la clave Open A I en el servidor.',
            }
        ), 503

    fs = request.files.get('audio') or request.files.get('file')
    if not fs or not (fs.filename or '').strip():
        _audit_bodega_voice_fallo('sin_audio', usuario_nom)
        return jsonify({'ok': False, 'error': 'sin_audio', 'speak': 'No recibí audio.'}), 400
    raw = fs.read()
    if not raw or len(raw) < 256:
        _audit_bodega_voice_fallo('audio_vacio', usuario_nom)
        return jsonify({'ok': False, 'error': 'audio_vacio', 'speak': 'El audio está vacío.'}), 400
    if len(raw) > 6 * 1024 * 1024:
        _audit_bodega_voice_fallo('audio_muy_grande', usuario_nom)
        return jsonify({'ok': False, 'error': 'audio_muy_grande', 'speak': 'El audio es demasiado grande.'}), 400

    fn = secure_filename(fs.filename or '') or 'audio.webm'

    transcript, err = _bodega_whisper_transcribe(raw, fn)
    if err or not transcript:
        _audit_bodega_voice_fallo(err or 'whisper_sin_texto', usuario_nom)
        return jsonify(
            {
                'ok': False,
                'error': err or 'whisper_sin_texto',
                'speak': 'No pude transcribir el audio. Reintentá.',
            }
        ), 502

    parsed, err2 = _bodega_gpt_parse_comando(transcript)
    if err2 or not isinstance(parsed, dict):
        _audit_bodega_voice_fallo(
            'gpt_parse',
            usuario_nom,
            extra={'parse_err': (str(err2)[:400] if err2 else '')},
        )
        return jsonify(
            {
                'ok': False,
                'error': err2 or 'gpt_parse',
                'transcript': transcript,
                'speak': 'Entendí el audio pero no pude interpretar el comando.',
            }
        ), 422

    try:
        out = _bodega_voice_ejecutar(parsed, usuario_nom)
    except Exception as ex:
        db.session.rollback()
        app.logger.exception('api_bodega_voice_command: %s', ex)
        _audit_bodega_voice_fallo('ejecucion', usuario_nom, extra={'exc': str(ex)[:240]})
        return jsonify(
            {
                'ok': False,
                'error': 'ejecucion',
                'transcript': transcript,
                'parsed': parsed,
                'speak': f'Error al ejecutar: {str(ex)[:120]}',
            }
        ), 500

    if out.get('ok'):
        acc_raw = (parsed.get('accion') or '').strip().lower().replace('-', '_')
        acc_raw = re.sub(r'_+', '_', acc_raw.replace(' ', '_')).strip('_')
        if acc_raw == 'verificar_stock':
            n_hits = len((out.get('data') or {}).get('hits') or [])
            _audit_bodega_voice_consulta_ok('verificar_stock', usuario_nom, extra={'hits': n_hits})
    else:
        _audit_bodega_voice_fallo(
            str(out.get('error') or 'negocio'),
            usuario_nom,
            extra={'accion': parsed.get('accion')},
        )

    code = 200 if out.get('ok') else 400
    body = {'ok': out.get('ok'), 'transcript': transcript, 'parsed': parsed, 'speak': out.get('speak')}
    if out.get('error'):
        body['error'] = out['error']
    if out.get('data') is not None:
        body['data'] = out['data']
    if 'wa_sent' in out:
        body['wa_sent'] = out['wa_sent']
    return jsonify(body), code


@app.route('/recepciones')
@permisos_required('gestionar_compras', 'ver_inventario', 'admin_inventario', 'gestionar_usuarios')
def lista_recepciones():
    from services.recepciones_lista_service import (
        ORDEN_FECHA,
        ORDEN_MONTO,
        PER_PAGE_RECEPCIONES,
        query_lista_recepciones,
        resumen_filtros_actuales,
    )
    from services.rcv_sii_import_service import ESTADO_PENDIENTE_ITEMS

    _asegurar_columnas_recepcion_rcv()
    estado_f = (request.args.get('estado') or '').strip()
    anio_f = request.args.get('anio', type=int)
    orden_f = (request.args.get('orden') or ORDEN_FECHA).strip().lower()
    if orden_f not in (ORDEN_FECHA, ORDEN_MONTO):
        orden_f = ORDEN_FECHA
    folio_f = (request.args.get('folio') or '').strip()
    page = max(1, request.args.get('page', 1, type=int))

    q = query_lista_recepciones(
        estado=estado_f or None,
        anio=anio_f if anio_f in (2025, 2026) else None,
        folio=folio_f or None,
        orden=orden_f,
        ocultar_archivado=(estado_f != '__todos__' and estado_f != 'Archivado RCV'),
    )
    pagination = (
        q.options(joinedload(RecepcionCompra.proveedor))
        .paginate(page=page, per_page=PER_PAGE_RECEPCIONES, error_out=False)
    )
    try:
        resumen = resumen_filtros_actuales(estado_f, anio_f)
    except Exception:
        resumen = {'pendiente_items': 0, 'pendiente_items_2026': 0}

    filtros = {
        'estado': estado_f,
        'anio': anio_f,
        'folio': folio_f,
        'orden': orden_f,
        'page': page,
    }
    return render_template(
        'recepciones_lista.html',
        recepciones=pagination.items,
        pagination=pagination,
        filtros=filtros,
        estado_pendiente_items=ESTADO_PENDIENTE_ITEMS,
        resumen=resumen,
        per_page=PER_PAGE_RECEPCIONES,
    )


@app.route('/recepciones/archivar-rcv', methods=['POST'])
@permisos_required('gestionar_compras', 'admin_inventario', 'gestionar_usuarios')
def archivar_recepciones_rcv():
    from services.recepciones_lista_service import archivar_recepciones_lote

    _asegurar_columnas_recepcion_rcv()
    accion = (request.form.get('accion') or '').strip()
    ids_raw = request.form.getlist('recepcion_ids')
    ids = []
    for x in ids_raw:
        try:
            ids.append(int(x))
        except (TypeError, ValueError):
            pass

    if accion == 'anio_2025':
        res = archivar_recepciones_lote(anio=2025)
    elif accion == 'seleccion' and ids:
        res = archivar_recepciones_lote(ids=ids)
    else:
        flash('Acción de archivado no válida.', 'warning')
        return redirect(url_for('lista_recepciones'))

    if not res.get('ok'):
        flash(res.get('error') or 'No se pudo archivar.', 'warning')
    elif res.get('actualizadas', 0) == 0:
        flash('No había recepciones pendientes de ítems para archivar.', 'info')
    else:
        flash(
            f"Se archivaron {res['actualizadas']} recepción(es) como tributario RCV "
            f"(fuera de cola de bodega).",
            'success',
        )
    return redirect(
        url_for(
            'lista_recepciones',
            estado=request.args.get('estado', ''),
            anio=request.args.get('anio', ''),
            folio=request.args.get('folio', ''),
            orden=request.args.get('orden', 'fecha'),
        )
    )


