@app.route('/recepciones/<int:rid>/etiquetas')
@login_required
def imprimir_etiquetas_recepcion(rid):
    rec = RecepcionCompra.query.options(
        joinedload(RecepcionCompra.detalles).joinedload(DetalleRecepcion.producto),
        joinedload(RecepcionCompra.proveedor),
    ).get_or_404(rid)
    ids_raw = (request.args.get('ids') or '').strip()
    ids_set = {int(x) for x in ids_raw.split(',') if x.strip().isdigit()} if ids_raw else set()
    productos = []
    for d in rec.detalles:
        p = d.producto
        if not p:
            continue
        if ids_set and p.id not in ids_set:
            continue
        productos.append(p)
    if not productos:
        flash("No hay etiquetas pendientes para esta recepción.", "info")
        return redirect(url_for('detalle_recepcion', rid=rid))
    return render_template('recepcion_etiquetas.html', recepcion=rec, productos=productos, auto_print=True)


@app.route('/ver_documento/<int:id>')
@login_required
def ver_documento(id):
    # 1. Buscamos la venta en la base de datos
    venta = Venta.query.get_or_404(id)
    
    # 2. Si es Factura, nos aseguramos de que tenga el IVA desglosado
    if venta.tipo_documento == 'Factura' or venta.tipo_documento == '33':
        venta.desglosar_iva() # Usamos la función que creamos en el modelo
        
    # 3. Renderizamos la plantilla pasando los datos de la venta
    return render_template('documento_tributario.html', venta=venta)
# Ruta para descargar el documento tributario en PDF. Similar a 'ver_documento' pero convierte el HTML a PDF usando pdfkit.

@app.route('/descargar_pdf/<int:id>')
@login_required
def descargar_pdf(id):
    # 1. Buscamos la venta y calculamos impuestos
    venta = Venta.query.get_or_404(id)
    venta.desglosar_iva()

    # 2. GENERAMOS EL QR LOCALMENTE (Para evitar errores de red)
    datos_qr = f"Ferreteria-Santo-Domingo|Folio:{venta.id}|Total:{venta.monto_total}"
    qr = qrcode.QRCode(version=1, box_size=10, border=2)
    qr.add_data(datos_qr)
    qr.make(fit=True)
    
    img_qr = qr.make_image(fill_color="black", back_color="white")
    buffered = io.BytesIO()
    img_qr.save(buffered, format="PNG")
    # Convertimos la imagen a texto (base64) para inyectarla en el HTML
    qr_base64 = base64.b64encode(buffered.getvalue()).decode()

    # 3. Renderizamos el HTML pasando la variable del QR
    html = render_template('documento_tributario.html', venta=venta, qr_code=qr_base64)

    # 4. Configuración de wkhtmltopdf para Windows
    path_wkhtmltopdf = r'C:\Program Files\wkhtmltopdf\bin\wkhtmltopdf.exe'
    config = pdfkit.configuration(wkhtmltopdf=path_wkhtmltopdf)

    # 5. Opciones del PDF (Ajustadas para velocidad y sin red)
    options = {
        'page-size': 'Letter',
        'encoding': "UTF-8",
        'margin-top': '0.5in',
        'margin-right': '0.5in',
        'margin-bottom': '0.5in',
        'margin-left': '0.5in',
        'quiet': '', 
        'enable-local-file-access': None,
        'no-outline': None
    }

    # 6. Generación del archivo
    try:
        pdf = pdfkit.from_string(html, False, options=options, configuration=config)
        
        response = make_response(pdf)
        response.headers['Content-Type'] = 'application/pdf'
        response.headers['Content-Disposition'] = f'inline; filename=Factura_FSD_{id}.pdf'
        return response
    except Exception as e:
        return f"Error crítico al generar PDF: {str(e)}"


def _parse_fecha_cartola_txt(txt):
    if not txt or not str(txt).strip():
        return None
    try:
        return datetime.strptime(str(txt).strip()[:10], '%Y-%m-%d').date()
    except ValueError:
        return None


def _cartola_credito_context(cliente_id, fecha_desde_txt, fecha_hasta_txt, orden):
    """Movimientos de crédito (ventas Credito + abonos) para cartola / PDF / boucher."""
    cliente = Cliente.query.get(cliente_id)
    if not cliente:
        return None
    desde_d = _parse_fecha_cartola_txt(fecha_desde_txt)
    hasta_d = _parse_fecha_cartola_txt(fecha_hasta_txt)
    orden = (orden or 'desc').strip().lower()
    if orden not in ('asc', 'desc'):
        orden = 'desc'

    ventas_credito = (
        Venta.query.filter(
            Venta.cliente_id == cliente_id,
            Venta.metodo_pago == 'Credito',
            or_(Venta.estado.is_(None), Venta.estado != 'Anulada'),
        )
        .order_by(Venta.fecha.asc(), Venta.id.asc())
        .all()
    )
    abonos_all = (
        AbonoCredito.query.filter_by(cliente_id=cliente_id)
        .order_by(AbonoCredito.fecha.asc(), AbonoCredito.id.asc())
        .all()
    )

    events = []
    for v in ventas_credito:
        dt = v.fecha or datetime.min
        doc = (v.tipo_documento or 'Vale').strip()
        folio = v.nro_documento
        detalle = f'Venta al crédito ({doc})'
        if folio:
            detalle = f'{detalle} — Folio {folio}'
        events.append(
            (
                dt,
                0,
                v.id,
                'cargo',
                float(v.monto_total or 0),
                f'{doc} #{v.id}',
                detalle,
            )
        )
    for a in abonos_all:
        dt = a.fecha or datetime.min
        mp = (a.metodo_pago or '').strip()
        detalle = (a.comentario or 'Abono a cuenta').strip() or 'Abono a cuenta'
        if mp:
            detalle = f'{detalle} [{mp}]'
        events.append(
            (
                dt,
                1,
                a.id,
                'abono',
                float(a.monto_abono or 0),
                f'Abono #{a.id}',
                detalle,
            )
        )

    events.sort(key=lambda t: (t[0], t[1], t[2]))

    def _fecha_dia(dt):
        return dt.date() if hasattr(dt, 'date') else dt

    opening = 0.0
    for (dt, _tie, _eid, tipo, monto, _ref, _det) in events:
        fd = _fecha_dia(dt)
        if desde_d and fd < desde_d:
            opening += monto if tipo == 'cargo' else -monto

    bal = opening
    mov_chrono = []
    total_cargos = 0.0
    total_abonos = 0.0
    for (dt, _tie, _eid, tipo, monto, ref, detalle) in events:
        fd = _fecha_dia(dt)
        if desde_d and fd < desde_d:
            continue
        if hasta_d and fd > hasta_d:
            continue
        if tipo == 'cargo':
            bal += monto
            total_cargos += monto
        else:
            bal -= monto
            total_abonos += monto
        mov_chrono.append(
            {
                'fecha': dt,
                'tipo': tipo,
                'ref': ref,
                'detalle': detalle,
                'monto': monto,
                'saldo_corriente': bal,
                'saldo_visual': bal,
            }
        )

    movimientos = list(reversed(mov_chrono)) if orden == 'desc' else mov_chrono
    saldo_reconstruido = bal
    saldo_actual = float(cliente.saldo_deudor or 0)
    diferencia_saldo = saldo_reconstruido - saldo_actual

    cuotas_credito_cliente = (
        VentaCuotaCredito.query.options(joinedload(VentaCuotaCredito.venta))
        .join(Venta, Venta.id == VentaCuotaCredito.venta_id)
        .filter(
            Venta.cliente_id == cliente_id,
            Venta.metodo_pago == 'Credito',
            or_(Venta.estado.is_(None), Venta.estado != 'Anulada'),
        )
        .order_by(VentaCuotaCredito.fecha_vencimiento.asc(), VentaCuotaCredito.id.asc())
        .all()
    )

    return {
        'cliente': cliente,
        'movimientos': movimientos,
        'fecha_desde_txt': (fecha_desde_txt or '').strip() or '',
        'fecha_hasta_txt': (fecha_hasta_txt or '').strip() or '',
        'orden': orden,
        'total_cargos': total_cargos,
        'total_abonos': total_abonos,
        'saldo_reconstruido': saldo_reconstruido,
        'saldo_actual': saldo_actual,
        'diferencia_saldo': diferencia_saldo,
        'generado_en': datetime.now(),
        'cuotas_credito_cliente': cuotas_credito_cliente,
        'hoy': date.today(),
    }


def _cartera_exists_venta_antigua_riesgo(cutoff_dt):
    """Heurística cartera: crédito explícito o vale pendiente sin método (aún no pasó por caja)."""
    mp = func.lower(func.coalesce(Venta.metodo_pago, ''))
    return exists().where(
        and_(
            Venta.cliente_id == Cliente.id,
            or_(Venta.estado.is_(None), Venta.estado != 'Anulada'),
            Venta.fecha < cutoff_dt,
            or_(
                Venta.metodo_pago == 'Credito',
                mp == 'credito',
                and_(
                    Venta.estado == 'Pendiente',
                    or_(Venta.metodo_pago.is_(None), Venta.metodo_pago == ''),
                ),
            ),
        )
    )


def _cartera_dashboard_kpis():
    """KPIs operativos + buckets de mora por cuotas vencidas (saldo de cuotas, no necesariamente = saldo cliente)."""
    hoy_d = date.today()
    start_d = datetime.combine(hoy_d, datetime.min.time())
    end_d = datetime.combine(hoy_d, datetime.max.time())
    row_hoy = (
        db.session.query(
            func.count(AbonoCredito.id),
            func.coalesce(func.sum(AbonoCredito.monto_abono), 0.0),
        )
        .filter(AbonoCredito.fecha >= start_d, AbonoCredito.fecha <= end_d)
        .first()
    )
    abonos_hoy_cnt = int(row_hoy[0] or 0)
    abonos_hoy_monto = float(row_hoy[1] or 0.0)

    pend = _sql_cuota_saldo_pendiente()
    rows_venc = (
        db.session.query(pend, VentaCuotaCredito.fecha_vencimiento, Venta.cliente_id)
        .join(Venta, Venta.id == VentaCuotaCredito.venta_id)
        .filter(
            pend > 0.01,
            VentaCuotaCredito.fecha_vencimiento < hoy_d,
            or_(Venta.estado.is_(None), Venta.estado != 'Anulada'),
        )
        .all()
    )
    aging_1_15 = aging_16_30 = aging_31p = 0.0
    ids_cli_cuota_vencida = set()
    for monto_pend, fv, cli_id in rows_venc:
        dias = (hoy_d - fv).days
        m = float(monto_pend or 0)
        if dias <= 15:
            aging_1_15 += m
        elif dias <= 30:
            aging_16_30 += m
        else:
            aging_31p += m
        if cli_id is not None:
            ids_cli_cuota_vencida.add(int(cli_id))
    monto_cuotas_vencidas = aging_1_15 + aging_16_30 + aging_31p

    aging_al_dia = float(
        db.session.query(func.coalesce(func.sum(pend), 0.0))
        .select_from(VentaCuotaCredito)
        .join(Venta, Venta.id == VentaCuotaCredito.venta_id)
        .filter(
            pend > 0.01,
            VentaCuotaCredito.fecha_vencimiento >= hoy_d,
            or_(Venta.estado.is_(None), Venta.estado != 'Anulada'),
        )
        .scalar()
        or 0.0
    )

    cut_susp = hoy_d - timedelta(days=15)
    ids_suspendidos = set()
    for r in (
        db.session.query(Venta.cliente_id)
        .join(VentaCuotaCredito, VentaCuotaCredito.venta_id == Venta.id)
        .filter(
            Venta.cliente_id.isnot(None),
            pend > 0.01,
            VentaCuotaCredito.fecha_vencimiento < cut_susp,
            or_(Venta.estado.is_(None), Venta.estado != 'Anulada'),
        )
        .distinct()
        .all()
    ):
        if r[0] is not None:
            ids_suspendidos.add(int(r[0]))

    return {
        'abonos_hoy_cnt': abonos_hoy_cnt,
        'abonos_hoy_monto': abonos_hoy_monto,
        'aging_al_dia': aging_al_dia,
        'aging_1_15': aging_1_15,
        'aging_16_30': aging_16_30,
        'aging_31p': aging_31p,
        'monto_cuotas_vencidas': monto_cuotas_vencidas,
        'n_clientes_cuota_vencida': len(ids_cli_cuota_vencida),
        'ids_suspendidos': ids_suspendidos,
    }


@app.route('/creditos')
@login_required
@caja_requerida
@permisos_required('ver_creditos_cartera', 'caja_cobrar_vale', 'gestionar_usuarios')
def modulo_creditos():
    vista = (request.args.get('vista') or 'ultimos').strip().lower()
    if vista == 'todos':
        vista = 'abonos'
    if vista not in ('ultimos', 'abonos', 'cartera', 'alerta'):
        vista = 'ultimos'

    clientes = Cliente.query.filter(Cliente.saldo_deudor > 0).order_by(Cliente.nombre.asc()).all()

    q_abonos = (
        AbonoCredito.query.options(joinedload(AbonoCredito.cliente))
        .order_by(AbonoCredito.fecha.desc())
    )
    if vista in ('ultimos', 'abonos'):
        lim_abonos = 900 if vista == 'abonos' else 25
        ultimos_abonos = q_abonos.limit(lim_abonos).all()
    else:
        ultimos_abonos = []

    total_cartera_credito = float(
        db.session.query(func.coalesce(func.sum(Cliente.saldo_deudor), 0.0))
        .filter(Cliente.saldo_deudor > 0)
        .scalar()
        or 0.0
    )

    # Clientes con deuda y documento "en riesgo" (crédito explícito o vale pendiente sin método, antiguo).
    dias_alerta_credito = 45
    cutoff = datetime.now() - timedelta(days=dias_alerta_credito)
    existe_venta_antigua = _cartera_exists_venta_antigua_riesgo(cutoff)
    ids_alerta = {
        row[0]
        for row in db.session.query(Cliente.id)
        .filter(Cliente.saldo_deudor > 0)
        .filter(existe_venta_antigua)
        .all()
    }
    n_credito_alert = len(ids_alerta)

    limite_cuotas = date.today() + timedelta(days=7)
    pend_cv = _sql_cuota_saldo_pendiente()
    n_cuotas_por_vencer = int(
        db.session.query(func.count(VentaCuotaCredito.id))
        .select_from(VentaCuotaCredito)
        .join(Venta, Venta.id == VentaCuotaCredito.venta_id)
        .filter(
            Venta.metodo_pago == 'Credito',
            pend_cv > 0.01,
            VentaCuotaCredito.fecha_vencimiento <= limite_cuotas,
            or_(Venta.estado.is_(None), Venta.estado != 'Anulada'),
        )
        .scalar()
        or 0
    )

    if vista == 'alerta':
        clientes_cartera = [c for c in clientes if c.id in ids_alerta]
    elif vista == 'cartera':
        clientes_cartera = clientes
    else:
        clientes_cartera = []

    dash = _cartera_dashboard_kpis()
    n_cobranza_sin_enviar = 0
    if _asegurar_tabla_cobranza_whatsapp_log():
        try:
            n_cobranza_sin_enviar = _cobranza_sin_enviar_hoy_count()
        except Exception:
            app.logger.exception('No se pudo calcular badge cobranza WhatsApp')
    c360_proyeccion_cupo = 0
    if _asegurar_columnas_customer_360_legacy():
        try:
            c360_proyeccion_cupo = _c360_sum_cupo_sugerido_clientes_activos()
        except Exception:
            app.logger.exception('No se pudo sumar proyección Customer 360')
    return render_template(
        'modulo_creditos.html',
        clientes=clientes,
        ultimos_abonos=ultimos_abonos,
        filtro_vista=vista,
        total_cartera_credito=total_cartera_credito,
        n_credito_alert=n_credito_alert,
        dias_alerta_credito=dias_alerta_credito,
        n_cuotas_por_vencer=n_cuotas_por_vencer,
        clientes_cartera=clientes_cartera,
        ids_alerta=ids_alerta,
        ids_alerta_list=sorted(ids_alerta),
        cartera_dash=dash,
        n_cobranza_sin_enviar=n_cobranza_sin_enviar,
        c360_proyeccion_cupo=c360_proyeccion_cupo,
    )


