@app.route('/api/cotizaciones/buscar_clientes')
@login_required
def cotizaciones_api_buscar_clientes():
    """Busqueda de clientes existentes para autocompletar la cabecera de la cotizacion."""
    q = (request.args.get('q') or '').strip()
    if len(q) < 2:
        return jsonify(items=[])
    like = f"%{q.lower()}%"
    clientes = (
        Cliente.query
        .filter(
            db.or_(
                db.func.lower(Cliente.nombre).like(like),
                Cliente.rut.ilike(f"%{q}%"),
                Cliente.telefono.ilike(f"%{q}%"),
                db.func.lower(Cliente.correo).like(like),
            )
        )
        .order_by(Cliente.nombre.asc())
        .limit(15)
        .all()
    )
    items = []
    for c in clientes:
        try:
            cupo = float(c.cupo_disponible or 0)
        except Exception:
            cupo = 0.0
        items.append({
            'id': c.id,
            'rut': c.rut or '',
            'nombre': c.nombre or '',
            'giro': _limpiar_texto_cliente_ui(c.giro) or '',
            'direccion': _limpiar_texto_cliente_ui(c.direccion) or '',
            'comuna': _limpiar_texto_cliente_ui(c.comuna) or '',
            'ciudad': _limpiar_texto_cliente_ui(c.ciudad) or '',
            'telefono': _limpiar_texto_cliente_ui(c.telefono) or '',
            'correo': _limpiar_texto_cliente_ui(c.correo) or '',
            'estado_credito': c.estado_credito or 'Activo',
            'saldo_deudor': float(c.saldo_deudor or 0),
            'limite_credito': float(c.limite_credito or 0),
            'cupo_disponible': cupo,
        })
    return jsonify(items=items)


@app.route('/api/creditos/buscar_deudores')
@login_required
@caja_requerida
def creditos_api_buscar_deudores():
    """Autocompletar clientes con saldo deudor (módulo cartera) por nombre o RUT mientras se escribe."""
    q_raw = (request.args.get('q') or '').strip()
    if not q_raw:
        return jsonify(results=[])
    q_lower = q_raw.lower()
    like_nombre = f"%{q_lower}%"
    like_rut = f"%{q_raw}%"
    q_digits = ''.join(ch for ch in q_raw if ch.isdigit())
    partes = [
        func.lower(Cliente.nombre).like(like_nombre),
        Cliente.rut.ilike(like_rut),
    ]
    if len(q_digits) >= 2:
        partes.append(Cliente.rut.ilike(f"%{q_digits}%"))
    rows = (
        Cliente.query.filter(Cliente.saldo_deudor > 0, or_(*partes))
        .order_by(Cliente.nombre.asc())
        .limit(40)
        .all()
    )
    results = []
    for c in rows:
        saldo = float(c.saldo_deudor or 0)
        rut = (c.rut or '').strip()
        nombre = (c.nombre or '').strip()
        monto_txt = f"${saldo:,.0f}".replace(",", ".")
        results.append(
            {
                'id': c.id,
                'text': f'{nombre} — {rut} — {monto_txt}',
                'saldo_deudor': saldo,
                'rut': rut,
            }
        )
    return jsonify(results=results)


